\label{T: comparison dirichlet} Let $\varphi$ be a Finsler norm in $\mathbb{R}^{d}$ and assume that $c: \mathbb{R}^{d} \to [0,+\infty)$ is such that $\sqrt{c}$ is uniformly Lipschitz continuous.  Given any bounded open set $U \subseteq \mathbb{R}^{d}$ and any bounded continuous function $f : U \to \mathbb{R}$, if $u \in USC(\overline{U})$ and $v \in LSC(\overline{U})$ are such that
		\begin{gather*}
			u - c(x) G_{\varphi}^{*}(Du,D^{2}u) \leq f(x) \quad \text{in} \, \, U, \quad v - c(x) G_{*}^{\varphi}(Dv,D^{2}v) \geq f(x) \quad \text{in} \, \, U,  \quad \text{and} \\
			u \leq v \quad \text{on} \, \, \partial U,
		\end{gather*}
	then
		\begin{equation*}
			u \leq v \quad \text{in} \, \, U.
		\end{equation*}
	Further, for any $g \in C(\partial U)$, there is a unique  $u \in C(\overline{U})$ satisfying \eqref{E: finsler dirichlet with zeroth order} with $u = g$ on $\partial U$, and $u \in C^{\alpha}_{\text{loc}}(U)$ for any $\alpha \in (0,1)$.

\label{D: cone comparison} Given an open set $U \subseteq \mathbb{R}^{d}$, an upper semicontinuous function $u \in USC(U)$ is said to satisfy \emph{comparison with cones from above} if, for any open $V \subset \subset U$, any $v \in \mathbb{R}^{d} \setminus V$, and any $\lambda > 0$,
		\begin{equation*}
			\max \left\{u(x) - \lambda \varphi(x - v) \, \mid \, x \in \overline{V} \right\} = \max \left\{ u(x) - \lambda \varphi(x - v) \, \mid \, x \in \partial V \right\}.
		\end{equation*}
	In this case, one writes $u \in CCA_{\varphi}(U)$.

Analogously, a lower semicontinuous function $v \in LSC(U)$ is said to satisfy \emph{comparison with cones from below} if, for any open $V \subset \subset U$, any $v \in \mathbb{R}^{d} \setminus V$, and any $\lambda > 0$, 
	\begin{equation*}
		\min \left\{v(x) + \lambda \varphi(v - x) \, \mid \, x \in \overline{V} \right\} = \min \left\{ v(x) + \lambda \varphi(v - x) \, \mid \, x \in \partial V \right\}.
	\end{equation*}
In this case, one writes $v \in CCB_{\varphi}(U)$.

\label{T: equivalent conditions} Fix an open set $U \subseteq \mathbb{R}^{d}$.  Given any continuous function $u : U \to \mathbb{R}$, the following are equivalent:
		\begin{itemize}
			\item[(i)] $u \in W^{1,\infty}_{\text{loc}}(U)$ and $u$ is an absolute minimizer of $\text{Lip}_{\varphi}(\cdot \, ; \overline{V})$ (i.e., \eqref{E: lipschitz min} holds) for any open $V \subset \subset U$;
			\item[(ii)] $u \in W^{1,\infty}_{\text{loc}}(U)$ and $u$ is an absolute minimizer of $\|\varphi^{*}(D(\cdot))\|_{L^{\infty}(V)}$ (i.e., \eqref{E: linfty min} holds) for any open $V \subset \subset U$; and
			\item[(iii)] $u \in CCA_{\varphi}(U) \cap CCB_{\varphi}(U)$.
		\end{itemize}

In addition to the equivalences (i), (ii), and (iii) stated above, $\varphi$-AMLE are characterized by the following condition:
		\begin{itemize}
			\item[(iv)] $u \in \text{Sub}_{\varphi}(U) \cap \text{Super}_{\varphi}(U)$.
		\end{itemize}

\label{T: old comparison} Let $\varphi$ be a Finsler norm.  Given any bounded open set $U \subseteq \mathbb{R}^{d}$, if $u \in USC(U)$ and $v \in LSC(U)$ satisfy
		\begin{equation*}
			u \in CCA_{\varphi}(U) \quad \text{and} \quad v \in CCB_{\varphi}(U),
		\end{equation*}
	then
		\begin{equation} \label{E: comparison of AMLE}
			\max\left\{ u(x) - v(x) \, \mid \, x \in \overline{U} \right\} = \max \left\{ u(x) - v(x) \, \mid \, x \in \partial U\right\}.
		\end{equation}
	In particular, given any uniformly Lipschitz $g \in C(\partial U)$, there is a unique $\varphi$-AMLE minimizer of \eqref{E: minimal lipschitz extension}.

\label{P: strongly superharmonic} If $\varphi$ is a Finsler norm in $\mathbb{R}^{d}$, then 
		\begin{equation} \label{E: strongly superharmonic}
			-G_{\varphi}^{*}(D\varphi,D^{2}\varphi) \geq 0 \quad \text{in the viscosity sense in} \quad \mathbb{R}^{d} \setminus \{0\}.
		\end{equation}

\label{P: strictly convex game} If $\varphi$ is a Finsler norm in $\mathbb{R}^{d}$ for which the unit ball $\{\varphi \leq 1\}$ is both of class $C^{1,1}$ and strictly convex, then there is a family of convex positively one-homogeneous functions $\{\psi_{x}\}_{x \in \mathbb{R}^{d} \setminus \{0\}}$ with the following properties:
		\begin{itemize}
			\item[(i)] $\psi_{x}$ is smooth in a neighborhood of $x$; 
			\item[(ii)] $\varphi \leq \psi_{x}$ pointwise in $\mathbb{R}^{d}$ and $\varphi(x) = \psi_{x}(x)$; and
			\item[(iii)] at the point $x$, the following identities hold:
				\begin{equation*}
					G_{*}^{\varphi}(D\psi_{x}(x),D^{2}\psi_{x}(x)) = G_{\varphi}^{*}(D\psi_{x}(x), D^{2}\psi_{x}(x)) = 0.
				\end{equation*}
		\end{itemize}

\label{T: regularized_norm} If $\varphi$ is any Finsler norm in $\mathbb{R}^{d}$, then there is a family of Finsler norms $(\varphi_{\zeta})_{\zeta > 0} \subseteq C^{1,1}_{\text{loc}}(\mathbb{R}^{d} \setminus \{0\})$ along with constants $\kappa(\varphi), \delta(\varphi) > 0$ such that
	\begin{equation*}
		\lim_{\zeta \to 0^{+}} \varphi_{\zeta} = \varphi \quad \text{locally uniformly in} \, \, \mathbb{R}^{d}
	\end{equation*} 
and, for any $\zeta \in (0,1)$, the following properties hold:
		\begin{itemize}
			\item[(i)] $\{\varphi_{\zeta} \leq 1\}$ satisfies a uniform interior ball condition with radius $\zeta$; 
			\item[(ii)] for any $p \in \mathbb{R}^{d} \setminus \{0\}$, 
				\begin{equation} \label{E: subdifferential version of infinity harmonic}
					\partial \varphi_{\zeta}^{*}(p) = \partial \varphi^{*}(p) + \frac{\zeta p}{\|p\|};
				\end{equation}
			\item[(iii)] $\varphi_{\zeta} \leq \varphi$ pointwise in $\mathbb{R}^{d}$;
			\item[(iv)] the following gradient bound holds:
				\begin{equation*}
			\varphi^{*}(D\varphi_{\zeta}(x)) \geq \kappa(\varphi) \quad \text{for each} \quad x \in \mathbb{R}^{d} \setminus \{0\}; \quad \text{and}
				\end{equation*} 
			\item[(v)] the following nondegeneracy condition holds:
				\begin{equation} \label{E: nondegeneracy condition zeta}
					\overline{B}_{\delta(\varphi)}(0) \subseteq \{\varphi_{\zeta} \leq 1\} \subseteq \overline{B}_{\delta(\varphi)^{-1}}(0).
				\end{equation}
		\end{itemize}

Although it is well-known that $\varphi$ is itself infinity harmonic,\footnote{See \cite[Section 1.4]{aronsson_crandall_juutinen} or \cite[Lemma 3.5 and Proposition 4.7]{armstrong_crandall_julin_smart}.} Proposition \ref{P: strongly superharmonic} appears to be new.  It strengthens an observation from \cite{m_souganidis}: if $\varphi$ is $C^{2}$ away from the origin (or, equivalently, if $\{\varphi \leq 1\}$ is of class $C^{2}$), then
		\begin{equation*}
			-G_{\varphi}^{*}(D\varphi(x),D^{2}\varphi(x)) = -G_{*}^{\varphi}(D\varphi(x),D^{2}\varphi(x)) = 0 \quad \text{for each} \quad x \in \mathbb{R}^{d} \setminus \{0\}.
		\end{equation*}

Given an open set $U \subseteq \mathbb{R}^{d}$, an upper semicontinuous function $u \in USC(U)$ is said to satisfy the differential inequality 
		\begin{equation*}
			-\mathcal{F}(x,u,Du,D^{2}u) \leq 0 \quad \text{in the viscosity sense in} \, \, U,
		\end{equation*}
	if the following condition is satisfied: for any $x_{0} \in U$, and any smooth function $\varphi$ defined in a neighborhood of $x_{0}$, if $u - \varphi$ has a local maximum at $x_{0}$, then
		\begin{equation*}
			-\mathcal{F}(x_{0},u(x_{0}),D\varphi(x_{0}),D^{2}\varphi(x_{0})) \leq 0.
		\end{equation*}
	Alternatively, in this case, $u$ is referred to as a \emph{viscosity subsolution} of the equation $-\mathcal{F}(x,w,Dw,D^{2}w) = 0$ in $U$.

Given an open set $U \subseteq \mathbb{R}^{d}$, a lower semicontinuous function $v \in LSC(U)$ is said to satisfy the differential inequality 
		\begin{equation*}
			-\mathcal{F}(x,v,Dv,D^{2}v) \geq 0 \quad \text{in the viscosity sense in} \, \, U,
		\end{equation*}
	if the following condition is satisfied: for any $x_{0} \in U$, and any smooth function $\varphi$ defined in a neighborhood of $x_{0}$, if $v - \varphi$ has a local minimum at $x_{0}$, then
		\begin{equation*}
			-\mathcal{F}(x_{0},v(x_{0}),D\varphi(x_{0}),D^{2}\varphi(x_{0})) \geq 0.
		\end{equation*}
	Alternatively, in this case, $v$ is referred to as a \emph{viscosity supersolution} of the equation $-\mathcal{F}(x,w,Dw,D^{2}w) = 0$ in $U$.

Fix $x_{0} \in \mathbb{R}^{d} \setminus \{0\}$ and let $\psi$ be a smooth function defined in a neighborhood of $x_{0}$.  Suppose that $\varphi - \psi$ has a local minimum at $x_{0}$.  

After a Taylor expansion at $x_{0}$, one finds
	\begin{equation} \label{E: taylor part}
		\varphi(x) \geq \varphi(x_{0}) + \langle D\psi(x_{0}), x - x_{0} \rangle + \frac{1}{2} \langle D^{2}\psi(x_{0})(x - x_{0}), x - x_{0} \rangle + o(\|x - x_{0}\|^{2}).
	\end{equation}
From this, it readily follows that $D\psi(x_{0}) \in \partial \varphi(x_{0})$, hence, by \eqref{E: subdifferential basic identity} and \eqref{E: inversion},
	\begin{gather}
		\varphi^{*}(D\psi(x_{0})) = 1, \quad \varphi^{*}(x_{0})^{-1} x_{0} \in \partial \varphi^{*}(D\psi(x_{0})), \quad \text{and} \nonumber \\
		\langle D\psi(x_{0}), q \rangle = 1 \quad \text{for each} \quad q \in \partial \varphi^{*}(D\psi(x_{0})). \label{E: useful subdifferential part 1}
	\end{gather}
Notice that this implies $x_{0} \in \mathcal{C}(\partial \varphi^{*}(D\psi(x_{0})))$.

Consider the cone $\mathcal{C}(\partial \varphi^{*}(D\psi(x_{0})))$ determined by the direction $D\psi(x_{0})$.  Observe that $\varphi$ is linear in $\mathcal{C}(\partial \varphi^{*}(D\psi(x_{0})))$, that is,
	\begin{equation} \label{E: linear thing}
		\varphi(x) = \langle D\psi(x_{0}), x \rangle \quad \text{for each} \quad x \in \mathcal{C}(\partial \varphi^{*}(D\psi(x_{0}))).
	\end{equation}
Indeed, if $q \in \partial \varphi^{*}(D\psi(x_{0}))$ and $\lambda \geq 0$, then \eqref{E: subdifferential basic identity dual} and \eqref{E: useful subdifferential part 1} together imply
	\begin{equation*}
		\varphi(\lambda q) = \lambda \varphi(q) = \lambda = \lambda \langle q, D\psi(x_{0}) \rangle = \langle \lambda q, D\psi(x_{0}) \rangle.
	\end{equation*}
Now \eqref{E: linear thing} follows from this and the definition of $\mathcal{C}(\partial \varphi^{*}(D\psi(x_{0})))$.

Next, notice that if $q \in \partial \varphi^{*}(D\psi(x_{0}))$ and $t > 0$, then $x_{0} + t q \in \mathcal{C}(\partial \varphi^{*}(D\psi(x_{0})))$.  This is immediate from \eqref{E: cone thing} since $\{x_{0}\} \cup \partial \varphi^{*}(D\psi(x_{0})) \subseteq \mathcal{C}(\partial \varphi^{*}(D\psi(x_{0})))$.

Finally, setting $x = x_{0} + tq$ with $t > 0$ and $q \in \partial \varphi^{*}(D\psi(x_{0}))$, the identity \eqref{E: linear thing} combines with \eqref{E: taylor part} and \eqref{E: useful subdifferential part 1} to yield
	\begin{align*}
		\varphi(x_{0}) + t = \varphi(x_{0} + t q) &\geq \varphi(x_{0}) + t\langle D\psi(x_{0}), q \rangle + \frac{t^{2}}{2} \langle D^{2}\psi(x_{0})q, q \rangle + o(t^{2}) \\
			&= \varphi(x_{0}) + t + \frac{t^{2}}{2} \langle D^{2}\psi(x_{0}) q, q \rangle + o(t^{2}).
	\end{align*}
This proves that 
	\begin{equation*}
		- \langle D^{2}\psi(x_{0}) q, q \rangle \geq 0,
	\end{equation*}
and, thus, by the arbitrariness of $q$ and the definition \eqref{E: upper def operator} of $G_{\varphi}^{*}$,
	\begin{equation*}
		- G^{*}_{\varphi}(D\psi(x_{0}),D^{2}\psi(x_{0})) = \min \left\{ -\langle D^{2}\psi(x_{0})q, q \rangle \, \mid \, q \in \partial \varphi^{*}(D\psi(x_{0})) \right\} \geq 0.
	\end{equation*}

\label{L: strict subharmonic} Fix an open set $U \subseteq \mathbb{R}^{d}$, an $x_{0} \in U$, and a Finsler norm $\varphi : \mathbb{R}^{d} \to [0,+\infty)$.  If $u$ is a bounded upper semicontinuous function in $U$ such that $-G_{\varphi}^{*}(Du,D^{2}u) \leq 0$ in $U$ and $V \subset \subset U$, then there is a constant $\epsilon_{*} = \epsilon_{*}(u,V) > 0$ such that if $(u^{\epsilon})_{\epsilon > 0}$ are defined by 
		\begin{equation} \label{E: strictness}
			u^{\epsilon}(x) = u(x) + \frac{\epsilon}{2} u(x)^{2},
		\end{equation}
	then, for each $\epsilon \in (0,\epsilon_{*})$,
		\begin{equation*}
			\frac{1}{2} \epsilon \varphi^{*}(Du^{\epsilon})^{2} -G_{\varphi}^{*}(Du^{\epsilon},D^{2}u^{\epsilon})  \leq 0 \quad \text{in} \, \, V.
		\end{equation*}

First, suppose that $u$ is $C^{2}$.  With $u^{\epsilon}$ as defined above, one differentiates to find, for all $x$ such that $1 + \epsilon u(x) > 0$,
				\begin{equation*}
					\varphi^{*}(Du^{\epsilon}(x)) = (1 + \epsilon u(x)) \varphi^{*}(Du(x)), \quad D^{2}u^{\epsilon}(x) = (1 + \epsilon u(x)) D^{2} u(x) + \epsilon Du(x) \otimes Du(x),
				\end{equation*}
			hence, by \eqref{E: subdifferential basic identity dual} and the definition \eqref{E: upper def operator},
				\begin{align*}
					-G_{\varphi}^{*}(Du^{\epsilon}(x),D^{2}u^{\epsilon}(x)) &= -\epsilon \varphi^{*}(Du(x))^{2} - (1 + \epsilon u(x)) G_{\varphi}^{*}(Du(x),D^{2}u(x)) \\
						&\leq -\epsilon (1 + \epsilon u(x))^{-2} \varphi^{*}(Du^{\epsilon}(x))^{2}.
				\end{align*}
			In particular, if $\epsilon$ is small enough,
				\begin{equation*}
					\frac{1}{2} \epsilon \varphi^{*}(Du^{\epsilon}(x))^{2} -G_{\varphi}^{*}(Du^{\epsilon}(x),D^{2}u^{\epsilon}(x)) \leq 0.
				\end{equation*}

			In general, even if $u$ is not $C^{2}$, one argues by passing the derivatives onto the test function and observing that, for any $\epsilon$ small enough, the transformation $s \mapsto s + \frac{\epsilon}{2} s^{2}$ restricts to a diffeomorphism in a neighborhood of the range of $u$.\footnote{Cf.~ Proof of \cite[Theorem 2.8]{evans_spruck}.}

The proof proceeds by contradiction. Fix an open set $V \subset \subset U$.  Suppose that there is a point $x_{0} \in V$, constants $\lambda,\mu > 0$, and a vector $v \in \mathbb{R}^{d} \setminus V$ such that 
		\begin{align} 
			u(x_{0}) - \lambda \varphi(x_{0} - v) &= \max \left\{ u(x) - \lambda \varphi(x - v) \, \mid \, x \in \overline{V} \right\} \label{E: touching point 1} \\
				&> \max\left\{u(x) - \lambda \varphi(x - v) \, \mid \, x \in \partial V \right\}. \nonumber
		\end{align}
	Up to replacing $u$ by $\lambda^{-1} u$, there is no loss of generality assuming that $\lambda = 1$.  Further, it is safe to assume that $v = 0$ as otherwise one can replace $U$ by $U - v$, $x_{0}$ by $x_{0} - v$, $u$ by $u(\cdot + v)$, and so on.

	Let $(u^{\epsilon})_{\epsilon > 0}$ be the family defined by \eqref{E: strictness} and let $\epsilon_{*} = \epsilon_{*}(u,\mu) > 0$ be as in Lemma \ref{L: strict subharmonic}.  Choose a family $(x_{\epsilon})_{\epsilon > 0} \subseteq \overline{V}$ such that 
		\begin{equation*}
			u^{\epsilon}(x_{\epsilon}) - \varphi(x_{\epsilon}) = \max \left\{ u^{\epsilon}(x) - \varphi(x) \, \mid \, x \in \overline{V} \right\}.
		\end{equation*}
	By \eqref{E: touching point 1}, there is no loss of generality assuming (i.e., up to extraction) that there is an $x_{*} \in V$ such that $x_{\epsilon} \to x_{*}$ as $\epsilon \to 0^{+}$.  When $\epsilon$ is small enough, there holds $x_{\epsilon} \in V$, and, thus, by the lemma,
		\begin{equation*}
			\frac{1}{2} \epsilon \varphi^{*}(Du^{\epsilon}(x_{\epsilon}))^{2} -G_{\varphi}^{*}(Du^{\epsilon}(x_{\epsilon}),D^{2}u^{\epsilon}(x_{\epsilon}))  \leq 0.
		\end{equation*}
	At the same time, $\varphi - u^{\epsilon}$ has a local minimum at $x_{\epsilon}$.  Hence, by Proposition \ref{P: strongly superharmonic} and its proof,
		\begin{equation*}
			-G_{\varphi}^{*}(Du^{\epsilon}(x_{\epsilon}),D^{2}u^{\epsilon}(x_{\epsilon}) \geq 0, \quad \varphi^{*}(Du^{\epsilon}(x_{\epsilon})) = 1.
		\end{equation*}
	(Here is where smoothness of $u^{\epsilon}$ is used.) In particular,
		\begin{equation*}
			0 < \frac{1}{2} \epsilon \leq \frac{1}{2} \epsilon \varphi^{*}(Du^{\epsilon}(x_{0}))^{2} -G_{\varphi}^{*}(Du^{\epsilon}(x_{0}),D^{2}u^{\epsilon}(x_{0})) \leq 0, 
		\end{equation*}
	which is absurd.

\label{L: symmetries} Let $\varphi$ be a Finsler norm in $\mathbb{R}^{d}$.  Then $\text{Sub}_{\varphi}(U) \subseteq CCA_{\varphi}(U)$ for all open sets $U$ if the following statement holds: for any open, bounded set $V \subseteq \mathbb{R}^{d} \setminus \{0\}$, any $\epsilon > 0$, and any $u^{\epsilon} \in USC(\overline{V})$ such that $\frac{1}{2} \epsilon \varphi^{*}(Du^{\epsilon})^{2} - G_{\varphi}^{*}(Du^{\epsilon},D^{2}u^{\epsilon}) \leq 0$ in $V$, there holds
		\begin{equation*}
			\max \left\{ u^{\epsilon}(x) - \varphi(x) \, \mid \, x \in \overline{V} \right\} = \max \left\{ u^{\epsilon}(x) - \varphi(x) \, \mid \, x \in \partial V \right\}.
		\end{equation*}

\label{L: reduction to subsolutions} Given any Finsler norm $\varphi$ in $\mathbb{R}^{d}$, let $\underline{\varphi}$ be the inverted norm, that is, the Finsler norm given by 
		\begin{equation*}
			\underline{\varphi}(q) = \varphi(-q) \quad \text{for each} \quad q \in \mathbb{R}^{d}.
		\end{equation*}
	Given any open set $U \subseteq \mathbb{R}^{d}$, if $\mathcal{N} : LSC(U) \to USC(U)$ is the map
		\begin{equation*}
			\mathcal{N}u(x) = -u(x) \quad \text{for each} \quad x \in U,
		\end{equation*}
	then
		\begin{equation*}
			\mathcal{N}(\text{Super}_{\varphi}(U)) = \text{Sub}_{\underline{\varphi}}(U), \quad \mathcal{N}(CCB_{\varphi}(U)) = CCA_{\underline{\varphi}}(U).
		\end{equation*}
	In particular, $\text{Super}_{\varphi}(U) \subseteq CCB_{\varphi}(U)$ if and only if $\text{Sub}_{\underline{\varphi}}(U) \subseteq CCA_{\underline{\varphi}}(U)$.

\label{R: lower bound} Later in the paper, it will be useful to know that, for any $\zeta \in (0,1)$, there is a lower bound
	\begin{equation*}
		\delta(\varphi)^{-1} \|x\| \leq \varphi_{\zeta}(x) \quad \text{for each} \quad x \in \mathbb{R}^{d}.
	\end{equation*}
Indeed, this follows directly from \eqref{E: nondegeneracy condition zeta} and positive homogeneity.

\label{P: approximate supersolution} There is a constant $c(\varphi) > 0$ such that $-G_{\varphi}^{*}(D\varphi_{\zeta},D^{2}\varphi_{\zeta}) \geq - c(\varphi) \zeta \varphi_{\zeta}^{-1}$ holds in $\mathbb{R}^{d} \setminus \{0\}$ with respect to convex test functions.  More precisely, if $x_{*} \in \mathbb{R}^{d} \setminus \{0\}$ and $\psi$ is a smooth convex function defined in a neighborhood of $x_{*}$ that touches $\varphi_{\zeta}$ from below at $x_{*}$, then
		\begin{equation*}
			- G_{\varphi}^{*}(D\psi(x_{*}), D^{2} \psi(x_{*})) \geq -c(\varphi) \zeta \varphi_{\zeta}(x_{*})^{-1}.
		\end{equation*}

\label{L: basic hessian bound} Given any Finsler norm $\varphi$, there is a constant $c(\varphi) > 0$ such that if $(\varphi_{\zeta})_{\zeta > 0}$ are the approximations of Theorem \ref{T: regularized_norm}, then, for any $\zeta \in (0,1)$,
		\begin{equation} \label{E: hessian estimate kind of silly}
			\varphi_{\zeta} D^{2}\varphi_{\zeta} \leq c(\varphi) \zeta^{-1} \text{Id} \quad \text{in the distributional sense.}
		\end{equation}

Henceforth, to lighten the notation, it will frequently be useful to denote by $Q_{X}$ the quadratic form associated with a symmetric matrix $X$, hence $Q_{X}(v) = \langle Xv, v \rangle$ for any $v \in \mathbb{R}^{d}$.  

	First, by Proposition \ref{P: strongly superharmonic},
		\begin{equation*}
			-Q_{D^{2}\psi(x_{*})}(q) = -\langle D^{2}\psi(x_{*}) q, q \rangle \geq 0 \quad \text{for each} \quad q \in \partial \varphi^{*}_{\zeta}(D\psi(x_{0})).
		\end{equation*}
	Yet $\psi$ is convex so $D^{2}\psi(x_{*}) \geq 0$.  Therefore, the previous bound is actually equivalent to an apparently stronger statement:
		\begin{equation} \label{E: key vanishing part 1}
			D^{2}\psi(x_{*}) q = 0 \quad \text{for each} \quad q \in \partial \varphi^{*}_{\zeta}(D\psi(x_{*})).
		\end{equation}

	Next, recall that \eqref{E: hessian estimate kind of silly} holds not only distributionally but also in the viscosity sense; the two are equivalent.\footnote{See \cite[Lemma 1]{alvarez_lasry_lions}, \cite[Theorem 1]{oberman}, or \cite[Proposition 5.1]{bardi_dragoni}.}  Thus, since $\psi$ touches $\varphi_{\zeta}$ from below at $x_{*}$,
		\begin{equation*}
			-D^{2}\psi(x_{*}) \geq - c(\varphi) \varphi_{\zeta}(x_{*})^{-1} \zeta^{-1}.
		\end{equation*}
	Finally, appeal to the definition of $G_{\varphi}^{*}$ and \eqref{E: shifted operator key identity}:
		\begin{align*}
			-G_{\varphi}^{*}(D\psi(x_{*}), D^{2}\psi(x_{*})) &= - \max \left\{ Q_{D^{2}\psi(x_{*})}(\bar{q}) \, \mid \, \bar{q} \in \partial \varphi(D\psi(x_{*})) \right\} \\
				&= - \max_{q \in \partial \varphi_{\zeta}(D\psi(x_{*}))} \left\{ Q_{D^{2}\psi(x_{*})}(q - \zeta \|D\psi(x_{*})\|^{-1} D\psi(x_{*}))  \right\}
		\end{align*}
	Due to \eqref{E: key vanishing part 1}, if $q \in \partial \varphi_{\zeta}(D\psi(x_{*}))$, then
		\begin{equation*}
			Q_{D^{2}\psi(x_{*})}(q - \zeta \|D\psi(x_{*})\|^{-1} D\psi(x_{*})) = \zeta^{2} \|D\psi(x_{*})\|^{-2} Q_{D^{2}\psi(x_{*})}(D\psi(x_{*}))
		\end{equation*}
	Thus, by the Hessian bound on $\psi$ at $x_{*}$,
		\begin{align*}
				-G_{\varphi}^{*}(D\psi(x_{*}), D^{2}\psi(x_{*})) &= - \zeta^{2}\|D\psi(x_{*})\|^{-2} \langle D^{2} \psi(x_{*}) D\psi(x_{*}), D\psi(x_{*}) \rangle \\
				&\geq - c(\varphi) \zeta^{-1} \varphi_{\zeta}(x_{*})^{-1} \zeta^{2} = -c(\varphi) \zeta \varphi_{\zeta}(x_{*})^{-1}.
		\end{align*}

\label{P: intermediate cone comparison} Let $\varphi$ be a Finsler norm in $\mathbb{R}^{d}$ and let $(\varphi_{\zeta})_{\zeta > 0}$ be the regularized norms of Theorem \ref{T: regularized_norm}.

	There is a constant $\tilde{\Gamma}(\varphi) > 0$ such that, for any $\zeta \in (0,1)$, $\alpha \in \mathbb{R}$, $\epsilon \geq 0$, and bounded open set $W \subseteq \mathbb{R}^{d}$ with $0 \notin W$, if $u \in USC(\overline{W})$ satisfies
		\begin{equation} \label{E: perturbed equation}
			\frac{1}{2} \epsilon \varphi^{*}(Du)^{2} - \mathcal{G}_{\varphi_{\zeta}}^{*,\alpha}(Du,D^{2}u) \leq 0 \quad \text{in} \, \, W,
		\end{equation}
	then either $u - \varphi_{\zeta}$ attains its maximum on $\partial W$ or else there is a triple $(x_{*},X_{*},q_{*}) \in W \times \mathcal{S}_{d} \times \{\varphi_{\zeta} = 1\}$ such that 
		\begin{gather*}
			\frac{1}{2} \epsilon \varphi^{*}(D\varphi_{\zeta}(x_{*}))^{2} - Q_{X_{*}}(q_{*} - \alpha \|D\varphi_{\zeta}(x_{*})\|^{-1} D\varphi_{\zeta}(x_{*})) \leq 0, \\
			X_{*}q_{*} = 0, \quad \text{and} \quad 0 \leq \varphi_{\zeta}(x_{*}) X_{*} \leq \tilde{\Gamma}(\varphi) \zeta^{-1} \text{Id}.
		\end{gather*}

By Lemma \ref{L: symmetries}, the proof reduces to establishing that, given any bounded open set $V \subseteq \mathbb{R}^{d} \setminus \{0\}$ and any $\epsilon > 0$, if $u \in USC(\overline{V})$ satisfies 
	\begin{equation*}
		\frac{1}{2} \epsilon \varphi^{*}(Du)^{2} - G_{\varphi}^{*}(Du,D^{2}u) \leq 0 \quad \text{in} \, \, V,
	\end{equation*}
then
	\begin{equation*}
		\max \left\{ u(x) - \varphi(x) \, \mid \, x \in \overline{V} \right\} = \max \left\{ u(x) - \varphi(x) \, \mid \, x \in \partial V \right\}.
	\end{equation*}

It is simplest to argue by contradiction: suppose that
	\begin{equation*}
		\max \left\{ u(x) - \varphi(x) \, \mid \, x \in \overline{V} \right\} > \max \left\{ u(x) - \varphi(x) \, \mid \, x \in \partial V \right\}.
	\end{equation*}
In particular, since $u$ is upper semicontinuous, there is an $r > 0$ such that if $\overline{B}_{r}(\partial V) = \bigcup_{y \in \partial V} \overline{B}_{r}(y)$, then
	\begin{equation*}
		\max \left\{ u(x) - \varphi(x) \, \mid \, x \in \overline{V} \right\} > \max \left\{ u(x) - \varphi(x) \, \mid \, x \in \overline{B}_{r}(\partial V) \right\}.
	\end{equation*}
Note that since $0 \notin V$, it follows that $V \setminus \overline{B}_{r}(\partial V) \subseteq \mathbb{R}^{d} \setminus \overline{B}_{r}(0)$. 

Let $(\varphi_{\zeta})_{\zeta > 0}$ be the approximating norms of Theorem \eqref{T: regularized_norm}.  Since $\varphi_{\zeta} \to \varphi$ uniformly in $\overline{V}$ as $\zeta \to 0^{+}$, it follows that there is a $\zeta_{*} \in (0,1)$ such that, for any $\zeta < \zeta_{*}$,
	\begin{equation} \label{E: what we want to prove gosh}
		\max \left\{ u(x) - \varphi_{\zeta}(x) \, \mid \, x \in \overline{V} \right\} > \max \left\{ u(x) - \varphi_{\zeta}(x) \, \mid \, x \in \overline{B}_{r}(\partial V) \right\}.
	\end{equation}

Fix an arbitrary $\zeta < \zeta_{*}$.  In view of \eqref{E: key transformation}, $u$ satisfies
	\begin{equation*}
		\frac{1}{2} \epsilon \varphi^{*}(Du)^{2} - \mathcal{G}_{\varphi_{\zeta}}^{*,\zeta}(Du,D^{2}u) \leq 0 \quad \text{in} \, \, V.
	\end{equation*}
Therefore, by Proposition \ref{P: technical core eaten} applied with $W = V \setminus \overline{B}_{r}(\partial V)$, there is a triple $(x_{*},X_{*},q_{*}) \in (V \setminus \overline{B}_{r}(\partial V)) \times \mathcal{S}_{d} \times \{\varphi_{\zeta} = 1\}$ such that
	\begin{gather*}
		\frac{1}{2} \epsilon \varphi^{*}(D\varphi_{\zeta}(x_{*}))^{2} - Q_{X_{*}}(q_{*} - \zeta \|D\varphi_{\zeta}(x_{*})\|^{-1} D\varphi_{\zeta}(x_{*})) \leq 0, \\
		X_{*} q_{*} = 0, \quad \text{and} \quad 0 \leq \varphi_{\zeta}(x_{*}) X_{*} \leq c(\varphi) \zeta^{-1} \text{Id}.
	\end{gather*}
Here it is important to emphasize specifically that $x_{*} \notin \overline{B}_{r}(\partial V)$ so $\|x_{*}\| > r$. 

Due to the bound on $X_{*}$ and the fact that $q_{*}$ lies in its kernel, one can write
	\begin{align*}
		Q_{X_{*}}(q_{*} - \zeta \|D\varphi_{\zeta}(x_{*})\|^{-1} D\varphi_{\zeta}(x_{*})) &= \zeta^{2} Q_{X_{*}}(\|D\varphi_{\zeta}(x_{*})\|^{-1} D\varphi_{\zeta}(x_{*})) \\
			&\leq c(\varphi) \varphi_{\zeta}(x_{*})^{-1} \zeta.
	\end{align*}

Harvesting the above inequalities, along with the bound $\varphi^{*}(D\varphi_{\zeta}(x_{*})) \geq \kappa(\varphi)$ from Theorem \ref{T: regularized_norm}, one finds
	\begin{equation*}
		\frac{1}{2} \epsilon \kappa(\varphi)^{2} - c(\varphi) \varphi_{\zeta}(x_{*})^{-1} \zeta \leq 0.
	\end{equation*}
In view of the fact that $\|x_{*}\| > r$, this can be rearranged to give
	\begin{equation*}
		\min \left\{ \varphi_{\zeta}(x) \, \mid \, x \in \partial B_{r}(0) \right\} = \min \left\{\varphi_{\zeta}(x) \, \mid \, x \in \mathbb{R}^{d} \setminus \overline{B}_{r}(0) \right\} \leq \frac{2 c(\varphi)}{\kappa(\varphi)^{2}} \cdot \frac{\zeta}{\epsilon}
	\end{equation*}
In the limit $\zeta \to 0^{+}$, this last inequality becomes the conclusion that 
	\begin{equation*}
		\min \left\{ \varphi(x) \, \mid \, x \in \partial B_{r}(0) \right\} \leq 0,
	\end{equation*}
but this contradicts the fact that $\varphi$ is positive away from zero.

\label{P: structure theorem} For any $\zeta > 0$, the set $E_{\zeta}$ has the following properties:
	\begin{itemize}
		\item[(i)] $E_{\zeta}$ is a closed convex set of class $C^{1,1}$ satisfying a uniform interior ball condition with radius $\zeta$.
		\item[(ii)] There is a continuous function $\mathcal{Q}_{\zeta} : \partial E_{\zeta} \to \{\varphi = 1\}$ such that, for any $q_{*} \in \partial E_{\zeta}$, the point $\bar{q}_{*} = \mathcal{Q}_{\zeta}(q)$ is the unique point in $\{\varphi = 1\}$ closest to $q_{*}$, that is,
				\begin{equation*}
					\{\bar{q}_{*}\} = \{\bar{q} \in \{\varphi \leq 1\} \, \mid \, \|\bar{q} - q_{*}\| = \zeta \}.
				\end{equation*}
		\item[(iii)] For any $q \in \partial E_{\zeta}$, if $\bar{q} = \mathcal{Q}_{\zeta}(q)$ as before, then 
				\begin{equation*}
					\varphi^{*}(q_{*} - \bar{q}_{*})^{-1} (q_{*} - \bar{q}_{*}) \in \partial \varphi(\bar{q}_{*}), \quad
					\langle q_{*} - \bar{q}_{*}, q_{*} \rangle = \sup \left\{ \langle q_{*} - \bar{q}_{*}, q \rangle \, \mid \, q \in E_{\zeta} \right\}.
				\end{equation*}
	\end{itemize}

\label{L: separation and distance} Let $E \subseteq \mathbb{R}^{d}$ be convex and suppose that $q_{*} \notin \overline{E}$. Given any $\bar{q}_{*} \in \partial E$, the equality $\|q_{*} - \bar{q}_{*}\| = \text{dist}(q_{*},E)$ holds if and only if
			\begin{equation*}
				\langle q_{*} - \bar{q}_{*}, \bar{q}_{*} \rangle = \sup \left\{ \langle q_{*} - \bar{q}_{*}, \bar{q} \rangle \, \mid \, \bar{q} \in \overline{E} \right\}.
			\end{equation*}
		In particular, there is a unique such point $\bar{q}_{*}$.

To see that (i) holds, first, observe that $E_{\zeta}$ is convex.  Indeed, suppose that $q_{1},q_{2} \in E_{\zeta}$ and $\lambda \in [0,1]$.  By construction, there are points $\bar{q}_{1},\bar{q}_{2} \in \{\varphi \leq 1\}$ and $\xi_{1},\xi_{2} \in \overline{B}_{\zeta}$ such that $q_{i} = \bar{q}_{i} + \xi_{i}$ for $i \in \{1,2\}$.  From this, one decomposes the convex combination $(1 - \lambda) q_{1} + \lambda q_{2}$ as
			\begin{equation*}
				(1 - \lambda) q_{1} + \lambda q_{2} = [(1 - \lambda) \bar{q}_{1} + \lambda \bar{q}_{2}] + [(1 - \lambda) \xi_{1} + \lambda \xi_{2}].
			\end{equation*}
		 Since $\{\varphi \leq 1\}$ and $\overline{B}_{\zeta}$ are both convex, it follows that $(1 - \lambda) q_{1} + \lambda q_{2} \in E_{\zeta}$, hence $E_{\zeta}$ is convex.  

		 Next, here is the proof that $E_{\zeta}$ satisfies a uniform interior ball condition with radius $\zeta$, and, thus, is of class $C^{1,1}$.  By definition, if $q_{*} \in \partial E_{\zeta}$, then there is a $\bar{q}_{*} \in \{\varphi \leq 1\}$ such that $\|q_{*} - \bar{q}_{*}\| = \zeta$.  From this, one readily deduces that $\overline{B}_{\zeta}(q_{*} - \zeta e) = \overline{B}_{\zeta}(\bar{q}_{*}) \subseteq E_{\zeta}$ with $e = \|q_{*} - \bar{q}_{*}\|^{-1} (q_{*} - \bar{q}_{*})$. 

		Next, turn to (ii).  By Lemma \ref{L: separation and distance}, for any $x \in \mathbb{R}^{d}$, there is a unique $\bar{q}_{x} \in \{\varphi \leq 1\}$ such that $\|x - \bar{q}_{x}\| = \text{dist}(x,\{\varphi \leq 1\})$.  It is also easy to check that $\bar{q}_{x} \in \{\varphi = 1\}$ if $\varphi(x) > 1$.  In particular, the function $\mathcal{Q}_{\zeta} : \partial E_{\zeta} \to \{\varphi = 1\}$ given by setting $\mathcal{Q}_{\zeta}(q) = \bar{q}_{q}$ is well-defined.  Due to the fact that $\{\varphi \leq 1\}$ is compact, uniqueness readily implies continuity.

		Finally, consider (iii).  Let $\bar{q}_{*} = \mathcal{Q}_{\zeta}(q_{*})$.  A classical argument establishes that $\varphi^{*}(q_{*} - \bar{q}_{*})^{-1} (q_{*} - \bar{q}_{*}) \in \partial \varphi(\bar{q}_{*})$.  Indeed, were this not the case, it would be possible to invoke \eqref{E: subdifferential basic identity dual} and \eqref{E: inversion} to find a $\bar{q}_{**} \in \{\varphi \leq 1\}$ such that 
			\begin{equation*}
				\langle q_{*} - \bar{q}_{*}, \bar{q}_{**} \rangle > \langle q_{*} - \bar{q}_{*}, \bar{q}_{*} \rangle.
			\end{equation*}
		However, this would contradict Lemma \ref{L: separation and distance}.  

		It only remains to show that
			\begin{equation} \label{E: super annoying}
				\langle q_{*} - \bar{q}_{*}, q_{*} \rangle = \sup \left\{ \langle q_{*} - \bar{q}_{*}, q \rangle \, \mid \, q \in \partial E_{\zeta} \right\}.
			\end{equation}
		To see this, first, note that if $N_{\partial E_{\zeta}}(q_{*}) \in S^{d-1}$ is the outward normal vector to $\partial E_{\zeta}$ at $q_{*}$, then, by convexity, $N_{\partial E_{\zeta}}(q_{*})$ determines a supporting hyperplane:
			\begin{equation} \label{E: separation}
				\langle N_{\partial E_{\zeta}}(q_{*}), q_{*} \rangle = \sup \left\{ \langle N_{\partial E_{\zeta}}, q \rangle \, \mid \, q \in E_{\zeta} \right\}.
			\end{equation}
		At the same time, as observed already, there holds $\overline{B}_{\zeta}(\bar{q}_{*}) \subseteq E_{\zeta}$ and $q_{*} \in \partial B_{\zeta}(\bar{q}_{*}) \cap \partial E_{\zeta}$, i.e., the ball $\overline{B}_{\zeta}(\bar{q}_{*})$ is tangent to $E_{\zeta}$ from the inside.  It necessarily follows that $N_{\partial E_{\zeta}}(q_{*})$ equals the normal vector to $\partial B_{\zeta}(\bar{q}_{*})$, that is, $N_{\partial E_{\zeta}}(q_{*}) = \|q_{*} - \bar{q}_{*}\|^{-1} (q_{*} - \bar{q}_{*})$.  Combining this with \eqref{E: separation} yields \eqref{E: super annoying}.

\label{P: multivalued inverse} Let $\mathcal{Q}_{\zeta}$ be the map defined in Proposition \ref{P: structure theorem}.  Then, for any $\bar{q} \in \{\varphi = 1\}$,
		\begin{equation*}
			\{q \in \partial E_{\zeta} \, \mid \, \mathcal{Q}_{\zeta}(q) = \bar{q}\} = \bar{q} + \left\{ \frac{\zeta p}{\|p\|} \, \mid \, p \in \partial \varphi(\bar{q}) \right\}
		\end{equation*}

\label{R: ball regularization} At this stage, it is worth considering what happens when $\varphi(q) = \alpha^{-1} \|q\|$ for some constant $\alpha > 0$.  In this case, the unit ball $\{\varphi \leq 1\}$ is nothing but the ball $\overline{B}_{\alpha}(0)$, and then it is easy to verify that $E_{\zeta} = \overline{B}_{\alpha + \zeta}(0)$ for any $\zeta > 0$.  In particular, this proves that
		\begin{equation*}
			\varphi_{\zeta} = \frac{1}{\alpha + \zeta} \|\cdot\| \quad \text{if} \quad \varphi = \frac{1}{\alpha} \|\cdot\|.
		\end{equation*}

\label{P: subdifferential characterization} If $p \in \mathbb{R}^{d} \setminus \{0\}$, then
		\begin{equation*}
			\partial \varphi_{\zeta}^{*}(p) = \partial \varphi^{*}(p) +  \frac{\zeta p}{\|p\|}.
		\end{equation*}

First, note that if $q \in \partial \varphi_{\zeta}^{*}(p)$, then \eqref{E: key subdifferential identity} implies that, at the level of the normal vector $N_{\partial E_{\zeta}}(q)$ to $\partial E_{\zeta}$ at $q$, there holds 
				\begin{equation*}
					\frac{p}{\|p\|} = N_{\partial E_{\zeta}}(q) = \frac{D\varphi_{\zeta}(q)}{\|D\varphi_{\zeta}(q)\|}.
				\end{equation*}
			Thus, by Proposition \ref{P: structure theorem}, (iii), 
				\begin{equation} \label{E: tedious subdifferential computations}
					q - \mathcal{Q}_{\zeta}(q) = \frac{\zeta p}{\|p\|}, \quad \varphi^{*}(p)^{-1} p \in \partial \varphi(\mathcal{Q}_{\zeta}(q)).
				\end{equation}
			By duality, the second identity can be rewritten as $\mathcal{Q}_{\zeta}(q) \in \partial \varphi^{*}(p)$.  Indeed, by \eqref{E: inversion} and zero-homogeneity,
				\begin{align*}
					\mathcal{Q}_{\zeta}(q) &\in \partial \varphi^{*}(\varphi^{*}(p)^{-1} p) = \partial \varphi^{*}(p).
				\end{align*}
			Since $q$ is an arbitrary element of $\partial \varphi_{\zeta}^{*}(p)$, this yields
				\begin{equation*}
					\partial \varphi_{\zeta}^{*}(p) \subseteq \partial \varphi^{*}(p) + \frac{\zeta p}{\|p\|}.
				\end{equation*}

			Conversely, if $\bar{q} \in \partial \varphi^{*}(p)$, then $\varphi^{*}(p)^{-1}p \in \partial \varphi(\bar{q})$ and Proposition \ref{P: multivalued inverse} implies that
				\begin{equation*}
					\bar{q} + \frac{\zeta p}{\|p\|} \in \partial E_{\zeta} \cap \mathcal{Q}_{\zeta}^{-1}(\bar{q}).
				\end{equation*}
			By Proposition \ref{P: structure theorem}, (iii) and \eqref{E: key subdifferential identity}, the inclusion $\bar{q} + \frac{\zeta p}{\|p\|} \in \partial \varphi^{*}_{\zeta}(p)$ holds.  Since $\bar{q}$ was arbitrary, this gives the remaining inclusion:
				\begin{equation*}
					\partial \varphi^{*}(p) + \frac{\zeta p}{\|p\|} \subseteq \partial \varphi_{\zeta}^{*}(p).
				\end{equation*}

\label{P: proof of approx theorem 1} $\varphi_{\zeta} \to \varphi$ locally uniformly in $\mathbb{R}^{d}$ as $\zeta \to 0^{+}$.  Furthermore, there are constants $C(\varphi), \mu(\varphi) > 0$ such that, for any $\zeta \in (0,1)$,
		\begin{gather} 
			\mu(\varphi) \leq \|D\varphi_{\zeta}(x)\| \leq C(\varphi) \quad \text{for each} \quad x \in \mathbb{R}^{d} \setminus \{0\}, \quad \text{and} \label{E: bounded below gradient} \\
			\{\varphi_{\zeta} \leq 1\} \subseteq (1 + C(\varphi) \zeta) \{\varphi \leq 1\}. \nonumber
		\end{gather}

First, recall that $\{\varphi \leq 1\} \subseteq \{\varphi_{\zeta} \leq 1\}$ for any $\zeta > 0$.  This implies $\varphi_{\zeta} \leq \varphi$ by positive one-homogeneity.  

		Define $C(\varphi) = \max\{\varphi(y) \, \mid \, \|y\| = 1\}$, and note that 
			\begin{equation*}
				B_{1}(0) \subseteq \{\varphi \leq C(\varphi)\} = C(\varphi) \{\varphi \leq 1\}.
			\end{equation*}
		Thus, for any $\zeta > 0$, there holds $E_{\zeta} \subseteq \{\varphi \leq 1\} + \overline{B}_{\zeta}(0) \subseteq (1 + C(\varphi)\zeta) \{\varphi \leq 1\}$.  Since $\varphi_{\zeta}$ is positively one-homogeneous, it follows that, for any $y \in \mathbb{R}^{d}$ and any $\zeta \in (0,1)$,
		\begin{equation*}
			(1 + C(\varphi)\zeta)^{-1} \min \left\{ \varphi(y) \, \mid \, \|y\| = 1\right\}\|x\| \leq \varphi_{\zeta}(x) \leq \varphi(x) \leq C(\varphi) \|x\|.
		\end{equation*}
	From this and the identity $\varphi_{\zeta}(x) = \langle D\varphi_{\zeta}(x), x \rangle$, one deduces that
		\begin{equation*}
			(1 + C(\varphi) \zeta)^{-1} \min \left\{ \varphi(y) \, \mid \, \|y\| = 1 \right\} \leq \|D\varphi_{\zeta}(x)\| \quad \text{for each} \quad x \in \mathbb{R}^{d} \setminus \{0\}.
		\end{equation*}
	Similarly, since $\langle D\varphi_{\zeta}(x), y \rangle \leq \varphi_{\zeta}(y)$ for any $x,y \in \mathbb{R}^{d} \setminus \{0\}$, 
		\begin{equation*}
			\|D\varphi_{\zeta}(x)\| \leq C(\varphi) \quad \text{for each} \quad x \in \mathbb{R}^{d} \setminus \{0\}.
		\end{equation*}
	This proves \eqref{E: bounded below gradient} holds, and it shows that $(\varphi_{\zeta})_{\zeta > 0}$ is uniformly Lipschitz.

	By the Arzel\`{a}-Ascoli Theorem, up to passing to a subsequence, there is a Finsler norm $\tilde{\varphi}$ such that $\varphi_{\zeta} \to \tilde{\varphi}$ locally uniformly as $\zeta \to 0^{+}$.  The previous considerations show that, for any $\zeta \in (0,1)$,
		\begin{equation*}
			\{\varphi \leq 1\} \subseteq \{\tilde{\varphi} \leq 1\} \subseteq (1 + C(\varphi) \zeta) \{\varphi \leq 1\}.
		\end{equation*}
	Therefore, $\{\varphi \leq 1\} = \{\tilde{\varphi} \leq 1\}$, which means $\tilde{\varphi} = \varphi$.  Since the subsequence was arbitrary, this proves $\varphi_{\zeta} \to \varphi$ locally uniformly.

\label{P: proof of approx theorem 2} There is a $\kappa(\varphi) > 0$ such that, for any $\zeta \in (0,1)$,
		\begin{equation*}
			\varphi^{*}(D\varphi_{\zeta}(x)) \geq \kappa(\varphi) \quad \text{for each} \quad x \in \mathbb{R}^{d} \setminus \{0\}.
		\end{equation*}

Since $\varphi^{*}$ is a Finsler norm, there is a constant $m(\varphi^{*}) > 0$ such that
			\begin{equation*}
				\varphi^{*}(p) \geq m(\varphi^{*}) \|p\| \quad \text{for each} \quad p \in \mathbb{R}^{d}.
			\end{equation*}
		Thus, the desired conclusion follows from Proposition \ref{P: proof of approx theorem 1}.

Given a convex set $C \subseteq \mathbb{R}^{d}$, the \emph{relative interior} $\text{rint}(C)$ is the interior of $C$ relative to the subspace $V_{C}$, that is, $x \in \text{rint}(C)$ if and only if there is an $r > 0$ such that
		\begin{equation*}
			B_{r}(x) \cap (x + V_{C}) \subseteq C.
		\end{equation*}
	The \emph{relative boundary} $\text{bdry}(C)$ of $C$ is the boundary of $C$ relative to $V_{C}$:
		\begin{equation*}
			\text{bdry}(C) = \overline{C} \setminus \text{rint}(C).
		\end{equation*}

Given a closed convex set $C \subseteq \mathbb{R}^{d}$, a subset $F \subseteq C$ is called an \emph{exposed face} if there is a $p \in \mathbb{R}^d$ such that 
		\begin{equation*}
			F = \left\{x \in C \, \mid \, \langle x, p \rangle = \max_{y \in C} \, \langle y,p \rangle \right\}.
		\end{equation*}

Consider the convex set $C \subseteq \mathbb{R}^{2}$ given by 
	\begin{equation*}
		C = ([0,1] \times [0,1]) \cup \left\{(x,y) \in \mathbb{R}^{2} \, \mid \,  1 \leq x \leq 2, \, \, 0 \leq y \leq \sqrt{1 - (x - 1)^{2}} \right\}.
	\end{equation*}
The segment $[0,1] \times \{1\}$ is an exposed face.  At the same time, the singleton $\{(1,1)\}$ is a face, but it is not exposed (since $\partial C$ is differentiable there).

Let $x \in \mathbb{R}^{d} \setminus \{0\}$.  Define $q = \varphi(x)^{-1} x$ so that $q \in \{\varphi = 1\}$ and $x \in \mathcal{C}(\{q\})$, and let $e = \|D\varphi(q)\|^{-1} D\varphi(q)$.  Define $\psi_{x}$ by $\psi_{x}(y) = \psi_{e,q,\zeta}(y)$, where $\psi_{e,q,\zeta}$ is the positively homogeneous convex function defined in the preceding discussion.  Condition (i) holds by \eqref{E: psi above} and \eqref{E: psi equal}, and condition (ii), by Lemma \ref{L: smoothness of the ball thing}.  Therefore, it only remains to check (iii).

