		\begin{equation*}
				\partial \varphi^{*}(D\psi_{e,q,\zeta}(x)) = \{D\varphi^{*}(D\psi_{e,q,\zeta}(x))\} = \{D\varphi^{*}(D\varphi(x))\} = \{q\}.
		\end{equation*}
Invoking the definition of $G_{\varphi}^{*}$ and $G_{*}^{\varphi}$, one concludes
		\begin{equation*}
			G_{\varphi}^{*}(D\psi_{e,q,\zeta}(x),D^{2}\psi_{e,q,\zeta}(x)) = G_{*}^{\varphi}(D\psi_{e,q,\zeta}(x),D^{2}\psi_{e,q,\zeta}(x)) = \langle D^{2} \psi_{e,q,\zeta}(x) q, q \rangle = 0.
		\end{equation*}

By Lemma \ref{L: symmetries}, to prove that $\text{Sub}_{\varphi}(U) \subseteq CCA_{\varphi}(U)$, it suffices to show that if $V$ is a bounded open set in $\mathbb{R}^{d} \setminus \{0\}$, $\epsilon > 0$, and $u$ is an upper semicontinuous function in $\overline{V}$ such that $ \frac{1}{2} \epsilon \varphi^{*}(Du)^{2} -G_{\varphi}^{*}(Du,D^{2}u) \leq 0$ in $V$, then
			\begin{equation*}
				\max \{u(x) - \varphi(x) \, \mid \, x \in \overline{V} \} = \max \{ u(x) - \varphi(x) \, \mid \, x \in \partial V\}.
