			\text{and} \quad G_{\varphi}^{*}(D\psi_{x}(x),D^{2}\psi_{x}(x)) = G_{*}^{\varphi}(D\psi_{x}(x),D^{2}\psi_{x}(x)) = 0. \nonumber
		\end{gather}

