	Yet \eqref{E: subdifferential basic identity} implies that $\varphi^{*}(D\varphi(x)) = 1$, so this leads to the inequality $0 < \frac{1}{2} \epsilon \leq 0$, which is absurd.

\label{R: strongly superharmonic again} Notice that the test functions $\{\psi_{x}\}_{x \in \mathbb{R}^{d} \setminus \{0\}}$ can be used to prove that $-G_{\varphi}^{*}(D\varphi,D^{2}\varphi) \geq 0$ holds in the viscosity sense in $\mathbb{R}^{d} \setminus \{0\}$.  Indeed, if $x \in \mathbb{R}^{d} \setminus \{0\}$ and $\psi$ is a smooth test function such that $\varphi - \psi$ has a local minimum at $x$, then $\psi_{x} - \psi$ also has a local minimum at $x$, hence, by the second derivative test and ellipticity,
	\begin{equation*}
		-G_{\varphi}^{*}(D\psi(x),D^{2}\psi(x)) \geq - G_{\varphi}^{*}(D\psi_{x}(x),D^{2}\psi_{x}(x)) = 0.
	\end{equation*}
In this sense, Proposition \ref{P: strictly convex game} is a stronger version of Proposition \ref{P: strongly superharmonic} in the special case when $\{\varphi \leq 1\}$ is strictly convex and $C^{1,1}$.

\label{P: touching above test function part} Suppose that $\varphi$ is a Finsler norm in $\mathbb{R}^{d}$ and $\{\varphi \leq 1\}$ satisfies a uniform interior ball condition of radius $\zeta$.  For any $p \in \mathbb{R}^{d} \setminus \{0\}$ and any $\nu \in (0,\zeta]$, if $e = \|p\|^{-1} p$, then
		\begin{gather}
			\varphi \leq \psi_{e, \partial \varphi^{*}(p), \nu} \quad \text{in} \, \, \mathbb{R}^{d}, \nonumber \\
			\varphi(x) = \psi_{e,\partial \varphi^{*}(p),\nu}(x) \quad \text{for each} \quad x \in \mathcal{C}(\partial \varphi^{*}(p)). \label{E: touching}
		\end{gather}
	Further, if $\nu < \zeta$, then the contact set equals $\mathcal{C}(\partial \varphi^{*}(p))$, i.e.,
		\begin{equation} \label{E: contact set cone part}
			\{\varphi = \psi_{e,\partial \varphi^{*}(p),\nu}\} = \{\psi_{e,\partial \varphi^{*}(p),\zeta} = \psi_{e,\partial \varphi^{*}(p),\nu} < +\infty \} = \mathcal{C}(\partial \varphi^{*}(p)).
		\end{equation}

\label{P: smooth case test function}  Suppose that $F \subseteq \mathbb{R}^{d}$ is a closed convex set, $e \in S^{d-1}$, and $\nu > 0$.  If there is a constant $c > 0$ such that 
		\begin{equation} \label{E: hyperplane assumption}
			F \subseteq \{x \in \mathbb{R}^{d} \, \mid \, \langle x,e \rangle = c\}
		\end{equation}
	and if $q_{*} \in \text{rint}(F)$, then $\psi_{e,F,\nu}$ is smooth in a neighborhood of the ray $\mathcal{C}(\{q_{*}\})$ and
		\begin{equation*}
			D^{2} \psi_{e,F,\nu}(q_{*}) q = 0 \quad \text{for each} \quad q \in F.
		\end{equation*}

\label{P: conical test functions not smooth} Suppose that $\varphi$ is a Finsler norm in $\mathbb{R}^{d}$ for which the unit ball $\{\varphi \leq 1\}$ is of class $C^{1,1}$.  Fix an open set $U \subseteq \mathbb{R}^{d}$ and an $\epsilon > 0$, and suppose that $u \in USC(U)$ satisfies
		\begin{equation*}
			\frac{1}{2} \epsilon \varphi^{*}(Du)^{2} -G^{*}_{\varphi}(Du,D^{2}u)  \leq 0 \quad \text{in} \, \, U.
		\end{equation*}  

	If there is a bounded open set $V \subseteq U \setminus \{0\}$ and an $x_{*} \in V$ such that
		\begin{equation*}
			u(x_{*}) - \varphi(x_{*}) = \max\{u(y) - \varphi(y) \, \mid \, y \in \overline{V} \},
		\end{equation*}
	then the point $\varphi(x_{*})^{-1}x_{*}$ does not belong to the relative interior of any of the exposed faces of $\varphi$, that is,
		\begin{equation} \label{E: relative interior issue}
			x_{*} \notin \bigcup_{p \in \mathbb{R}^{d} \setminus \{0\}} \text{rint}(\mathcal{C}(\partial \varphi^{*}(p))).
		\end{equation}

Let $q_{*} = \varphi(x_{*})^{-1} x_{*}$ and fix a $\zeta > 0$ such that $\{\varphi \leq 1\}$ satisfies a interior ball condition of radius $\zeta$.  Argue by contradiction: assume there is a $p \in \mathbb{R}^{d} \setminus \{0\}$ such that
	\begin{equation*}
		q_{*} \in \text{rint}(\partial \varphi^{*}(p)),
	\end{equation*}
which is equivalent to $x_{*} \in \text{rint}(\mathcal{C}(\partial \varphi^{*}(p)))$.
Setting $e = \|p\|^{-1} p$ and applying \eqref{E: touching}, the test function $\psi := \psi_{e,\partial \varphi^{*}(p),\zeta}$ is smooth in a neighborhood of $x$ and $u - \psi$ has a local maximum at $x$.  Thus, by Proposition \ref{P: smooth case test function}, the subsolution property of $u$, and \eqref{E: subdifferential basic identity},
	\begin{align*}
		0 &\geq \frac{1}{2} \epsilon \varphi^{*}(D\psi(x))^{2} -G_{\varphi}^{*}(D\psi(x),D^{2}\psi(x))  \\
			&=  \frac{1}{2} \epsilon \varphi^{*}(D\varphi(x))^{2} - \max \left\{ \langle D^{2}\psi(x) q, q \rangle \, \mid \, q \in \partial \varphi^{*}(p) \right\} = \frac{1}{2} \epsilon,
	\end{align*}
which contradicts the fact that $\epsilon > 0$.

To lighten the notation, let $F = \partial \varphi^{*}(p)$ and $e = \|p\|^{-1} p$.  By \eqref{E: subdifferential basic identity dual}, the outward normal vector to $\{\varphi \leq 1\}$ equals $e$ at each point of $F$.  Thus, since, by hypothesis, $\{\varphi \leq 1\}$ satisfies an interior ball condition of radius $\zeta$, for any $q \in F$, there holds
	\begin{equation*}
		\overline{B}_{\zeta}(q - \zeta e) \subseteq \{\varphi \leq 1\}.
	\end{equation*}
In particular,  $F_{(e,\zeta)} \subseteq \{\varphi \leq 1\}$ by definition.  After a straightforward manipulation of the definition \eqref{E: test function definition} of $\psi_{e,F,\zeta}$, this implies
	\begin{equation*}
		\varphi \leq \psi_{e,F,\zeta} \quad \text{in} \, \, \mathbb{R}^{d}.
	\end{equation*}

Next, if $q \in F$, then $q \in F_{(e,\nu)}$ and, thus, the definition of $\psi_{e,F,\zeta}$ immediately implies that $\psi_{e,F,\zeta}(q) \leq 1$.  On the other hand, since $F \subseteq \{\varphi = 1\}$ by \eqref{E: subdifferential basic identity dual}, there holds $1 = \varphi(q) \geq \psi_{e,F,\zeta}(q)$.  Hence $\varphi = \psi_{e,F,\zeta} = 1$ in $F$, and, by homogeneity, $\varphi = \psi_{e,F,\zeta}$ in $\mathcal{C}(F)$.

Finally, in case $\nu < \zeta$, there holds $\varphi \leq \psi_{e,F,\zeta} \leq \psi_{e,F,\nu}$.  Further, note that for an arbitrary $q \in \mathbb{R}^{d}$, one has 
	\begin{equation*}
		\overline{B}_{\nu}(q - \nu e) \cap \overline{B}_{\zeta}(q - \zeta e) = \{q\}.
	\end{equation*}
From this, it follows that $\partial F_{(e,\nu)} \cap \partial F_{(e,\zeta)} = F$.  Thus, given $x \in \{\psi_{e,F,\zeta} < +\infty\} \cap \{\psi_{e,F,\nu} < +\infty\}$, there holds  $\psi_{e,F,\zeta}(x) = \psi_{e,F,\nu}(x)$ if and only if $x \in F$.

We will show that there is an $r > 0$ and a smooth function $\tilde{\psi} : B_{r}(q) \to \mathbb{R}$ such that $\tilde{\psi}(x) = \psi_{e,F,\nu}(x)$ for each $x \in B_{r}(q)$.  

Let $V_{F} \subseteq \mathbb{R}^{d}$ be the smallest linear subspace such that $F \subseteq q + V_{F}$ (cf.\ Section \ref{S: faces}).  Let $\tilde{F}$ be the corresponding tube, defined analogously to $F_{(e,\nu)}$, that is,
	\begin{equation*}
		\tilde{F} = \bigcup_{y \in q + V_{F}} \overline{B}_{\nu}(y - \nu e).
	\end{equation*}
Let $\tilde{\psi}$ be the Minkowski gauge of $\tilde{F}$:
	\begin{equation*}
		\tilde{\psi}(x) = \inf \left\{ \alpha > 0 \, \mid \, \frac{x}{\alpha} \in \tilde{F} \right\}.
	\end{equation*}
Since $q \in \text{rint}(F)$ by assumption, it follows that there is an $r_{1} > 0$ such that $B_{r_{1}}(q) \cap F = B_{r_{1}}(q) \cap (q + V_{F})$ and, thus, 
	\begin{equation*}
		B_{r_{1}}(q) \cap F_{(e,\nu)} = B_{r_{1}}(q) \cap \tilde{F}.
	\end{equation*}
This implies $\psi_{e,F,\nu} = \tilde{\psi}$ in the cone $\mathcal{C}(B_{r_{1}}(q))$, and, in particular, in $B_{r}(q)$ for an appropriate choice of $r$.  

It only remains to show that $\tilde{\psi}$ is smooth in a neighborhood of $q$.  Since $\tilde{\psi}$ is a positively homogeneous convex function, the results of the next section, particularly Propositions \ref{P: differentiability in terms of level sets} and \ref{P: check proposition} (and their proofs), are applicable.  Hence to see that $\tilde{\psi}$ is smooth in a neighborhood of $q$, it suffices to prove that $\partial \tilde{F}$ is a smooth hypersurface in a neighborhood of $q$.  

Let $V_{F}^{\perp}$ denote the orthogonal complement of $V_{F}$.  To see that $\tilde{F}$ is smooth in a neighborhood of $q$, it suffices to establish that 
	\begin{equation} \label{E: need to prove cylinder thing}
		\{x \in \tilde{F} \, \mid \, \langle x, e \rangle \geq \langle q, e \rangle - \nu\} = (q - \nu e) + V_{F} + (\overline{B}_{\nu}(0) \cap H_{e} \cap V_{F}^{\perp}),
	\end{equation}
where, as before, $H_{e} = \{x \in \mathbb{R}^{d} \, \mid \, \langle x,e \rangle \geq 0\}$.
Indeed, the right-hand side is a cylinder, hence its boundary is a smooth hypersurface; and $q$ is an element of the boundary of the left-hand side.  Therefore, it only remains to prove \eqref{E: need to prove cylinder thing}.  

As far as \eqref{E: need to prove cylinder thing} is concerned, suppose that $x \in \tilde{F}$ and $\langle x,e \rangle \geq \langle q, e \rangle - \nu$.  Fix a $y \in q + V_{F}$ such that $x \in \overline{B}_{\nu}(y - \nu e)$.  Write $x = y - \nu e + \xi_{F} + \xi_{F}^{\perp}$ with $\xi_{F} \in V_{F}$ and $\xi_{F}^{\perp} \in V_{F}^{\perp}$ to find 
	\begin{equation*}
		\|\xi_{F}^{\perp}\| \leq \|x - (y - \nu e)\| \leq \nu, \quad \langle \xi_{F}^{\perp}, e \rangle = \langle x, e \rangle - \langle y, e \rangle + \nu = \langle x,e \rangle - \langle q, e \rangle + \nu \geq 0
	\end{equation*}
since $y - q \in V_{F}$ and $V_{F} \subseteq \langle e \rangle^{\perp}$ holds by \eqref{E: hyperplane assumption}.  This proves
	\begin{equation*}
		-(q - \nu e) + \{x \in \tilde{F} \, \mid \, \langle x, e \rangle \geq \langle q, e \rangle - \nu\} \subseteq V_{F} + (\overline{B}_{\nu}(0) \cap H_{e} \cap V_{F}^{\perp}).
	\end{equation*}

Conversely, fix $\xi_{F} \in V_{F}$ and $\xi_{F}^{\perp} \in \overline{B}_{\nu}(0) \cap H_{e} \cap V_{F}^{\perp}$.  Let $y = q + \xi_{F}$.  Observe that if $x = y - \nu e + \xi_{F}^{\perp}$, then $x \in \overline{B}_{\nu}(y - \nu e) \subseteq \tilde{F}$ and 
	\begin{equation*}
		\langle x,e \rangle = \langle y, e \rangle - \nu + \langle \xi_{F}^{\perp}, e \rangle \geq \langle q, e \rangle - \nu.
	\end{equation*}
This proves the remaining inclusion, and hence \eqref{E: need to prove cylinder thing}.

In what follows, it will be convenient to consider convex functions taking values in $\mathbb{R} \cup \{+\infty\}$.  Toward that end, recall that a function $f : \mathbb{R}^{d} \to \mathbb{R} \cup \{+\infty\}$ is called convex if and only if the set $\{f < + \infty\}$ is convex and $f$ restricts to a real-valued convex function therein.

Furthermore, in order to include nontrivial functions taking value $+\infty$, it is important to give a precise definition of \emph{postively one-homogeneous}.  Specifically, henceforth, a function $f : \mathbb{R}^{d} \to \mathbb{R} \cup \{+\infty\}$ is positively one-homogeneous if, for any $x \in \mathbb{R}^{d}$ and $\lambda > 0$,
	\begin{equation*}
		f(\lambda x) = \lambda f(x).
	\end{equation*}
(It is necessary to exclude $\lambda = 0$ in this definition so that the set $\{f = + \infty\}$ need not be trivial.)

\label{P: subdifferential} If $\psi : \mathbb{R}^{d} \to [0,+\infty]$ is convex and positively one-homogeneous, then, for any $x_{*} \in \text{int}(\{\psi < +\infty\}) \setminus \{0\}$,
		\begin{equation} \label{E: subdifferential thing}
			\partial \psi(x_{*}) = \{p \in \mathbb{R}^{d} \, \mid \, \langle p, x_{*} \rangle = \psi(x_{*})\} \cap \bigcap_{x \in \mathbb{R}^{d}} \{p \in \mathbb{R}^{d} \, \mid \, \langle p, x \rangle \leq \psi(x)\}.
		\end{equation}

First, suppose that $x_{*} \in \text{int}(\{\psi < +\infty\}) \setminus \{0\}$ and $p \in \partial \psi(x_{*})$.  Since $x_{*}$ is in the interior of $\{\psi < +\infty\}$, there is an $\epsilon > 0$ such that $(1 + t)x_{*} \in \{\psi < +\infty\} \setminus \{0\}$ for any $t \in (-\epsilon,\epsilon)$.  Setting $x = (1 + t) x_{*}$ for $t \in (-\epsilon,\epsilon)$, one invokes \eqref{E: def subdifferential} to obtain
			\begin{equation*}
				(1 + t) \psi(x_{*}) = \psi((1 + t)x_{*}) \geq \psi(x_{*}) + t \langle p, x_{*} \rangle.
			\end{equation*}
		Sending $t \to 0^{+}$ yields $\psi(x_{*}) \geq \langle p, x_{*} \rangle$, while sending $t \to 0^{-}$ gives $\psi(x_{*}) \leq \langle p, x_{*} \rangle$.  Thus, $\psi(x_{*}) = \langle p, x_{*} \rangle$.

		Revisiting \eqref{E: def subdifferential} and substituting $\psi(x_{*}) = \langle p, x_{*} \rangle$, one obtains
			\begin{equation*}
				\psi(x) \geq \langle p, x \rangle \quad \text{for each} \quad x \in \mathbb{R}^{d}.
			\end{equation*}
		This proves one of the inclusions involved in \eqref{E: subdifferential thing}.

		Finally, it remains to prove the opposite inclusion.  Suppose that $x_{*} \in \text{int}(\{\psi < +\infty\}) \setminus \{0\}$ and $p \in \mathbb{R}^{d}$ is such that 
			\begin{equation*}
				\langle p, x \rangle \leq \psi(x) \quad \text{for each} \quad x \in \mathbb{R}^{d}, \quad \langle p, x_{*} \rangle = \psi(x_{*}).
			\end{equation*}
		To see that $p \in \partial \psi(x_{*})$, add and subtract $\langle p,x_{*} \rangle$ to find, for any $x \in \mathbb{R}^{d}$,
			\begin{equation*}
				\psi(x) \geq \langle p, x \rangle = \langle p, x_{*} \rangle + \langle p, x - x_{*} \rangle = \psi(x_{*}) + \langle p, x - x_{*} \rangle.
			\end{equation*}

First, note that if $p \in \partial \psi(x_{*})$, then 
			\begin{equation*}
				\langle p, q \rangle \leq \psi(q) \leq 1 = \langle p, \psi(x_{*})^{-1} x_{*} \rangle \quad \text{for each} \quad q \in \{\psi \leq 1\}.
			\end{equation*}
		Thus, each element of $\partial \psi(x_{*})$ determines a supporting hyperplane to $\{\psi \leq 1\}$ through $\psi(x_{*})^{-1} x_{*}$.  

		Conversely, suppose that $p \in \mathbb{R}^{d} \setminus \{0\}$ determines such a hyperplane, that is, $\langle p, q - \psi(x_{*})^{-1} x_{*} \rangle \leq 0$ for each $q \in \{\psi \leq 1\}$.  Replacing $p$ by $\lambda p$ for an appropriate choice of $\lambda > 0$, there is no loss of generality assuming that $\langle p, x_{*} \rangle = \psi(x_{*})$.  Since $\langle p, q \rangle \leq 1$ for any $q \in \{\psi \leq 1\}$, one readily deduces by positive-homogeneity that $\langle p, y \rangle \leq \psi(y)$ for any $y \in \{\psi < +\infty\}$.  Thus, by Proposition \ref{P: subdifferential}, $p \in \partial \psi(x_{*})$.  

		The previous two paragraphs show that $p \in \partial \psi(x_{*})$ holds if and only if $p$ determines a supporting hyperplane to $\{\psi \leq 1\}$ through the point $\psi(x_{*})^{-1}x_{*}$.  Finally, recall that $\psi$ is differentiable at $x_{*}$ if and only if there is a vector $p \in \mathbb{R}^{d}$ such that $\partial \psi(x_{*}) = \{p\}$.\footnote{See \cite[Theorem 9.18]{rockafellar_wets} or \cite[Theorem 1.5.15]{schneider}.}  Therefore, $\psi$ is differentiable at $x_{*}$ if and only if there is a unique supporting hyperplane to $\{\psi \leq 1\}$ through $\psi(x_{*})^{-1}x_{*}$.

		Finally, if $\psi$ is differentiable at a point $x$, then the positive one-homogeneity of $\psi$ implies that $\psi$ is differentiable at each point of $\mathcal{C}(\{x\})$ and
	\begin{equation*}
		D\psi(x) = D\psi(\check{x}) = \|D\psi(\check{x})\| N(\check{x}),
	\end{equation*}
where $\check{x} = \psi(x)^{-1} x$ and $N(\check{x})$ is the outward normal vector to $\{\psi \leq 1\}$ at $\check{x}$. 
At the same time, by Proposition \ref{P: subdifferential}, 
	\begin{equation*}
		1 = \psi(\check{x}) = \langle D\psi(\check{x}), \check{x} \rangle,
	\end{equation*}
which implies that
	\begin{equation*}
		\|D\psi(\check{x})\|^{-1} = \langle N(\check{x}), \check{x} \rangle.
	\end{equation*}
Therefore,
	\begin{equation} \label{E: gradient formula}
		D\psi(x) = \langle N(\check{x}), \check{x} \rangle^{-1} N(\check{x}).
	\end{equation}
From this, one readily deduces that if $\{\psi \leq 1\}$ is a $C^{k}$ hypersurface locally in the interior of $\{\psi < +\infty\}$, then $D\psi$ is $C^{k -1}$ in that set and hence $\psi$ is $C^{k}$ there.  The converse follows immediately from the implicit function theorem.

\label{P: check proposition} Let $\psi : \mathbb{R}^{d} \to [0,+\infty]$ be a positively one-homogeneous convex function.  Assume that $\psi$ is locally $C^{1,1}$ in the interior of $\{\psi < +\infty\}$, and let $N : \{\psi = 1\} \to S^{d-1}$ be the (outward) normal vector to $\{\psi \leq 1\}$.  Define a map $x \mapsto \check{x}$ from $\{\psi < + \infty\}$ into $\{\psi = 1\}$ by 
		\begin{equation*}
			\check{x} = \frac{x}{\psi(x)}.
		\end{equation*}  
	Then, for every $x \in \{\psi < + \infty\}$ at which $D^{2}\psi(x)$ exists, there holds
		\begin{equation} \label{E: chain rule guy}
			D^{2}\psi(x) = \psi(x)^{-1} A(x) \cdot B(x),
		\end{equation}
	where $A$ and $B$ are the matrix fields given by 
		\begin{align*}
			A(x) &= \langle N(\check{x}),\check{x} \rangle^{-1} DN(\check{x}) - \langle N(\check{x}), \check{x} \rangle^{-2} (N(\check{x}) \otimes \check{x}) DN(\check{x}) - \langle N(\check{x}), \check{x} \rangle^{-2} N(\check{x}) \otimes N(\check{x}), \\
			B(x) &= \text{Id} - \check{x} \otimes D\psi(x).
		\end{align*}

\label{P: curvature bound for pos hom} Let $\psi : \mathbb{R}^{d} \to [0,+\infty]$ be a positively one-homogeneous convex function.  Assume that $\psi$ is locally $C^{1,1}$ in the open set $\text{int}(\{\psi < +\infty\})$, and define the map $x \mapsto \check{x}$ as in Proposition \ref{P: check proposition}.  Then
		\begin{align*}
			\|D^{2}\psi(x)\| \leq \psi(x)^{-1} \left[ 2 \left( 1 + \|D\psi(x)\|^{2} \right) \left(1 + \|\check{x}\| \right) (1 + \|DN(\check{x})\|) \right] \left( 1 + \|D\psi(x)\| \|\check{x}\| \right)		
		\end{align*}
	at any point in $x \in \text{int}(\{\psi < +\infty\})$ at which $D^{2}\psi(x)$ exists.

\label{P: trivial hessian estimate} There is a continuous function $\Gamma : (0,1) \to (0,1)$ such that, for any $\delta \in (0,1)$, the constant $\Gamma(\delta) > 0$ has the following property: suppose that $\psi : \mathbb{R}^{d} \to [0,+\infty]$ is a positively homogeneous convex function and $\psi$ is locally $C^{1,1}$ in the interior of $\{\psi < +\infty\}$, fix $\zeta \in (0,1)$, and let $A \subseteq \{\psi = 1\} \cap \overline{B}_{\delta^{-1}}(0)$.  If for any $q \in A$, there holds
		\begin{equation*}
			\|DN(q)\| \leq \zeta^{-1} \quad \text{and} \quad \|D\psi(q)\| \leq \delta^{-1},
		\end{equation*}
	then $\psi$ satisfies the Hessian estimate
		\begin{equation*}
			\psi(x) D^{2}\psi(x) \leq \Gamma(\delta) \zeta^{-1} \text{Id} \quad \text{for almost every} \quad x \in \mathcal{C}(A).
		\end{equation*}

Suppose that $x \in \mathcal{C}(A) \setminus \{0\}$, hence $x \in \mathbb{R}^{d} \setminus \{0\}$ and $\psi(x)^{-1}x \in \overline{B}_{\delta^{-1}}(0)$.  If $D^{2}\psi(x)$ exists, then Proposition \ref{P: curvature bound for pos hom} applies to give, by hypothesis,
			\begin{equation*}
				\psi(x) D^{2}\psi(x) \leq 2 ( 1 + \delta^{-1}) (1 + \delta^{-1}) (1 + \zeta^{-1}) (1 + \delta^{-2}).
			\end{equation*}
		Since $\max\{\zeta,\delta\} < 1$, this yields the desired estimate with $\Gamma(\delta) = 4 (1 + \delta^{-2})^{3}$.

\label{P: very easy gradient bound} Let $\varphi$ be a Finsler norm in $\mathbb{R}^{d}$.  If there is a $\delta > 0$ such that 
		\begin{equation*}
			\overline{B}_{\delta}(0) \subseteq \{\varphi \leq 1\},
		\end{equation*}
	then $\{\varphi^{*} \leq 1\} \subseteq \overline{B}_{\delta^{-1}}(0)$.  

	In particular, if $\varphi$ is $C^{1}$ away from the origin and $\overline{B}_{\delta}(0) \subseteq \{\varphi \leq 1\}$, then $\|D\varphi(x)\| \leq \delta^{-1}$ for each $x \in \mathbb{R}^{d} \setminus \{0\}$.

Assume that $\overline{B}_{\delta}(0) \subseteq \{\varphi \leq 1\}$, and fix $p \in \{\varphi^{*} = 1\}$.  If $q \in \partial B_{\delta}(0)$, then $q \in \{\varphi \leq 1\}$ and, thus, by duality,
			\begin{equation*}
				\langle q, p \rangle \leq \varphi(q) \varphi^{*}(p) \leq 1.
			\end{equation*}
		It follows that $\|p\| \leq \delta^{-1}$.  This proves $\{\varphi^{*} = 1\} \subseteq \overline{B}_{\delta^{-1}}(0)$, hence also $\{\varphi^{*} \leq 1\} \subseteq \overline{B}_{\delta^{-1}}(0)$ by scaling.

		Finally, if $\varphi$ is $C^{1}$ away from the origin and $\overline{B}_{\delta}(0) \subseteq \{\varphi \leq 1\}$, then, for any $x \in \mathbb{R}^{d} \setminus \{0\}$, the variational formula \eqref{E: subdifferential basic identity} implies that
			\begin{equation*}
				\{D\varphi(x)\} = \partial \varphi(x) \subseteq \{\varphi^{*} = 1\}.
			\end{equation*}
		Thus, $\|D\varphi(x)\| \leq \delta^{-1}$ for every $x \in \mathbb{R}^{d} \setminus \{0\}$.

\label{A: c11 assumption} $\varphi$ is a Finsler norm in $\mathbb{R}^{d}$ such that, for some $\zeta, \delta > 0$,
	\begin{gather}
		\{\varphi \leq 1\} \quad \text{satisfies an interior ball condition of radius} \, \, \zeta, \label{E: zeta interior ball} \\
		\overline{B}_{\delta}(0) \subseteq \{\varphi \leq 1\} \subseteq \overline{B}_{\delta^{-1}}(0). \label{E: nondegeneracy}
	\end{gather}

\label{T: technical core} Assume that $\varphi$ satisfies Assumption \ref{A: c11 assumption}.  Let $V \subseteq \mathbb{R}^{d} \setminus \{0\}$ be a bounded open set, fix $\alpha \in \mathbb{R}$, and let $\mathcal{H}$ be a function satisfying \eqref{Ass: continuity assumption} and \eqref{Ass: elliptic assumption}. 

	If $u \in USC(\overline{V})$ satisfies
		\begin{equation*}
			-\mathcal{H}(x,Du,D^{2}u,\mathcal{G}_{\varphi}^{*,\alpha}(Du,D^{2}u)) \leq 0 \quad \text{in} \, \, V,
		\end{equation*}
	and
		\begin{equation*}
			\max \{u(x) - \varphi(x) \, \mid \, x \in \overline{V} \} > \max \{u(x) - \varphi(x) \, \mid \, x \in \partial V \},
