		\end{gather*}
	Above $\Gamma(\delta)$ is the constant from Proposition \ref{P: trivial hessian estimate}.

\label{P: basic touching thing} Assume that $\varphi$ satisfies Assumption \eqref{A: c11 assumption}.  Let $V \subseteq \mathbb{R}^{d} \setminus \{0\}$ be a bounded open set, fix an $\alpha \in \mathbb{R}$, and let $\mathcal{H}$ be a function satisfying \eqref{Ass: continuity assumption} and \eqref{Ass: elliptic assumption}.

	Fix a $\nu \in (0,\zeta]$ and a $p \in \mathbb{R}^{d} \setminus \{0\}$.  Let $e = \|p\|^{-1} p$ and write $\psi_{\mu} = \psi_{e,\partial \varphi^{*}(p),\mu}$ for $\mu \in \{\nu,\zeta\}$.  Assume that there is an open set $\mathcal{U} \subseteq \mathbb{R}^{d}$, a constant $\epsilon_{*} > 0$, and a family of nonnegative functions $(\psi^{\epsilon}_{\nu})_{\epsilon \in (0,\nu)}$ such that $\mathcal{C}(\partial \varphi^{*}(p)) \subseteq \mathcal{U}$ and
		\begin{gather*}
			\psi_{\nu}^{\epsilon} \to \psi_{\nu} \quad \text{locally uniformly in} \, \, \mathcal{U} \quad \text{as} \quad \epsilon \to 0^{+}, \\
			\psi_{\nu}^{\epsilon} \quad \text{is smooth in} \, \, \mathcal{U} \quad \text{and} \quad \{\psi_{\nu}^{\epsilon} < + \infty\} = \mathcal{U} \quad \text{for each} \quad \epsilon \in (0,\epsilon_{*}).
		\end{gather*}

	If $u \in USC(\overline{V})$, $M \in \mathbb{R}$, and $x_{0} \in V \cap \mathcal{C}(\partial \varphi^{*}(p))$ are such that
