Since $X_{*} = \psi_{\nu}(x_{*})^{-1} Y_{*}$, it follows that $X_{*} q = 0$ for each $q \in F_{*}$.

Given a convex set $C \subseteq \mathbb{R}^{m}$ in dimension $m$, the normal cone $\mathcal{N}^{m}_{C}(x)$ to $C$ at a point $x \in C$ is the convex cone defined by 
		\begin{equation*}
			\mathcal{N}^{m}_{C}(x) = \bigcap_{y \in C} \left\{ v \in \mathbb{R}^{m} \, \mid \, \langle v, x \rangle \geq \langle v, y \rangle \right\}.
		\end{equation*}

\label{L: explicit normal cone} Let $\varphi$ be a Finsler norm in $\mathbb{R}^{d}$.  If  $q \in \{\varphi = 1\}$, then
		\begin{equation*}
			\mathcal{N}^{d}_{\{\varphi \leq 1\}}(q) = \mathcal{C}(\partial \varphi(q)).
		\end{equation*}

\label{L: upper semicontinuity} Let $C \subseteq \mathbb{R}^{m}$ be a convex set in dimension $m$.  The normal cone $\mathcal{N}^{m}_{C}$ is upper semicontinuous in the following sense: for any $x \in C$, if the limit superior of $\mathcal{N}^{m}_{C}$ at $x$ is defined by 
		\begin{equation*}
			\limsup_{y \to x} \mathcal{N}^{m}_{C}(y) = \overline{\bigcap_{\epsilon > 0} \bigcup_{y \in B_{\epsilon}(x)} \mathcal{N}^{m}_{C}(y)},
		\end{equation*}
	then 
		\begin{equation*}
			\limsup_{y \to x} \mathcal{N}^{m}_{C}(y) \subseteq \mathcal{N}^{m}_{C}(x) \quad \text{for each} \quad x \in C.
		\end{equation*}

If $v \in \limsup_{y \to x} \mathcal{N}^{m}_{C}(y)$, then there is a sequence $((x_{n},v_{n}))_{n \in \mathbb{N}} \subseteq C \times \mathbb{R}^{d}$ such that $(x_{n},v_{n}) \to (x,v)$ as $n \to +\infty$ and $v_{N} \in \mathcal{N}^{m}_{C}(x_{N})$ for all $N$.  If $y \in C$, then the definition of the normal cone implies that
			\begin{equation*}
				\langle v_{n}, x_{n} \rangle \geq \langle v_{n}, y \rangle \quad \text{for each} \quad n \in \mathbb{N},
			\end{equation*}
		which implies that $\langle v, x \rangle \geq \langle v, y \rangle$.  Since this is true for any $y \in C$, this proves $v \in \mathcal{N}^{m}_{C}(x)$ by definition.

\label{L: direction of approach}  Fix $m \in \mathbb{N}$ and let $C \subseteq \mathbb{R}^{m}$ be a convex set. Suppose that $x \in C$ and $p \in \mathcal{N}^{m}_{C}(x)$.  If there is a sequence $((x_{n},p_{n}))_{n \in \mathbb{N}} \subseteq C \times (\mathbb{R}^{d} \setminus \{p\})$ and a point $w' \in \mathbb{R}^{d}$ such that (i)  $(x_{n},p_{n}) \to (x,p)$ as $n \to +\infty$; (ii) $p_{N} \in \mathcal{N}^{m}_{C}(x_{N})$ for each $N \in \mathbb{N}$; and
		\begin{equation*}
			\text{(iii)} \quad w' = \lim_{n \to \infty} \frac{p_{n} - p}{\|p_{n} - p\|},
		\end{equation*}
	then
		\begin{equation*}
			\langle w', x \rangle = \max \left\{ \langle w', y \rangle \, \mid \, y \in C \, \, \text{such that} \, \, p \in \mathcal{N}^{m}_{C}(y) \right\}.
		\end{equation*}

Suppose that $y \in C$ and $p \in \mathcal{N}^{m}_{C}(y)$.  By the monotonicity formula \eqref{E: monotonicity formula},
			\begin{equation*}
				\langle p_{n} - p, x_{n} - y \rangle \geq 0.
			\end{equation*}
		Dividing by $\|p_{n} - p\|$ is harmless here, hence, after doing so and sending $n \to +\infty$, one finds
			\begin{equation*}
				\langle w', x - y\rangle \geq 0.
			\end{equation*}
		Since $y$ was arbitrary and $p \in \mathcal{N}^{m}_{C}(x)$, the desired conclusion is now immediate.

\label{L: intermediate key lemma} Let $G \subseteq \mathbb{R}^{d - 1}$ be a convex set, fix a $\nu > 0$, and define $g : \{\text{dist}(\cdot,G) \leq \nu\} \to [0,+\infty)$ and $g^{\epsilon} : \{\text{dist}(\cdot,G) \leq \nu - \epsilon\} \to [0,+\infty)$ by 
		\begin{equation*}
			g(x) = \sqrt{\nu^{2} - \text{dist}(x',G)^{2}}, \quad g^{\epsilon}(x') = \int_{\mathbb{R}^{d-1}} g(x' + \epsilon y') \rho(y') \, dy'.
		\end{equation*} 
	If $(\epsilon_{j})_{j \in \mathbb{N}} \subseteq (0,+\infty)$ is a sequence converging to zero and $(q_{j}')_{j \in \mathbb{N}} \subseteq \mathbb{R}^{d-1}$ satisfies
		\begin{equation} \label{E: nice convergence}
			\limsup_{j \to \infty} \epsilon_{j}^{-1} \text{dist}(q_{j}',G) < +\infty,
		\end{equation}
	then the blow-up sequence $(d_{j})_{j \in \mathbb{N}}$ defined by 
		\begin{equation*}
			d_{j}(y') = \epsilon_{j}^{-1} \text{dist}(q'_{j} + \epsilon_{j} y',G) = \text{dist}(y', \epsilon_{j}^{-1} (G - q'_{j}))
		\end{equation*}
	has a subsequence $(d_{j_{k}})_{k \in \mathbb{N}}$ that converges locally uniformly to a convex function $d_{*} : \mathbb{R}^{d-1} \to [0,+\infty)$, which is $C^{1}$ in the set $\{d_{*} > 0\}$.  Furthermore, the following formulas hold:
		\begin{align}
			\lim_{k \to \infty} \epsilon_{j_{k}}^{-1} Dg^{\epsilon_{j_{k}}}(q_{j_{k}}') &= - \nu^{-1} \int_{B_{1}} d_{*}(y') Dd_{*}(y') \, \rho(y') dy', \label{E: direction of approach} \\
			\lim_{k \to \infty} D^{2}g^{\epsilon_{j_{k}}}(q_{j_{k}}') &= - \nu^{-1} \int_{B_{1}} \left( d_{*}(y') D^{2}d_{*}(y') + Dd_{*}(y') \otimes Dd_{*}(y') \right) \rho(y') \, dy'. \label{E: curvature}
		\end{align}
	In addition, if the subsequence $(q'_{j_{k}})_{k \in \mathbb{N}}$ converges to some point $q'_{*} \in G$, then 
		\begin{equation} \label{E: key normal cone part}
			Dd_{*}(y') \in \mathcal{N}^{d-1}_{G}(q'_{*}) \quad \text{for each} \quad y' \in \{d_{*} > 0\}.
		\end{equation}

Actually, if $q_{j_{k}}' \to q_{*}'$ as in the final statement of the lemma, then one can further say that there is a shift $v' \in \mathbb{R}^{d-1}$ such that $d_{*}$ is given by 
	\begin{equation*}
		d_{*}(y') = \text{dist}(y', v' + \mathcal{T}_{G}(q_{*}')) = \text{dist}(y' - v', \mathcal{T}_{G}(q_{*}'),
	\end{equation*}
where $\mathcal{T}_{G}(q_{*}')$ is the tangent cone to $G$ at $q_{*}'$.\footnote{See \cite{rockafellar_wets} for the definition of tangent cones.}  Though it helps in understanding the geometric meaning of the lemma, this observation will not be needed in what follows.

Begin with a priori estimates: it is well-known that distance functions are uniformly Lipschitz with constant one, that is,
				\begin{equation*}
					\{d_{j}\}_{j \in \mathbb{N}} \subseteq W^{1,\infty}_{\text{loc}}(\mathbb{R}^{d-1}), \quad \|Dd_{j}\|_{L^{\infty}(\mathbb{R}^{d-1})} = 1 \quad \text{for each} \quad j \in \mathbb{N}.
				\end{equation*}
			At the same time, by hypothesis,
				\begin{equation*}
					\limsup_{j \to \infty} d_{j}(0) = \limsup_{j \to \infty} \epsilon_{j}^{-1} \text{dist}(q_{j}',G) < +\infty.
				\end{equation*}
			This establishes that $\{d_{j}\}_{j \in \mathbb{N}}$ is locally bounded in $\mathbb{R}^{d-1}$.

			It is convenient to obtain slightly more information about $\{d_{j}\}_{j \in \mathbb{N}}$.  First, observe that it is possible to write
				\begin{equation*}
					\frac{1}{2} d_{j}(y')^{2} = \min \left\{ \frac{1}{2} \|y' - \tilde{y}'\|^{2} \, \mid \, \tilde{y}' \in \epsilon_{j}^{-1}(G - x_{j}') \right\}.
				\end{equation*}
			Thus, since this last expression has the form of an inf-convolution,\footnote{See \cite[Section 11]{primer} or \cite[Appendix]{user}.} 
				\begin{equation*}
					-D^{2} \left\{ 2^{-1} d_{j}^{2}\right\} \geq -\text{Id} \quad \text{in the viscosity sense in} \, \, \mathbb{R}^{d-1}.
				\end{equation*}
			As already mentioned in the proof of Proposition \ref{P: approximate supersolution} above, such a viscosity inequality is equivalent to its distributional version, hence $D^{2}\{2^{-1}d_{j}^{2}\} \leq \text{Id}$ holds distributionally.  At the same time, since $G$ is convex, $d_{j}$ is convex for any $j$.  In particular, $2^{-1} d_{j}^{2}$ is also convex for all $j$.  It follows that
				\begin{equation*}
					0 \leq D^{2} \left\{ 2^{-1} d_{j}^{2} \right\} \leq \text{Id} \quad \text{in the sense of distributions in} \, \, \mathbb{R}^{d-1}.
				\end{equation*}
			Thus, $2^{-1} d_{j}^{2} \in W^{2,\infty}_{\text{loc}}(\mathbb{R}^{d-1})$ for any $j$ and the second derivative, which is \emph{a priori} just a Radon measure, is represented by a function in $L^{\infty}(\mathbb{R}^{d-1})$.  In particular, there is no abuse of notation writing it as
				\begin{equation*}
					D^{2}\{2^{-1} d_{j}^{2}\} = d_{j} D^{2} d_{j} + Dd_{j} \otimes Dd_{j}
				\end{equation*}
			since this formula holds almost everywhere; and the positivity of $Dd_{j} \otimes Dd_{j}$ implies
				\begin{equation*}
					0 \leq d_{j} D^{2} d_{j} \leq \text{Id} \quad \text{almost everywhere in} \, \, \mathbb{R}^{d-1}.
				\end{equation*}			

			At last, the previous arguments show that there is a subsequence $(j_{k})_{k \in \mathbb{N}} \subseteq \mathbb{N}$ and a nonnegative convex function $d_{*}$ such that
				\begin{gather*}
					d_{j_{k}} \to d_{*} \quad \text{locally uniformly in} \, \, \mathbb{R}^{d-1}, \\
					Dd_{j_{k}} \to Dd_{*} \quad \text{locally uniformly in} \, \, \{d_{*} > 0\},  \\
					d_{j_{k}} D^{2} d_{j_{k}} \overset{*}{\rightharpoonup} d_{*} D^{2}d_{*} \quad \text{weakly in} \, \, L^{\infty}(\mathbb{R}^{d - 1}).
				\end{gather*}
			In view of \eqref{E: first derivative key mountain} and \eqref{E: second derivative key mountain}, these convergences imply \eqref{E: direction of approach} and \eqref{E: curvature}. 

			It remains to prove that if $q_{j_{k}}' \to q_{*}'$ as $k \to +\infty$, then $Dd_{*}$ takes values in $\mathcal{N}^{d-1}_{G}(q'_{*})$.  Recall that if $q' \in \mathbb{R}^{d-1} \setminus \overline{G}$, then $D\text{dist}(q', G) = \|q' - [q']\|^{-1}(q' - [q'])$, where $[q']$ is the (unique) closest point in $G$ to $x'$.\footnote{See \cite[Section 1.2]{schneider} and \cite[Example 2.25]{rockafellar_wets}.}  In particular, $[q'] \in \partial G$ and $\|q' - [q']\|^{-1}(q' - [q'])$ is the normal vector to a supporting hyperplane to $G$ at $[q']$.  Thus,
				\begin{equation*}
					D\text{dist}(q',G) = \|q' - [q']\|^{-1}(q' - [q']) \in \mathcal{N}^{d-1}_{G}([q']).
				\end{equation*}
			After rescaling, this becomes
				\begin{equation*}
					Dd_{j}(y') \in \mathcal{N}^{d-1}_{G}([q_{j}' + \epsilon_{j} y']).
				\end{equation*}
			Clearly, $[q_{j}' + \epsilon y'] \to [q_{*}'] = q_{*}'$ as $\epsilon \to 0$.  Therefore, by the upper semicontinuity of $\mathcal{N}_{G}^{d-1}$ (i.e., Lemma \ref{L: upper semicontinuity}), for any $y' \in \{d_{*} > 0\}$,
				\begin{equation*}
					Dd_{*}(y') = \lim_{j \to \infty} Dd_{j_{k}}(y') \in \limsup_{q' \to q'_{*}} \mathcal{N}_{G}^{d-1}(q') \subseteq \mathcal{N}^{d-1}_{G}(q_{*}').
				\end{equation*}
			This proves that $Dd_{*}$ maps $\{d_{*} > 0\}$ into $\mathcal{N}^{d-1}_{G}(q'_{*})$.

Apply Lemma \ref{L: intermediate key lemma} with $G$ equal to $G_{p} = \partial \varphi^{*}(p) - \varphi^{*}(e) e$ (using the identification of $\{e\}^{\perp}$ with $\mathbb{R}^{d-1}$ to regard this as a convex set in $\mathbb{R}^{d-1}$) and the sequence $(q_{j}')_{j \in \mathbb{N}}$ determined as usual by projecting $(q_{j})_{j \in \mathbb{N}}$ to $\{e\}^{\perp}$, see \eqref{E: orthogonal projection part}.  The lemma asserts that there is a convex function $d_{*} : \mathbb{R}^{d-1} \to [0,+\infty)$ such that 
		\begin{equation} \label{E: gradient constraint}
			Dd_{*}(y') \in \mathcal{N}^{d-1}_{G_{p}}(q_{*}') \quad \text{for each} \quad y' \in \{d_{*} > 0\}.
		\end{equation}
	Further, note that the function $g$ in the statement of the lemma coincides with $g_{\nu}$ up to a constant, hence the conclusions concerning its derivatives imply the desired conclusions \eqref{E: first derivative thingy} and \eqref{E: second derivative thingy}.  In particular, there is a subsequence $(j_{k})_{k \in \mathbb{N}} \subseteq \mathbb{N}$ such that
		\begin{equation} \label{E: need this gradient business later}
			- \lim_{k \to \infty} \epsilon_{j_{k}}^{-1} Dg_{\nu}^{\epsilon_{j_{k}}}(q_{j_{k}}') = \nu^{-1} \int_{B_{1}} d_{*}(y') Dd_{*}(y') \, \rho(y') dy'
		\end{equation}
	As in the discussion preceding this proof, see \eqref{E: first derivative thingy}, denote this vector by $w_{*}'$.

	It remains to show that
		\begin{equation*}
			\langle w_{*}', q_{*} \rangle = \langle w_{*}', q_{**} \rangle = \max \left\{ \langle w_{*}', q \rangle \, \mid \, q \in \partial \varphi^{*}(p) \right\}.
		\end{equation*}
	This is trivial if $w_{*}' = 0$; hence, in the rest of the proof, assume that $w_{*}' \neq 0$.  

	Start with $q_{**}$, the easier of the two: this part is a straightforward application of Lemma \ref{L: direction of approach}.  Consider the convex set $\{\varphi \leq 1\} \subseteq \mathbb{R}^{d}$.  For any $j \in \mathbb{N}$, one knows that $\tilde{q}_{j} \in \partial \varphi^{*}(D\psi_{\nu}^{\epsilon_{j}}(q_{j}))$ by hypothesis and, thus, by inversion \eqref{E: inversion},
		\begin{equation*}
			\varphi^{*}(D\psi_{\nu}^{\epsilon_{j}}(q_{j}))^{-1} D\psi_{\nu}^{\epsilon_{j}}(q_{j}) \in \partial \varphi(\tilde{q}_{j}).
		\end{equation*}
	From this and Lemma \ref{L: explicit normal cone}, it follows that if one defines the sequence $(\hat{p}_{j})_{j \in \mathbb{N}}$ by letting $\hat{p}_{j} = \|D\psi_{\nu}^{\epsilon_{j}}(q_{j})\|^{-1} D\psi_{\nu}^{\epsilon_{j}}(q_{j})$, then
		\begin{equation*}
			\hat{p}_{j} \in \mathcal{N}^{d}_{\{\varphi \leq 1\}}(\tilde{q}_{j}) \quad \text{for each} \quad j \in \mathbb{N}.
		\end{equation*}
	Furthermore, since $q_{j} \to q_{*}$ as $j \to +\infty$ and $q_{*} \in \partial \varphi^{*}(p)$, Proposition \ref{P: touching above test function part} says that $\varphi$ touches $\psi_{\nu}$ from below at $x_{*}$.  Thus,
		\begin{equation*}
			\lim_{j \to \infty} D\psi_{\nu}^{\epsilon_{j}}(q_{j}) = D\psi_{\nu}(q_{*}) = D\varphi(q_{*}) \overset{\eqref{E: subdifferential basic identity}}{=} \varphi^{*}(p)^{-1} p,
		\end{equation*}
	It follows that $\hat{p}_{j} \to e$ as $j \to +\infty$.  At the same time, by the definition \eqref{E: first derivative thingy} of $w_{*}'$ and the representation formula \eqref{E: classical normal vector formula}, 
		\begin{equation*}
			\lim_{k \to \infty} \frac{\hat{p}_{j_{k}} - e}{\|\hat{p}_{j_{k}} - e\|} = \frac{w_{*}'}{\|w_{*}'\|}.
		\end{equation*}
	At last, by Lemma \ref{L: direction of approach} applied to $(\tilde{q}_{j_{k}},\hat{p}_{j_{k}})_{k \in \mathbb{N}}$, plus another application of Lemma \ref{L: explicit normal cone},
		\begin{align*}
			\langle w_{*}', q_{**} \rangle &= \max \left\{ \langle w_{*}', q \rangle \, \mid \, q \in \{\varphi \leq 1\} \, \, \text{such that} \, \, e \in \mathcal{N}^{d}_{\{\varphi \leq 1\}}(q) \right\} \\
				&= \max \left\{ \langle w_{*}', q \rangle \, \mid \, q \in \partial \varphi^{*}(e) \right\} \overset{\eqref{E: zero hom}}{=} \max \left\{ \langle w_{*}', q \rangle \, \mid \, q \in \partial \varphi^{*}(p) \right\}.
		\end{align*}





	It remains to consider $q_{*}$.  This boils down to yet another application of Lemma \ref{L: direction of approach}, except for the (nontrivial) complication that the convex set in question varies with $j$.  

	For any $j$, consider the convex set $C_{j} = \{\psi_{\nu}^{\epsilon_{j}} \leq 1\} \subseteq \mathbb{R}^{d}$.  By assumption, $q_{j} \in \partial C_{j}$ for any $j$ and $q_{j} \to q_{*}$ as $j \to +\infty$.  By the discussion preceding Lemma \ref{L: explicit normal cone},		
	\begin{equation*}
			\hat{p}_{j} = \|D\psi_{\nu}^{\epsilon_{j}}(q_{j})\|^{-1} D\psi_{\nu}^{\epsilon_{j}}(q_{j}) \in \mathcal{N}^{d}_{C_{j}}(q_{j}) \quad \text{for each} \quad j \in \mathbb{N}.
		\end{equation*}
	At the same time, if the set $[\partial \varphi^{*}(p)]^{(\mu)}$ is defined for $\mu > 0$ by
		\begin{equation*}
			[\partial \varphi^{*}(p)]^{(\mu)} = \left\{q \in \partial \varphi^{*}(p) \, \mid \, \text{dist}(q, \text{bdry}(\partial \varphi^{*}(p))) \geq \mu \right\}, 
		\end{equation*}
	then it is not difficult to show that, for any $\epsilon < \mu$,
		\begin{equation*}
			\|D\psi_{\nu}^{\epsilon}(q)\|^{-1} D\psi_{\nu}^{\epsilon}(q) = e \quad \text{for each} \quad q \in [\partial \varphi^{*}(p)]^{(\mu)};
		\end{equation*}
	see Proposition \ref{P: flatness prop} in Appendix \ref{App: flatness} for the proof.  In particular, for any $\mu > 0$, there is a $J(\mu) \in \mathbb{N}$ such that if $j \geq J(\mu)$, then
		\begin{equation*}
			e \in \mathcal{N}^{d}_{C_{j}}(q) \quad \text{for each} \quad q \in [\partial \varphi^{*}(p)]^{(\mu)}.
		\end{equation*}
	Thus, by the monotonicity formula \eqref{E: monotonicity formula}, for any $j \geq J(\mu)$,
		\begin{equation*}
			\langle \hat{p}_{j} - e, q_{j} - q \rangle \geq 0 \quad \text{for each} \quad q \in [\partial \varphi^{*}(p)]^{(\mu)}.
		\end{equation*}
	Dividing by $\|\hat{p}_{j} - e\|$ and sending $j \to +\infty$, this becomes
		\begin{equation*}
			\langle w_{*}', q_{*} - q \rangle \geq 0 \quad \text{for each} \quad q \in [\partial \varphi^{*}(p)]^{(\mu)}.
		\end{equation*}
	In the limit $\mu \to 0^{+}$, this yields the remaining half of \eqref{E: optimality condition directional}.

\label{L: cone integral} Given any dimension $m \in \mathbb{N}$ and any closed convex cone $\mathcal{N} \subseteq \mathbb{R}^{m}$, let $\mu$ be a finite positive Borel measure on $\mathcal{N}$ and let $\mathcal{N}'$ be a face of $\mathcal{N}$.  If $\int_{\mathcal{N}} \|v\| \, \mu(dv) < +\infty$ and the mean of $\mu$ is in $\mathcal{N}'$, that is,
		\begin{equation*}
			\int_{\mathcal{N}} v \, \mu(dv) \in \mathcal{N}',
		\end{equation*}
then $\mu$ is supported on $\mathcal{N}'$ (i.e., $\mu(\mathcal{N} \setminus \mathcal{N}') = 0$).

The Hessian bounds \eqref{E: hessian bounds ack ack} follow from the estimates in Section \ref{S: pos hom}.  Indeed, at the limit point $q_{*}$, one knows that $D\psi_{\nu}(q_{*}) = D\varphi(q_{*})$, and control over $D\varphi$ is furnished by the $\delta$-nondegeneracy condition \eqref{E: nondegeneracy}.  Similarly, control over the curvature of the level sets of the sequence $\{\psi^{\epsilon_{j}}_{\nu}\}_{j \in \mathbb{N}}$ can be gleaned from the explicit formula for the second derivative of $g_{\nu}^{\epsilon_{j}}$.  For the full details, the reader is referred to Lemma \ref{L: key hessian control} in Appendix \ref{A: technical results}. 

That only leaves the more interesting statement, namely, the Hessian constraint \eqref{E: hessian constraint}.  Toward that end, it suffices to establish that 
	\begin{equation} \label{E: A constant part}
		A_{*}'( q - q_{*}) = 0 \quad \text{for each} \quad q \in F_{*}.
	\end{equation}
To see why, assume for the moment that \eqref{E: A constant part} holds.  Note that $Y_{*}q_{*} = 0$ since, by positive homogeneity,
	\begin{align*}
		Y_{*}q_{*} = \lim_{k \to \infty} D^{2}\psi_{\nu}^{\epsilon_{j_{k}}}(q_{j_{k}}) q_{j_{k}} = \lim_{k \to \infty} (0) = 0.
	\end{align*} Therefore, for any $q \in F_{*}$,
	\begin{align*}
		\langle Y_{*} q, q \rangle &= \langle Y_{*}(q - q_{*}), q - q_{*} \rangle.
	\end{align*}
At the same time, since $F_{*} \subseteq \partial \varphi^{*}(p) = \partial \varphi^{*}(e)$, the representation \eqref{E: subdifferential basic identity dual} implies that $q - q_{*} = (\text{Id} - e \otimes e) (q - q_{*})$ for any $q \in F_{*}$.  Thus, by the discussion preceding Lemma \ref{L: cone integral},
	\begin{align*}
		\langle Y_{*}q,q \rangle &= \langle (\text{Id} - e \otimes e) Y_{*} (\text{Id} - e \otimes e) (q - q_{*}), q - q_{*} \rangle \\
			&= \|D\psi_{\nu}(q_{*})\| \langle A_{*}'(q - q_{*}), q - q_{*} \rangle = 0.
	\end{align*}
Since $Y_{*} \geq 0$ by convexity, the identity $\langle Y_{*}q,q \rangle = 0$ actually implies $Y_{*}q = 0$.  Therefore, \eqref{E: A constant part} implies \eqref{E: hessian constraint} as claimed.

It only remains to prove \eqref{E: A constant part}.  For the rest of the proof, $G_{p}$ is treated as a subset of $\mathbb{R}^{d-1}$ so that $\mathcal{N}_{G_{p}}^{d-1}$ makes sense.  In what follows, given a vector $w' \in \mathcal{N}^{d-1}_{G_{p}}(q_{*}')$, let $\tilde{\mathcal{N}}(w')$ denote the face of $\mathcal{N}^{d-1}_{G_{p}}(q_{*}')$ such that 
	\begin{equation*}
		w' \in \text{rint}(\tilde{\mathcal{N}}(w')).
	\end{equation*}
By \eqref{E: face partition}, there is a unique such face, hence the map $w' \mapsto \tilde{\mathcal{N}}(w')$ is well-defined.

To ease the exposition, the proof will be presented arguing by cases.

\textit{Case: $w_{*}' = 0$ and $\tilde{\mathcal{N}}(0) = \{0\}$.} 

This case is particularly simple.  By \eqref{E: direction of approach},
	\begin{equation*}
		\int_{B_{1} \cap \{d_{*} > 0\}} d_{*}(y') Dd(y') \rho(y') \, dy = \int_{B_{1}} d_{*}(y') Dd(y') \rho(y') \, dy = w_{*}' = 0.
	\end{equation*}
At the same time, since $Dd_{*} \in \mathcal{N}^{d-1}_{G_{p}}(q_{*}')$ pointwise by \eqref{E: gradient constraint}, this last integral has the form described in Lemma \ref{L: cone integral}.  Applying that lemma with $\mathcal{N} = \mathcal{N}^{d-1}_{G_{p}}(q_{*}')$, $\mathcal{N}' = \{0\}$, and $\mu$ the measure on $\mathcal{N}^{d-1}_{G_{p}}(q_{*}')$ given by 
	\begin{equation*}
		\int_{\mathcal{N}^{d-1}_{G_{p}}(q_{*}')} f(v) \, \mu(dv) = \int_{B_{1} \cap \{d_{*} > 0\}} f(d_{*}(y') Dd_{*}(y')) \rho(y') \, dy',
	\end{equation*} 
one finds
	\begin{equation}
		Dd_{*}(y') = 0 \quad \text{for each} \quad y' \in \{d_{*} > 0\} \cap B_{1}.
	\end{equation}
It follows that $D^{2}d_{*}(y') = 0$ for a.e.\ $y' \in B_{1}$, and, thus, $A_{*}' = 0$ by \eqref{E: curvature}.  Hence \eqref{E: A constant part} holds trivially in this case.

\textit{Case: $w_{*}' = 0$ and $\tilde{\mathcal{N}}(0) \neq \{0\}$.}  

First, it is useful to note that $\tilde{\mathcal{N}}(0)$ has a special form: specifically, $\tilde{\mathcal{N}}(0)$ is what is referred to in \cite{rockafellar} as the \emph{lineality} of $\mathcal{N}^{d-1}_{G_{p}}(q_{*}')$, that is, the maximal linear subspace of $\mathbb{R}^{d-1}$ contained in $\mathcal{N}^{d-1}_{G_{p}}(q_{*}')$.  At the same time, by the definition of normal cone, this is equivalent to saying that $\tilde{\mathcal{N}}(0)$ is the maximal subspace of $\mathbb{R}^{d-1}$ such that 
	\begin{equation} \label{E: vanishing thing}
		G_{p} - q_{*}' \subseteq \tilde{\mathcal{N}}(0)^{\perp}.
	\end{equation}


Next, applying Lemma \ref{L: cone integral} as in the last case, observe that the inclusion $w_{*}' = 0 \in \tilde{\mathcal{N}}(0)$ implies that
	\begin{equation*}
		Dd_{*}(y') \in \tilde{\mathcal{N}}(0) \quad \text{for each} \quad y' \in B_{1} \cap \{d_{*} > 0\}.
	\end{equation*}
Since $\tilde{\mathcal{N}}(0)$ is a linear space, the last inclusion can be differentiated to find
	\begin{equation*}
		D^{2}d_{*}(y')(\mathbb{R}^{d-1}) \subseteq \tilde{\mathcal{N}}(0) \quad \text{for a.e.} \quad y' \in B_{1} \cap \{d_{*} > 0\}.
	\end{equation*}
Integrating over $B_{1} \cap \{d_{*} > 0\}$, one finds from \eqref{E: curvature} that $A_{*}'$ has the same property, that is, the range of $A_{*}'$ is contained in $\tilde{\mathcal{N}}(0)$.  Hence, since $A_{*}'$ is a symmetric matrix,
	\begin{equation} \label{E: first kernel condition}
		\tilde{\mathcal{N}}(0)^{\perp} \subseteq \text{Ker}(A_{*}'),
	\end{equation}
where $\text{Ker}(A_{*}')$ denotes the kernel of $A_{*}'$.

Combining \eqref{E: vanishing thing} and \eqref{E: first kernel condition}, one deduces that, for any $q' \in G_{p}$,
	\begin{equation*}
		A_{*}'(q' - q_{*}') = 0.
	\end{equation*}
Since $\partial \varphi^{*}(p) = G_{p} + \varphi^{*}(e) e$, this implies that
	\begin{equation*}
		A_{*}'(q - q_{*}) = 0 \quad \text{for each} \quad q \in \partial \varphi^{*}(p),
	\end{equation*}
which is nothing but \eqref{E: A constant part}.


\textit{Case: $w_{*}' \neq 0$.}  

This case is very similar to the previous one in so far as the use of the map $w' \mapsto \tilde{\mathcal{N}}(w')$ is concerned.  By definition of $F_{*}$ (i.e., \eqref{E: F* definition}), one knows that
	\begin{equation} \label{E: linear relation}
		\langle w_{*}', q \rangle = \langle w_{*}', q_{*} \rangle \quad \text{for each} \quad q \in F_{*}. 
	\end{equation}
In particular,
	\begin{equation*}
		F_{*} - q_{*} \subseteq \{ w_{*}' \}^{\perp}.
	\end{equation*}
In fact, this can be upgraded to
	\begin{equation} \label{E: perpendicular part}
		F_{*} - q_{*} \subseteq \tilde{\mathcal{N}}(w_{*}')^{\perp}.
	\end{equation}

Indeed, to see that \eqref{E: perpendicular part} holds, suppose that $q \in F_{*}$ and let $q'$ denote its orthogonal projection to $\{e\}^{\perp}$ as usual.  By \eqref{E: linear relation}, 
	\begin{equation*}
		w_{*}' \in \{w' \in \mathcal{N}^{d-1}_{G_{p}}(q_{*}') \, \mid \, \langle w', q \rangle = \langle w', q_{*} \rangle \} =: \mathcal{N}''(q).
	\end{equation*}
At the same time, $\mathcal{N}''(q)$ is an exposed face of $\mathcal{N}^{d-1}_{G_{p}}(q_{*}')$ since, by the definition of normal cone and the fact that $\mathbb{R}^{d-1}$ is being identified with $\{e\}^{\perp}$,
	\begin{equation*}
		\langle w', q \rangle = \langle w', q' \rangle \leq \langle w', q'_{*} \rangle = \langle w', q_{*} \rangle \quad \text{for each} \quad w' \in \mathcal{N}^{d-1}_{G_{p}}(q_{*}').
	\end{equation*}
Therefore, since $w_{*}' \in \text{rint}(\tilde{\mathcal{N}}(w_{*}')) \cap \mathcal{N}''(q)$, the defining property of faces (Definition \ref{D: face}) implies
	\begin{equation*}
		\tilde{\mathcal{N}}(w_{*}') \subseteq \mathcal{N}''(q).
	\end{equation*}
Since $q$ was arbitrary, this leads to the inclusion $\tilde{\mathcal{N}}(w_{*}') \subseteq \bigcap_{q \in F_{*}} \mathcal{N}''(q)$, which is equivalent to \eqref{E: perpendicular part}.

Finally, once again, Lemma \ref{L: cone integral} implies that
	\begin{equation*}
		Dd_{*}(y') \in \tilde{\mathcal{N}}(w_{*}') \quad \text{for each} \quad y' \in B_{1} \cap \{d_{*} > 0\},
	\end{equation*}
and hence
	\begin{equation*}
		D^{2}d_{*}(y')(\mathbb{R}^{d-1}) \subseteq \text{span}(\tilde{\mathcal{N}}(w_{*}')) \quad \text{for a.e.} \quad y' \in B_{1} \cap \{d_{*} > 0\},
	\end{equation*}
where $\text{span}(\tilde{\mathcal{N}}(w_{*}'))$ denotes the linear span of $\tilde{\mathcal{N}}(w_{*}')$.
In particular, combining this last observation with \eqref{E: perpendicular part}, one concludes as in the last step that
	\begin{equation*}
		F_{*} - q_{*} \subseteq \tilde{\mathcal{N}}(w_{*}')^{\perp} \subseteq \text{Ker}(A_{*}'),
	\end{equation*}
which is precisely \eqref{E: A constant part}.  The proof of \eqref{E: hessian constraint} is complete.

\label{P: technical core eaten} Let $\varphi$ be a Finsler norm in $\mathbb{R}^{d}$ and let $(\varphi_{\zeta})_{\zeta > 0}$ be the regularized norms of Theorem \ref{T: regularized_norm}.  Let $V \subseteq \mathbb{R}^{d} \setminus \{0\}$ be a bounded open set, and let $\mathcal{H}$ be a function satisfying \eqref{Ass: continuity assumption} and \eqref{Ass: elliptic assumption}.

	If $u \in USC(\overline{V})$ satisfies
		\begin{equation*}
			-\mathcal{H}(x,Du,D^{2}u,G_{\varphi}^{*}(Du,D^{2}u)) \leq 0 \quad \text{in} \, \, V,
		\end{equation*}
	and if there is a $\zeta \in (0,1)$ such that 
		\begin{equation*}
			\max \{u(x) - \varphi_{\zeta}(x) \, \mid \, x \in \overline{V} \} > \max \{u(x) - \varphi_{\zeta}(x) \, \mid \, x \in \partial V \},
		\end{equation*}
	then there is a triple $(x_{*},X_{*},q_{**}) \in V \times \mathcal{S}_{d} \times \{\varphi_{\zeta} = 1\}$ such that
		\begin{gather*}
			u(x_{*}) - \varphi_{\zeta}(x_{*}) = \max \{u(x) - \varphi_{\zeta}(x) \, \mid \, x \in \overline{V} \}, \\
			- \mathcal{H}(x_{*},D\varphi_{\zeta}(x_{*}),X_{*}, Q_{X_{*}}(q_{**} - \zeta \|D\varphi_{\zeta}(x_{*})\|^{-1} D\varphi_{\zeta}(x_{*}))) \leq 0, \\
			X_{*} q_{**} = 0, \quad \text{and} \quad 0 \leq \varphi_{\zeta}(x_{*}) X_{*} \leq \tilde{\Gamma}(\varphi) \zeta^{-1} \text{Id},
		\end{gather*}
	where $\tilde{\Gamma}(\varphi) > 0$ depends only on $\varphi$.

This is an application of Theorem \ref{T: technical core}.  Indeed, reasoning as in Section \ref{S: c11 reduction}, one observes that
	\begin{equation*}
		-\mathcal{H}(x,Du,D^{2}u,\mathcal{G}_{\varphi_{\zeta}}^{\zeta}(Du,D^{2}u)) \leq 0 \quad \text{in} \, \, V.
	\end{equation*}
Furthermore, $\varphi_{\zeta}$ satisfies \eqref{E: zeta interior ball} with radius $\zeta$ and \eqref{E: nondegeneracy} with constant $\delta = \delta(\varphi)$ by Theorem \ref{T: regularized_norm}.  Taken together with the other hypotheses, these observations establish that Theorem \ref{T: technical core} applies, and the theorem directly yields the desired conclusion with $\tilde{\Gamma}(\varphi) := \Gamma(\delta(\varphi))$.

\label{P: technical core eaten curved} Let $\varphi$ be a Finsler norm in $\mathbb{R}^{d}$ and let $(\varphi_{\zeta})_{\zeta > 0}$ be the regularized norms of Theorem \ref{T: regularized_norm}.  Let $V \subseteq \mathbb{R}^{d} \setminus \{0\}$ be a bounded open set, and let $\mathcal{H}$ be a function satisfying \eqref{Ass: continuity assumption} and \eqref{Ass: elliptic assumption}.  Suppose that $h : \mathbb{R} \to \mathbb{R}$ is smooth and increasing.

	If $u$ is an upper semicontinuous function in $\overline{V}$ satisfying
		\begin{equation*}
			-\mathcal{H}(x,Du,D^{2}u,G_{\varphi}^{*}(Du,D^{2}u)) \leq 0 \quad \text{in} \, \, V,
		\end{equation*}
	and if there is a point $x_{0} \in V$ and a $\zeta \in (0,1)$ such that 
		\begin{equation*}
			u(x_{0}) - h(\varphi_{\zeta}(x_{0})) = \max \{u(x) - h(\varphi_{\zeta}(x)) \, \mid \, x \in \overline{V} \} > \max \{u(x) - h(\varphi_{\zeta}(x)) \, \mid \, x \in \partial V \},
		\end{equation*}
	then there is a triple $(x_{*},X_{*},q_{**}) \in V \times \mathcal{S}_{d} \times \{\varphi_{\zeta} = 1\}$ such that
		\begin{gather}
			u(x_{*}) - h(\varphi_{\zeta}(x_{*})) = \max \{u(x) - h(\varphi_{\zeta}(x)) \, \mid \, x \in \overline{V} \}, \label{E: equality thing we need ack} \\
			- \mathcal{H}(x_{*},h'(u(x_{*}))D\varphi_{\zeta}(x_{*}),X_{*}^{h}, Q_{X^{h}_{*}}(q_{**} - \zeta \|D\varphi_{\zeta}(x_{*})\|^{-1} D\varphi_{\zeta}(x_{*}))) \leq 0, \nonumber \\
			X_{*} q_{**} = 0, \quad \text{and} \quad 0 \leq \varphi_{\zeta}(x_{*}) X_{*} \leq c(\varphi) \zeta^{-1} \text{Id}, \nonumber
		\end{gather}
		where $X^{h}_{*}$ is derived from $h$, $X_{*}$, and $x_{*}$ via the rule
		\begin{equation*}
			X^{h}_{*} = h'(u(x_{*})) X_{*} + h''(u(x_{*})) D\varphi_{\zeta}(x_{*}) \otimes D\varphi_{\zeta}(x_{*}).
		\end{equation*}

By hypothesis, there is an $r > 0$ such that if $\overline{B}_{r}(\partial V) = \bigcup_{y \in \partial V} \overline{B}_{r}(y)$, then
			\begin{equation*}
				\max \{u(x) - h(\varphi_{\zeta}(x)) \, \mid \, x \in \overline{V} \} > \max \{u(x) - h(\varphi_{\zeta}(x)) \, \mid \, x \in \overline{B}_{r}(\partial V) \}.
			\end{equation*}
		To begin with, there is no loss of generality assuming that $h'$ is positive and $h(\mathbb{R}) = \mathbb{R}$; otherwise, one can perturb $h$ by setting $h_{\epsilon}(u) = h(u) + \epsilon u$, and then recover the desired result in the limit $\epsilon \to 0^{+}$.

		Up to subtracting a constant from $u$, which does not change the equation, one can assume that
			\begin{equation*}
				\max\left\{ u(x) - h(\varphi_{\zeta}(x)) \, \mid \, x \in \overline{V} \right\} = 0,
			\end{equation*}
		hence $u \leq h(\varphi_{\zeta})$ holds in $\overline{V}$ with equality at some point in $V$.

		In particular, if $v = h^{-1}(u)$, then
			\begin{equation*}
				\max \left\{ v(x) - \varphi_{\zeta}(x) \, \mid \, x \in \overline{V} \right\} = 0 > \max \left\{v(x) - \varphi_{\zeta}(x) \, \mid \, x \in \overline{B}_{r}(\partial V) \right\}.
			\end{equation*}

		A straightforward computation shows that $v$ satisfies
			\begin{equation*}
				-\mathcal{H}(x,h'(u(x)) Dv, \mathcal{X}(v,Dv,D^{2}v), G_{\varphi}^{*}(h'(u(x))Dv, \mathcal{X}(u(x),Dv,D^{2}v))) \leq 0 \quad \text{in} \, \, V,
			\end{equation*}
		where $\mathcal{X} : \mathbb{R} \times \mathbb{R}^{d} \times \mathcal{S}_{d} \to \mathcal{S}_{d}$ is the map
			\begin{equation*}
				\mathcal{X}(u,p,X) = h'(u) X + h''(u) p \otimes p.
			\end{equation*}
		This differential inequality fits into the framework of Proposition \ref{P: technical core eaten}.  Therefore, by that proposition, there is a triple $(x_{*},X_{*},q_{**}) \in V \times \mathcal{S}_{d} \times \{\varphi = 1\}$ such that 
			\begin{gather}
				v(x_{*}) - \varphi_{\zeta}(x_{*}) = 0 = \max \left\{ v(x) - \varphi(x) \, \mid x \in \overline{V} \right\}, \label{E: monotonicity use here ack} \\
				- \mathcal{H}(x_{*}, h'(u(x_{*})) D\varphi_{\zeta}(x_{*}), X^{h}_{*}, Q_{X^{h}_{*}}(q_{**} - \zeta \|D\varphi_{\zeta}(x_{*})\|^{-1} D\varphi_{\zeta}(x_{*}))) \leq 0, \label{E: equation for the umpteenth time} \\
				X_{*} q^{\epsilon}_{**} = 0, \quad \text{and} \quad 0 \leq \varphi_{\zeta}(x_{*}) X_{*} \leq c(\varphi) \zeta^{-1} \text{Id}. \label{E: another bound}
			\end{gather}
		where $X^{h}_{*} = \mathcal{X}(u(x_{*}), D\varphi_{\zeta}(x_{*}),X_{*})$. 
	Note that \eqref{E: monotonicity use here ack} implies \eqref{E: equality thing we need ack} since $h$ is monotone.  Therefore, the proof is complete.

\label{T: penalized problem comparison} Let $\varphi$ be a Finsler norm in $\mathbb{R}^{d}$, $U \subseteq \mathbb{R}^{d}$ be a bounded open set, and $\mathcal{H}$ be a continuous function such that \eqref{E: strict monotonicity operator} and \eqref{E: regularity operator} both hold for some fixed parameters $\lambda(\mathcal{H}) > 0$ and $\zeta(\mathcal{H}) \in (0,1)$.  If $u \in USC(\overline{U})$ and $v \in LSC(\overline{U})$ are such that 
		\begin{gather*}
			-\mathcal{H}(x,u,Du,D^{2}u,\mathcal{G}_{\varphi}^{*}(Du,D^{2}u)) \leq 0 \quad \text{in} \, \, U, \\
			- \mathcal{H}(x,v,Dv,D^{2}v,\mathcal{G}_{*}^{\varphi}(Dv,D^{2}v)) \geq 0 \quad \text{in} \, \, U, \\
			\text{and} \quad \max \left\{ u(x) - v(x) \, \mid \, x \in \partial U \right\} \leq 0,
		\end{gather*}
	then 
		\begin{equation*}
			\max \left\{ u(x) - v(x) \, \mid \, x \in \overline{U} \right\} \leq 0.
		\end{equation*}

\label{P: doubling variables} Let $\varphi$ be a Finsler norm and $U \subseteq \mathbb{R}^{d}$ be a bounded open set.  Given a parameter $\zeta \in (0,1)$, let $\varphi_{\zeta}$ be the regularized version of $\varphi$ from Theorem \ref{T: regularized_norm}.  Let $\mathcal{H} : \mathbb{R}^{d} \times \mathbb{R} \times \mathbb{R}^{d} \times \mathcal{S}_{d} \times \mathbb{R} \to \mathbb{R}$ be a function satisfying assumptions \eqref{Ass: continuity assumption} and \eqref{Ass: elliptic assumption}.  

	Suppose that $u \in USC(\overline{U})$ and $v \in LSC(\overline{U})$ are such that
		\begin{align}
			-\mathcal{H}(x,u,Du,D^{2}u,G_{\varphi}^{*}(Du,D^{2}u)) &\leq 0 \quad \text{in} \, \, U, \label{E: we are doubling variables 1}\\
			-\mathcal{H}(x,u,Dv,D^{2}v,G_{*}^{\varphi}(Dv,D^{2}v)) &\geq 0 \quad \text{in} \, \, U. \label{E: we are doubling variables 2}
		\end{align}

	If for some $\beta > 0$ one has that
		\begin{align}
			\sup &\left\{ u(x) - v(y) - \frac{\varphi_{\zeta}(x-y)^{4}}{4 \beta} \, \mid \, (x,y) \in U \times U \right\} \label{E: nondegenerate boundary assumption} \\
				&\qquad > \max \left\{ u(x) - v(y) - \frac{\varphi_{\zeta}(x -y)^{4}}{4 \beta} \, \mid \, (x,y) \in \partial(U \times U) \right\}, \nonumber
		\end{align}
	then there are triples $(x_{*},X_{*},q^{u}_{**}), (y_{*},Y_{*},q^{v}_{**}) \in U \times \mathcal{S}_{d} \times \{\varphi_{\zeta} = 1\}$ and a constant $C(\varphi) > 0$ depending only on $\varphi$ such that, after defining $T_{*} \geq 0$ and $\mu_{*} \in \mathbb{R}^{d}$ by
		\begin{equation*}
			T_{*} = \beta^{-1} \varphi_{\zeta}(x_{*} - y_{*})^{2}, \quad \mu_{*} = \left\{ \begin{array}{r l}
			 			\beta^{-1} \varphi_{\zeta}(x_{*} - y_{*})^{3} D\varphi_{\zeta}(x_{*} - y_{*}), & \text{if} \, \, x_{*} \neq y_{*}, \\
						0, & \text{otherwise,}
					\end{array} \right.
		\end{equation*} 
	one has
		\begin{gather}
			u(x_{*}) - v(y_{*}) - \frac{\varphi_{\zeta}(x_{*} - y_{*})^{4}}{4 \beta} \qquad \qquad \qquad \qquad \qquad\qquad \label{E: big maximization} \\
			\quad \qquad \qquad \qquad = \max\left\{ u(x) - v(y) - \frac{\varphi_{\zeta}(x-y)^{4}}{4 \beta} \, \mid \, (x,y) \in \overline{U} \times \overline{U} \right\}, \nonumber \\
			-\mathcal{H}(x_{*},u(x_{*}),\mu_{*}, X_{*}, Q_{X_{*}}(q_{**}^{u} - \zeta \|\mu_{*}\|^{-1} \mu_{*})) \leq 0 \quad \text{if} \, \, x_{*} \neq y_{*}, \label{E: big equation 1} \\
			-\mathcal{H}(x_{*},u(x_{*}),0,0,0) \leq 0 \quad \text{if} \, \, x_{*} = y_{*}, \label{E: big equation 1 star}, \\
			-\mathcal{H}(y_{*},u(y_{*}),\mu_{*},Y_{*}, Q_{Y_{*}}(q^{v}_{**} - \zeta \|\mu_{*}\|^{-1} \mu_{*})) \geq 0 \quad \text{if} \, \, x_{*} \neq y_{*}, \label{E: big equation 2} \\
			-\mathcal{H}(y_{*},u(y_{*}),0,0,0) \geq 0 \quad \text{if} \, \, x_{*} = y_{*}, \label{E: big equation 2 star} \\
			X_{*} (q^{u}_{**} - q^{v}_{**}) = Y_{*}(q^{u}_{**} - q^{v}_{**}) = 0, \label{E: big killing}, \\
			- C(\varphi) T_{*} \zeta^{-1} \left( \begin{array}{c c}
															\text{Id} & 0 \\
															0 & \text{Id}
														\end{array} \right) \leq \left( \begin{array}{c c}
		X_{*} & 0 \\
		0 & -Y_{*}
	\end{array} \right) \leq C(\varphi) T_{*} \zeta^{-1} \left( \begin{array}{c c}
																	\text{Id} & - \text{Id} \\
																	-\text{Id} & \text{Id}
																\end{array} \right), \label{E: crazy matrix business}
		\end{gather}

\label{R: big killing crazy} Notice that if, as in the previous proposition, there is a matrix $Y_{*} \in \mathcal{S}_{d}$ and vectors $q_{**}^{u}, q_{**}^{v} \in \mathbb{R}^{d}$ such that $Y_{*}q_{**}^{u} = Y_{*}q_{**}^{v}$, then, for any $\xi \in \mathbb{R}^{d}$,
	\begin{equation*}
		Q_{Y_{*}}(q^{v}_{**} + \xi) = Q_{Y_{*}}(q_{**}^{u} + \xi).
	\end{equation*}
In particular, in this scenario, \eqref{E: big equation 2} is equivalent to
	\begin{equation*}
		-\mathcal{H}(y_{*},u(y_{*}),\mu_{*},Y_{*},Q_{Y_{*}}(q^{u}_{**} - \zeta \|\mu_{*}\|^{-1} \mu_{*}) \leq 0.
	\end{equation*}
As will become clear in the proof of Theorem \ref{T: penalized problem comparison} below, this means the discontinuity of $G_{\varphi}^{*}$ and $G_{*}^{\varphi}$ has effectively been circumvented, and the rest of the variable-doubling argument can be conducted as in the case of equations with continuous coefficients.

\label{R: regularity assumption} Note that \eqref{E: regularity operator} is a generalization of the standard assumption guaranteeing comparison in the viscosity theory for second-order elliptic operators, see, for instance, \cite[Section 3]{user}.  Indeed, \eqref{E: regularity operator} becomes the assumption in that reference if $\varphi_{\zeta} = \alpha^{-1} \|\cdot\|$ for some $\alpha > 0$ (cf. Remark \ref{R: ball regularization}).


	In particular, as usual, if $\mathcal{H}$ has the following ``separable" form
		\begin{equation*}
			\mathcal{H}(x,s,p,X,a) = \mathcal{H}_{0}(s,p,X,a) - f(x),
		\end{equation*}
	where $\mathcal{H}_{0}$ is monotone increasing in the third and fourth arguments and $f$ is uniformly continuous, then \eqref{E: regularity operator} holds.

\label{R: diffusion assumption} The computation of \cite[Example 3.6]{user} applies just as well in this setting.  Thus, for instance, if $\sigma : \mathbb{R}^{d} \to [0,+\infty)$ is uniformly Lipschitz, that is, if there is a $K > 0$ such that, for any $x,y \in \mathbb{R}^{d}$,
		\begin{equation*}
			|\sigma(x) - \sigma(y)| \leq K \|x - y\|,
		\end{equation*}
	then the operator $\mathcal{H}_{\sigma}$ given by 
		\begin{equation*}
			\mathcal{H}_{\sigma}(x,r,p,X,a) = -u + \sigma(x)^{2} a
		\end{equation*}
	satisfies \eqref{E: regularity operator}.  Hence, setting $c(x) = \sigma(x)^{2}$, Theorem \ref{T: penalized problem comparison} applies to the problem \eqref{E: finsler dirichlet with zeroth order} presented in the introduction.

Argue by contradiction, that is, assume that
		\begin{equation} \label{E: running assumption ack}
			\max\left\{ u(x) - v(x) \, \mid \, x \in \overline{U} \right\} > 0 \geq \max \left\{ u(x) - v(x) \, \mid \, x \in \partial U \right\}.
		\end{equation}

	Let $\zeta = \zeta(\mathcal{H}) \in (0,1)$ be as in the hypotheses and let $\varphi_{\zeta}$ be the regularized norm of Theorem \ref{T: regularized_norm}.

	Let $\beta > 0$.  Assume that there is a $\beta_{*} \in (0,1)$ such that, for any $\beta \in (0,\beta_{*})$,		\begin{align}
			\sup &\left\{ u(x) - v(y) - \frac{\varphi_{\zeta}(x - y)^{4}}{4 \beta} \, \mid \, (x,y) \in U \times U \right \} \label{E: ack ack ack need to prove ack ack ack} \\
			&\qquad > \max \left\{ u(x) - v(y) - \frac{\varphi_{\zeta}(x - y)^{4}}{4 \beta} \, \mid \, (x,y) \in \partial (U \times U) \right\}. \nonumber
		\end{align}
	The existence of $\beta_{*}$ follows from \eqref{E: running assumption ack}, as will be verified at the end of this proof.


	Taking $\beta < \beta_{*}$ and applying Proposition \ref{P: doubling variables}, one obtains two triples 
		\begin{equation*}
			(x_{*},X_{*},q^{u}_{**}), (y_{*},Y_{*},q^{v}_{**}) \in U \times \mathcal{S}_{d} \times \{\varphi_{\zeta} = 1\}
		\end{equation*} 
	such that the conditions \eqref{E: big maximization}-\eqref{E: crazy matrix business} all hold.  As in the statement of the proposition, it is convenient to let $T_{*} = \beta^{-1} \varphi_{\zeta}(x_{*} - y_{*})^{2}$.  The crux of the proof lies in establishing the following inequality		
		\begin{equation} \label{E: what we are proving now finally at last}
			\lambda (u(x_{*}) - v(y_{*})) \leq \omega_{C}(\|x_{*} - y_{*}\| + T_{*} \|x_{*} -y_{*}\|^{2}),
		\end{equation}
	where $\lambda = \lambda(\mathcal{H})$ is as in the hypotheses and $\omega_{C}$ is as in \eqref{E: regularity operator} for some well-chosen $C$.

	If $x_{*} = y_{*}$, then this follows immediately from \eqref{E: big equation 1 star}, \eqref{E: big equation 2 star}, and \eqref{E: strict monotonicity operator}.  Indeed, here in the application of \eqref{E: strict monotonicity operator}, one needs to observe that, by \eqref{E: running assumption ack} and the choice of the point $(x_{*},y_{*})$,
		\begin{align}
			0 &< \sup \left\{ u(x) - v(x) \, \mid \, x \in \overline{U} \right\} \label{E: useful string of inequalities ack} \\
			&\leq \sup \left\{ u(x) - v(y) - \frac{\varphi_{\zeta}(x - y)^{4}}{4 \beta} \, \mid \, x,y \in \overline{U} \times \overline{U} \right\} \leq u(x_{*}) - v(y_{*}). \nonumber
		\end{align}
	Thus, if $x_{*} = y_{*}$, one invokes \eqref{E: strict monotonicity operator} and \eqref{E: regularity operator} (with an arbitrary $C$) to find
		\begin{align*}
			\lambda (u(x_{*}) - v(y_{*})) &\leq \mathcal{H}(x_{*},v(y_{*}),0,0,0) - \mathcal{H}(x_{*},u(x_{*}),0,0,0) \\
			&\leq \mathcal{H}(x_{*}, v(y_{*}),0,0,0) - \mathcal{H}(y_{*},v(y_{*}),0,0,0) \\
			&\leq \omega_{C}(\|x_{*} - y_{*}\| + T_{*} \|x_{*} - y_{*}\|^{2}).
		\end{align*}
	Hence, in what follows, assume $x_{*} \neq y_{*}$.

	As explained in Remark \ref{R: big killing crazy}, when $x_{*} \neq y_{*}$, \eqref{E: big equation 2} combines with \eqref{E: big killing} to yield the following inequality
		\begin{equation} \label{E: key thing we need ack}
			-\mathcal{H}(y_{*},v(y_{*}),\mu_{*},Y_{*},Q_{Y_{*}}(q^{u}_{**} - \zeta \|\mu_{*}\|^{-1} \mu_{*}) \geq 0,
		\end{equation}
	where $\mu_{*} = \beta^{-1} \varphi_{\zeta}(x_{*} - y_{*})^{3} D\varphi_{\zeta}(x_{*} - y_{*})$.  At this stage, the goal is to apply \eqref{E: strict monotonicity operator} and \eqref{E: regularity operator} to obtain \eqref{E: what we are proving now finally at last}.

Toward that end, note that, by \eqref{E: crazy matrix business}, $X_{*}$ and $Y_{*}$ satisfy the following inequality
	\begin{equation*}
		- C(\varphi) T_{*} \left( \begin{array}{c c}
							\text{Id} & 0\\
							0 & \text{Id}
						\end{array} \right) \leq \left( \begin{array}{c c}
													X_{*} & 0 \\
													0 & - Y_{*}
											\end{array} \right) \leq C(\varphi) T_{*} \left( \begin{array}{c c}
																	\text{Id} & - \text{Id} \\
																	- \text{Id} & \text{Id}
															\end{array} \right).
	\end{equation*}
Furthermore, observe that since $\{q_{**}^{u},q_{**}^{v}\} \subseteq \{\varphi_{\zeta} = 1\}$, there holds
	\begin{equation*}
		\left\| q_{**}^{u} - \zeta \|\mu_{*}\|^{-1} \mu_{*} \right\|, \left\| q_{**}^{v} - \zeta \|\mu_{*}\|^{-1} \mu_{*} \right\| \leq \max \left\{ \|q\| \, \mid \, \varphi_{\zeta}(q) = 1 \right\} + 1.
	\end{equation*}
Thus, if $C = C(\varphi) +  \max \{ \|q\| \, \mid \, \varphi_{\zeta}(q) = 1\} + 1$, then one can invoke \eqref{E: regularity operator} to find
	\begin{align*}
		&\mathcal{H}(x_{*},v(y_{*}), \mu_{*},X_{*},Q_{X_{*}}(q_{u}^{**} - \zeta \|\mu_{*}\|^{-1} \mu)) -\mathcal{H}(y_{*},v(y_{*}),\mu_{*},Y_{*},Q_{Y_{*}}(q^{u}_{**} - \zeta \|\mu_{*}\|^{-1} \mu_{*}) \\
		&\qquad \qquad \qquad \leq \omega_{C}(\|x_{*} - y_{*}\| + T_{*} \|x_{*} -y_{*}\|^{2}).
	\end{align*}



Adding this last expression to \eqref{E: big equation 1} and invoking \eqref{E: key thing we need ack} and \eqref{E: strict monotonicity operator}, one obtains
	\begin{align*}
		\lambda (u(x_{*}) - v(y_{*})) &\leq \mathcal{H}(x_{*}, v(y_{*}), \mu_{*}, X_{*}, Q_{X_{*}}(q_{**}^{u} - \zeta \|\mu_{*}\|^{-1} \mu_{*})) \\
			&\quad - \mathcal{H}(x_{*},u(x_{*}), \mu_{*},X_{*}, Q_{X_{*}}(q_{**}^{u} - \zeta \|\mu_{*}\|^{-1} \mu_{*})) \\
			&\leq \omega_{C}(\|x_{*} - y_{*}\| + T_{*} \|x_{*} - y_{*}\|^{2}) \\
			&\quad + \mathcal{H}(y_{*},v(y_{*}),\mu_{*},Y_{*},Q_{Y_{*}}(q_{**}^{u} - \zeta \|\mu_{*}\|^{-1} \mu_{*})) \\
			&\leq \omega_{C}(\|x_{*} - y_{*}\| + T_{*} \|x_{*} - y_{*}\|^{2}).
	\end{align*} 
Thus, \eqref{E: what we are proving now finally at last} holds, as claimed.  

Here is the conclusion of the proof: by \eqref{E: what we are proving now finally at last} and \eqref{E: useful string of inequalities ack}, one deduces that
	\begin{align*}
		\sup \left\{ u(x) - v(x) \, \mid \, x \in \overline{U} \right\} &\leq u(x_{*}) - v(y_{*}) \leq \frac{1}{\lambda} \omega_{C}(\|x_{*} - y_{*}\| + T_{*} \|x_{*} - y_{*}\|^{2}).
	\end{align*}
In view of the running assumption \eqref{E: running assumption ack}, this leads to a contradiction provided 
		\begin{align*}
			\lim_{\beta \to 0^{+}} \left( \|x_{*} - y_{*}\| + T_{*} \|x_{*} - y_{*}\|^{2} \right) = 0.
		\end{align*}
	Toward that end, by definition of $T_{*}$, it suffices to establish that
		\begin{align} \label{E: vanishing part of proof comparison}
			\lim_{\beta \to 0^{+}} \frac{\varphi_{\zeta}(x_{*} - y_{*})^{4}}{4 \beta} = 0.
		\end{align}
	Indeed, notice that, by definition of $T_{*}$, 
		\begin{equation*}
			T_{*} \|x_{*} - y_{*}\|^{2} \leq \max \left\{ \|q\|^{2} \, \mid \, \varphi_{\zeta}(q) = 1 \right\} \cdot \frac{\varphi_{\zeta}(x_{*} - y_{*})^{4}}{\beta}.
		\end{equation*}
	Thus, the proof is complete as soon as \eqref{E: ack ack ack need to prove ack ack ack} and \eqref{E: vanishing part of proof comparison} are established.  Both are fairly standard claims; nonetheless, the details are provided next for completeness.

	In order to avoid confusion in what follows, make the dependence on $\beta$ explicit by setting $(x_{*}^{\beta},y_{*}^{\beta}) = (x_{*},y_{*})$.  Since $\overline{U}$ is compact, there is no great loss of generality in assuming that the limits $x_{\infty} = \lim_{\beta \to 0^{+}} x_{*}^{\beta}$ and $y_{\infty} = \lim_{\beta \to 0^{+}} y_{*}^{\beta}$ exist; otherwise, pass to a subsequence.  In view of the computation \eqref{E: useful string of inequalities ack}, 
		\begin{align*}
			\frac{\varphi_{\zeta}(x_{*}^{\beta} - y_{*}^{\beta})^{4}}{4 \beta} &\leq u(x_{*}^{\beta}) - v(y_{*}^{\beta}) \\
			&\leq \max \left\{ u(x) \, \mid \, x \in \overline{U} \right\} - \inf \left\{ v(y) \, \mid \, y \in \overline{U} \right\} < +\infty.
		\end{align*}
	It follows that $x_{\infty} = y_{\infty}$. 

	Since $u$ is upper semicontinuous and $v$, lower semicontinuous, one finds
		\begin{align*}
			u(x_{\infty}) - v(x_{\infty}) &\geq \limsup_{\beta \to 0^{+}} u(x_{*}^{\beta}) - \liminf_{\beta \to 0^{+}} v(y_{*}^{\beta}) \\
				&\geq \limsup_{\beta \to 0^{+}} \left[ u(x_{*}^{\beta}) - v(y_{*}^{\beta}) - \frac{\varphi_{\zeta}(x_{*}^{\beta} - y_{*}^{\beta})^{4}}{4 \beta} \right].
		\end{align*}
	At the same time, 		
		\begin{equation*}
			u(x_{\infty}) - v(x_{\infty}) \leq \sup\{u(x) - v(x) \, \mid \, x \in U \} \leq \liminf_{\beta \to 0^{+}} \left[ u(x_{*}^{\beta}) - v(y_{*}^{\beta}) - \frac{\varphi_{\zeta}(x_{*}^{\beta} - y_{*}^{\beta})^{4}}{4 \beta} \right].
		\end{equation*}
	This proves $u(x_{\infty}) = \limsup_{\beta \to 0^{+}} u(x_{*}^{\beta})$ and $v(x_{\infty}) = \liminf_{\beta \to 0^{+}} v(y_{*}^{\beta})$.  Therefore, after revisiting the last inequality, one finds
		\begin{align*}
			u(x_{\infty}) - v(x_{\infty}) &\leq \limsup_{\beta \to 0^{+}} u(x_{*}^{\beta}) - \liminf_{\beta \to 0^{+}} v(x_{*}^{\beta}) - \limsup_{\beta \to 0^{+}} \frac{\varphi_{\zeta}(x_{*}^{\beta} - y_{*}^{\beta})^{4}}{4 \beta} \\
				&= u(x_{\infty}) - v(x_{\infty}) - \limsup_{\beta \to 0^{+}} \frac{\varphi_{\zeta}(x_{*}^{\beta}) - y_{*}^{\beta})^{4}}{4 \beta}.
		\end{align*} 
	This proves $(4 \beta)^{-1} \varphi_{\zeta}(x_{*}^{\beta} - y_{*}^{\beta})^{4} \to 0$ as $\epsilon \to 0$, as claimed.  Furthermore, the argument showed that 
		\begin{equation*}
			\lim_{\beta \to 0^{+}} \sup \left\{ u(x) - v(y) - \frac{\varphi_{\zeta}(x - y)^{4}}{4 \beta} \, \mid \, x,y \in \overline{U} \times \overline{U} \right\} = \sup \{u(x) - v(x) \, \mid \, x \in \overline{U}\}.
		\end{equation*}

	Finally, to establish \eqref{E: ack ack ack need to prove ack ack ack}, one repeats the previous arguments to show that
		\begin{align*}
			&\lim_{\beta \to 0^{+}} \sup \left\{ u(x) - v(y) - \frac{\varphi_{\zeta}(x - y)^{4}}{4 \beta} \, \mid \, x,y \in \partial (U \times U) \right\} \\
			&\qquad \qquad \qquad = \sup \left\{ u(x) - v(x) \, \mid \, x \in \partial U \right\}.
		\end{align*}
	Combining this with the previous limit, one invokes \eqref{E: running assumption ack} to deduce that \eqref{E: ack ack ack need to prove ack ack ack} holds.

\label{P: jensen ishii lemma} Fix $\alpha \in \mathbb{R}$, let $U \subseteq \mathbb{R}^{d}$ be a bounded open set, and suppose that $u \in USC(\overline{U})$ and $v \in LSC(\overline{U})$ satisfy
	\begin{align*}
		-\mathcal{H}(x,u,Du,D^{2}u,\mathcal{G}_{\varphi}^{*,\alpha}(Du,D^{2}u)) \leq 0 \quad \text{in} \, \, U, \\
		-\mathcal{H}(x,u,Du,D^{2}u,\mathcal{G}_{*,\alpha}^{\varphi}(Du,D^{2}u)) \geq 0 \quad \text{in} \, \, U.
	\end{align*}  
Let $\xi_{0} \in \mathbb{R}^{d}$ and suppose that $\psi : \mathbb{R}^{d} \to \mathbb{R} \cup \{+\infty\}$ is a convex function which is finite and smooth in a neighborhood of $\xi_{0}$.  If there are points $(x_{0},y_{0}) \in U$ such that $\xi_{0} = x_{0} - y_{0}$ and 
	\begin{equation*}
		\sup \left\{ u(x) - v(y) - \psi(x - y) \, \mid \, (x,y) \in U \times U\right\} = u(x_{0}) - v(y_{0}) - \psi(x_{0} - y_{0}),
	\end{equation*}
then there are matrices $X, Y \in \mathcal{S}_{d}$ such that 
	\begin{align*}
		- \mathcal{H}(x_{0},u(x_{0}),D\psi(\xi_{0}),X,\mathcal{G}_{\varphi}^{*,\alpha}(D\psi(\xi_{0}),X)) &\leq 0, \\
		-\mathcal{H}(y_{0},v(y_{0}),D\psi(\xi_{0}),Y,\mathcal{G}_{*,\alpha}^{\varphi}(D\psi(\xi_{0}),Y)) &\geq 0, 
	\end{align*}
and
	\begin{equation*}
		-3 \left( \begin{array}{c c}
			D^{2}\psi(\xi_{0}) & 0 \\
			0 & D^{2}\psi(\xi_{0}) 
		\end{array} \right) \leq \left( \begin{array}{c c}
								X & 0 \\
								0 & - Y
							\end{array} \right) \leq 3 \left( \begin{array}{c c}
													D^{2}\psi(\xi_{0}) & -D^{2}\psi(\xi_{0}) \\
													-D^{2}\psi(\xi_{0}) & D^{2}\psi(\xi_{0}) 
												\end{array} \right).
	\end{equation*}

\label{P: generate contact points double variable} Let $\varphi$ be a Finsler norm in $\mathbb{R}^{d}$ satisfying \eqref{E: zeta interior ball} and \eqref{E: nondegeneracy} for some constants $\zeta, \delta > 0$; let $U \subseteq \mathbb{R}^{d}$ be a bounded open set; and fix a $p \in \mathbb{R}^{d} \setminus \{0\}$.  Define $e = \|p\|^{-1} p$.  

	Fix a $\beta > 0$ and a $\nu \in (0,\zeta)$.  For $\mu \in \{\nu,\zeta\}$, let $\psi_{\mu}$ be the conical test function $\psi_{\mu} := \psi_{e,\partial \varphi^{*}(p),\mu}$ of Section \ref{S: conical test}, and let $(\psi_{\nu}^{\epsilon})_{0 < \epsilon < \nu}$ be an admissible perturbation of $\psi_{\nu}$.

	If $u \in \text{USC}(\overline{U})$ and $v \in \text{LSC}(\overline{U})$ are such that 
		\begin{align}
			-\mathcal{H}(x,u,Du,D^{2}u,\mathcal{G}_{\varphi}^{*,\alpha}(Du,D^{2}u)) &\leq 0 \quad \text{in} \, \, U, \label{E: doubled equation part one} \\
			-\mathcal{H}(x,u,Du,D^{2}u,\mathcal{G}_{*,\alpha}^{\varphi}(Du,D^{2}u)) &\geq 0 \quad \text{in} \, \, U, \label{E: doubled equation part two}
		\end{align}
	and
		\begin{align}
			M &:= \max \left\{ u(x) - v(y) - \frac{\psi_{\zeta}(x - y)^{4}}{4 \beta} \, \mid \, (x,y) \in \overline{U} \times \overline{U} \right\} \label{E: maximum point doubled equation} \\
			&\qquad > \max \left\{ u(x) - v(y) - \frac{\psi_{\zeta}(x-y)^{4}}{4 \beta} \, \mid \, (x,y) \in \partial (U \times U) \right\}, \nonumber \\
			\{(x,y) &\, \mid \, u(x) - v(y) = M + \frac{\psi_{\zeta}(x - y)^{4}}{4 \beta} \} \label{E: nondegeneracy assumption for doubled cone} \\
			&\qquad \subseteq \{(x,y) \in U \times U \, \, \mid \, x - y \in \mathcal{C}(\partial \varphi^{*}(p)), \, \, x \neq y\}, \nonumber
		\end{align}
	then, for any $\nu \in (0,\zeta)$, there are sequences $(\epsilon_{j})_{j \in \mathbb{N}} \subseteq (0,+\infty)$, $((x_{j},y_{j}))_{j \in \mathbb{N}} \subseteq U \times U$, and $((p_{j},X_{j},Y_{j}))_{j \in \mathbb{N}} \subseteq \mathbb{R}^{d} \times \mathcal{S}_{d} \times \mathcal{S}_{d}$ such that
		\begin{gather}
			u(x_{j}) - v(y_{j}) - \frac{\psi_{\nu}^{\epsilon_{j}}(x_{j} - y_{j})^{4}}{4 \beta} = \max \left\{ u(x) - v(y) - \frac{\psi_{\nu}^{\epsilon_{j}}(x - y)^{4}}{4 \beta} \, \mid \, (x,y) \in \overline{U} \times \overline{U} \right\}, \label{E: the double variable maximum thing} \\
			- \mathcal{H}(x_{j},u(x_{j}),\mu_{j}, X_{j}, \mathcal{G}_{\varphi}^{*,\alpha}(\mu_{j},X_{j})) \leq 0, \quad - \mathcal{H}(y_{j},v(y_{j}),\mu_{j},Y_{j}, \mathcal{G}_{*,\alpha}^{\varphi}(\mu_{j},Y_{j})) \geq 0, \label{E: doubled equation} \\
			\mu_{j} = \beta^{-1} \psi_{\nu}^{\epsilon_{j}}(x_{j} - y_{j})^{3} D\psi_{\nu}^{\epsilon_{j}}(x_{j} - y_{j}), \label{E: maximum first derivative thing double variable} \\
			- 3 \left( \begin{array}{r l}
					\bar{A}_{j}(x_{j} - y_{j}) & 0 \\
					0 & \bar{A}_{j}(x_{j} - y_{j})
				\end{array} \right) \leq \left( \begin{array}{r l}
										X_{j} & 0 \\
										0 & -Y_{j} 
									\end{array} \right) \leq 3 \left( \begin{array}{r l}
															\bar{A}_{j}(x_{j} - y_{j}) & -\bar{A}_{j}(x_{j} - y_{j}) \\
															-\bar{A}_{j}(x_{j} - y_{j}) & \bar{A}_{j}(x_{j} - y_{j})
														\end{array} \right), \label{E: key doubled matrix inequality for later}
		\end{gather}
	where $\bar{A}$ is the matrix function
		\begin{align}
			\bar{A}_{j}(\xi) = \left\{ \begin{array}{r l}
							\beta^{-1} \psi_{\nu}^{\epsilon_{j}}(\xi)^{3} D^{2}\psi_{\nu}^{\epsilon_{j}}(\xi) + 3 \beta^{-1} \psi_{\nu}^{\epsilon_{j}}(\xi)^{2} D\psi_{\nu}^{\epsilon_{j}}(\xi)^{\otimes 2}, & \text{if} \, \, \xi \neq 0, \\
							0, & \text{otherwise.}
						\end{array} \right. \label{E: matrix function stuff}
		\end{align}

The proof boils down to an application of Propositions \ref{P: key mountain} and \ref{P: generate contact points double variable}.  In order to apply Proposition \ref{P: generate contact points double variable} directly, though, it would be necessary to know that the maximum of $u(x) - v(y) - (4 \beta)^{-1} \varphi_{\zeta}(x - y)^{4}$ occurs away from the diagonal.  Of course, this may not be true in general.  Thus, the proof begins with the (ultimately trivial) case when the maximum is on the diagonal before proceeding to the more interesting situation.

\textit{Case: maximum on the diagonal.} 

Suppose that there is a point $x_{0} \in U$ such that
	\begin{equation*}
		u(x_{0}) - v(x_{0}) = \sup \left\{ u(x) - v(y) - \frac{\varphi_{\zeta}(x-y)^{4}}{4 \beta} \, \mid \, (x,y) \in U \times U \right\}.
	\end{equation*}
This implies that 
	\begin{align*}
		u(x_{0}) - v(x_{0}) &= \max \left\{ u(x) - v(x_{0}) - \frac{\varphi_{\zeta}(x - x_{0})^{4}}{4 \beta} \, \mid \, x \in U \right\}, \\
		u(x_{0}) - v(y) &= \max \left\{ u(x_{0}) - v(y) - \frac{\varphi_{\zeta}(x_{0} - y)^{4}}{4 \beta} \, \mid \, y \in U \right\}.
	\end{align*}
At the same time, since $\varphi_{\zeta}$ sastisifes \eqref{E: nondegeneracy condition zeta},
	\begin{align*}
		\frac{\varphi_{\zeta}(\xi)^{4}}{4 \beta} &\leq \frac{\|\xi\|^{4}}{4 \beta \delta} \quad \text{with equality if} \quad \xi = 0,
	\end{align*}
Therefore,
	\begin{align*}
		u(x_{0}) - v(x_{0}) &= \sup \left\{ u(x) - v(x_{0}) - \frac{\|x - x_{0}\|^{4}}{4 \beta \delta} \, \mid \, x \in U \right\}, \\
		u(x_{0}) - v(x_{0}) &= \sup \left\{ u(x_{0}) - v(y) - \frac{\|x_{0} - y\|^{4}}{4 \beta \delta} \, \mid \, y \in U \right\},
	\end{align*}
and, thus, since $\|\cdot\|^{4}$ is smooth and vanishing to second order at zero,
	\begin{align*}
		- \mathcal{H}(x_{0},u(x_{0}),0, 0, 0) \leq 0, \quad -\mathcal{H}(y_{0},u(y_{0}),0,0,0) \geq 0.
	\end{align*}
This completes the proof with $(x_{*},y_{*}) = (x_{0},y_{0})$, $(X_{*},Y_{*}) = (0,0)$, and $q^{u}_{**}, q^{v}_{**}$ any arbitrary points in $\{\varphi = 1\}$, their values being completely irrelevant in this case.

\textit{Case: all maxima off the diagonal.} 

To complete the proof, it suffices to proceed under the assumption that there is an $r > 0$ such that
	\begin{equation} \label{E: trivial assumption almost done}
		\left\{(x,y) \, \mid \, u(x) - v(y) = M + \frac{\varphi_{\zeta}(x - y)^{4}}{4 \beta} \right\} \subseteq \{(x,y) \in U \times U \, \mid \, \|x - y\| > r\},
	\end{equation}
where $M$ is the maximum
	\begin{equation*}
		M = \max\left\{ u(x) - v(y) - \frac{\varphi_{\zeta}(x - y)^{4}}{4 \beta} \, \mid \, (x,y) \in \overline{U} \times \overline{U} \right\}.
	\end{equation*}

Due to \eqref{E: nondegenerate boundary assumption} and \eqref{E: trivial assumption almost done}, there are points $(x_{0},y_{0}) \in U \times U$ such that 
	\begin{equation*}
		u(x_{0}) - v(y_{0}) = M + \frac{\varphi_{\zeta}(x_{0} - y_{0})^{4}}{4 \beta}, \quad \|x_{0} - y_{0}\| > r.
	\end{equation*}
Let $\xi_{0} = x_{0} - y_{0}$.  Since $\|\xi_{0}\| > r$, the vector $p = D\varphi_{\zeta}(\xi_{0})$ is well-defined, as is the direction $e = \|p\|^{-1} p$.  

For $\nu \in (0,\zeta]$, let $\psi_{\nu} = \psi_{e,\partial \varphi_{\zeta}^{*}(p),\nu}$ be the conical test function associated with the triple $(e,\partial \varphi_{\zeta}^{*}(p),\nu)$.  By Proposition \ref{P: touching above test function part}, the following statements all hold:
	\begin{gather}
		u(x_{0}) - v(y_{0}) = M + \frac{\psi_{\nu}(x_{0} - y_{0})^{4}}{4 \beta}, \nonumber \\
		u(x) - v(y) \leq M + \frac{\psi_{\nu}(x - y)^{4}}{4 \beta} \quad \text{for each} \quad (x,y) \in \overline{U} \times \overline{U}, \nonumber \\
		\left\{(x,y) \, \mid \, u(x) - v(y) = M + \frac{\psi_{\nu}(x - y)^{4}}{4 \beta} \right\} \subseteq \{(x,y) \in U \times U \, \mid \, x - y \in \mathcal{C}(\partial \varphi^{*}_{\nu}(p)), \, \, x \neq y \}. \label{E: contact condition ack ack ack}
	\end{gather}
In particular, the hypotheses of Proposition \ref{P: generate contact points double variable} are satisfied.

Fix a $\nu \in (0,\zeta)$; for instance, $\nu = 2^{-1} \zeta$, although the exact value is immaterial to the proof.  By Proposition \ref{P: generate contact points double variable}, there are sequences 
	\begin{equation*}
		(\epsilon_{j})_{j \in \mathbb{N}} \subseteq (0,+\infty), \quad ((x_{j},y_{j}))_{j \in \mathbb{N}} \subseteq U \times U, \quad ((\mu_{j},X_{j},Y_{j}))_{j \in \mathbb{N}} \subseteq \mathbb{R}^{d} \times \mathcal{S}_{d} \times \mathcal{S}_{d} 
	\end{equation*}
such that \eqref{E: the double variable maximum thing}-\eqref{E: key doubled matrix inequality for later} all hold with this value of $\nu$.  

In what follows, it will be useful to define $p_{j} = D\psi_{\nu}^{\epsilon_{j}}(x_{j} - y_{j})$ and $A_{j} = \bar{A}_{j}(x_{j} - y_{j})$, where $\bar{A}_{j}$ is the matrix function defined in \eqref{E: matrix function stuff}.  Notice that if $(H_{j})_{j \in \mathbb{N}}$ is the sequence $H_{j} = D^{2}\psi_{\nu}^{\epsilon_{j}}(x_{j} - y_{j})$, then
	\begin{equation*}
		A_{j} = \beta^{-1} \psi_{\nu}^{\epsilon_{j}}(x_{j} - y_{j})^{3} H_{j} + 3 \beta^{-1} \psi_{\nu}^{\epsilon_{j}}(x_{j} - y_{j})^{2} p_{j} \otimes p_{j}.	
	\end{equation*}

By compactness (up to passing to a subsequence), there are points $(x_{*},y_{*}) \in \overline{U} \times \overline{U}$ such that $(x_{j},y_{j}) \to (x_{*},y_{*})$.  Note that, by upper semicontinuity and Proposition \ref{P: touching above test function part},
	\begin{equation} \label{E: touching ack ack ack ack}
		u(x_{*}) - v(y_{*}) = M + \frac{\psi_{\nu}(x_{*} - y_{*})^{4}}{4 \beta} = M + \frac{\varphi_{\zeta}(x_{*} - y_{*})^{4}}{4 \beta}
	\end{equation}
and, thus, $\|x_{*} - y_{*}\| > r$ by assumption \eqref{E: trivial assumption almost done}.  Since $x_{*} \neq y_{*}$, \eqref{E: touching ack ack ack ack} implies $\psi_{\nu}(x_{*} - y_{*}) = \varphi_{\zeta}(x_{*} - y_{*}) < +\infty$ and, thus, $p_{j} \to D\psi_{\nu}(x_{*} - y_{*}) = D\varphi_{\zeta}(x_{*} - y_{*}) = p$ as $j \to +\infty$ by \eqref{E: contact condition ack ack ack} and Proposition \ref{P: touching above test function part}. 
Additionally, by Proposition \ref{P: key mountain}, 
	\begin{align} \label{E: useful bound again and again}
		\varphi_{\zeta}(x_{*} - y_{*}) \limsup_{j \to \infty} \|H_{j}\| = \limsup_{j \to \infty} \psi_{\nu}(x_{j} - y_{j}) \|H_{j}\| \leq  \tilde{\Gamma}(\varphi) \zeta^{-1}.
	\end{align}
In particular, up to passing to yet another subsequence, there is an $H_{*} \in \mathcal{S}_{d}$ such that $H_{j} \to H_{*}$ as $j \to +\infty$.  Note that this implies $A_{j} \to A_{*}$, where 
	\begin{equation} \label{E: kind of annoying need it later}
		A_{*} = \beta^{-1} \varphi_{\zeta}(x_{*} - y_{*})^{3} H_{*} + 3 \beta^{-1} \varphi_{\zeta}(x_{*} - y_{*})^{2} p \otimes p.
	\end{equation}
Thus, by \eqref{E: useful bound again and again}, Proposition \ref{P: very easy gradient bound}, and the assumption $\zeta < 1$, upon writing $T_{*} = \beta^{-1} \varphi_{\zeta}(x_{*} - y_{*})^{2}$, one finds
	\begin{align} \label{E: i need this one too}
		0 \leq A_{*} \leq \left( \tilde{\Gamma}(\varphi) \zeta^{-1} T_{*} + 3 T_{*} \delta(\varphi)^{-2} \right) \text{Id} \leq \left( \tilde{\Gamma}(\varphi) + 3 \delta(\varphi)^{-2} \right) \zeta^{-1} T_{*} \text{Id}.
	\end{align}

Next, fix the $y$ variable: observe that, for any $j \in \mathbb{N}$,
	\begin{align*}
		u(x_{j}) - v(y_{j}) - \frac{\psi_{\nu}^{\epsilon_{j}}(x_{j} - y_{j})^{4}}{4 \beta} = \sup \left\{ u(x) - v(y_{j}) - \frac{\psi_{\nu}^{\epsilon_{j}}(x - y_{j})^{4}}{4 \beta} \, \mid \, x \in \overline{U} \right\},
	\end{align*}
hence there is a sequence $(q^{u}_{j})_{j \in \mathbb{N}} \subseteq \{\varphi_{\zeta} = 1\}$ such that
	\begin{align*}
		- \mathcal{H}(x_{j},u(x_{j}),\mu_{j},A_{j},Q_{A_{j}}(q^{u}_{j} - \zeta \|\mu_{j}\|^{-1} \mu_{j})) \leq 0, \quad q_{j}^{u} \in \partial \varphi^{*}_{\zeta}(\mu_{j}) = \partial \varphi^{*}_{\zeta}(p_{j}).
	\end{align*}
Since $\{\varphi_{\zeta} = 1\}$ is compact, there is no loss of generality assuming there is a $q^{u}_{**} \in \{\varphi_{\zeta} = 1\}$ such that $q^{u}_{j} \to q^{u}_{**}$ as $j \to +\infty$.  By Proposition \ref{P: key mountain}, it follows that there is a face $F_{*}^{u} \subseteq \partial \varphi_{\zeta}^{*}(p)$ such that
	\begin{equation} \label{E: vanishing face part a}
		q_{**}^{u} \in F_{*}^{u} \quad \text{and} \quad H_{*} q = 0 \quad \text{for each} \quad q \in F_{*}^{u}.
	\end{equation}

Similarly, fix the $x$ variable: observe that, for any $j \in \mathbb{N}$,
	\begin{align*}
		u(x_{j}) - v(y_{j}) - \frac{\psi_{\nu}^{\epsilon_{j}}(x_{j} - y_{j})^{4}}{4 \beta} = \sup \left\{ u(x_{j}) - v(y) - \frac{\psi_{\nu}^{\epsilon_{j}}(x_{j} - y)^{4}}{4 \beta} \, \mid \, y \in \overline{U} \right\},
	\end{align*}
hence there is a sequence $(q^{v}_{j})_{j \in \mathbb{N}} \subseteq \{\varphi_{\zeta} = 1\}$ such that
	\begin{align*}
		- \mathcal{H}(y_{j},v(y_{j}),p_{j},-A_{j},Q_{-A_{j}}(q_{j}^{v} - \zeta \|\mu_{j}\|^{-1} \mu_{j})) \geq 0, \quad q_{j}^{v} \in \partial \varphi^{*}_{\zeta}(p_{j}).
	\end{align*}
Once again, after passing to a subsequence, there is a limit $q_{**}^{v} = \lim_{j \to \infty} q_{j}^{v}$.  Further, by Proposition \ref{P: key mountain} (applied to supersolutions; cf.\ Lemma \ref{L: reduction to subsolutions}), there is a face $F_{*}^{v} \subseteq \partial \varphi^{*}_{\zeta}(p)$ such that
	\begin{equation} \label{E: vanishing face part b}
		q_{**}^{v} \in F_{*}^{v} \quad \text{and} \quad H_{*} q = 0 \quad \text{for each} \quad q \in F_{*}^{v}.
	\end{equation}

Finally, notice that \eqref{E: key doubled matrix inequality for later} implies that $- 3 A_{j} \leq X_{j} \leq Y_{j} \leq 3 A_{j}$.  Thus, the sequence $((X_{j},Y_{j}))_{j \in \mathbb{N}}$ is pre-compact, and there is no loss of generality in assuming that there are matrices $X_{*}$ and $Y_{*}$ such that $(X_{j},Y_{j}) \to (X_{*}, Y_{*})$ as $j \to +\infty$.  By \eqref{E: key doubled matrix inequality for later} and \eqref{E: i need this one too}, the inequality \eqref{E: crazy matrix business} holds with $C(\varphi) = 3(\tilde{\Gamma}(\varphi) + 3 \delta(\varphi)^{-2})$.  To prove \eqref{E: big killing}, first, observe that, on the one hand, since $q_{**}^{u}, q_{**}^{v} \in \partial \varphi_{\zeta}^{*}(p)$, the variational formula \eqref{E: subdifferential basic identity dual} implies that
	\begin{equation*}
		(p \otimes p)(q_{**}^{u} - q_{**}^{v}) = \left[ \langle p, q_{**}^{u} \rangle - \langle p, q_{**}^{v} \rangle \right] p = [\varphi_{\zeta}^{*}(p) - \varphi_{\zeta}^{*}(p)] p = 0.
	\end{equation*} 
In view of \eqref{E: kind of annoying need it later}, \eqref{E: vanishing face part a}, and \eqref{E: vanishing face part b}, this proves $A_{*}(q_{**}^{u} - q_{**}^{v}) = 0$.  On the other hand, in the limit $j \to +\infty$, \eqref{E: key doubled matrix inequality for later} implies $-3A_{*} \leq X_{*} \leq Y_{*} \leq 3A_{*}$.  Accordingly, it is an exercise in linear algebra to convince oneself that also\footnote{Cf.\ the proof of \cite[Lemma 1]{m_souganidis}.}
	\begin{equation*}
		X_{*}(q_{**}^{u} - q_{**}^{v}) = Y_{*}(q_{**}^{u} - q_{**}^{v}) = 0.
	\end{equation*}

\label{L: barriers dirichlet} For any Finsler norm $\varphi$, any $\alpha \in (0,1)$, and any $R > 0$, there are constants $C_{+,\alpha}(R), C_{-,\alpha}(R) > 0$ such that the functions $u_{+,\alpha}, u_{-,\alpha} : \mathbb{R}^{d} \to [0, +\infty)$ given by 
		\begin{equation*}
			u_{+,\alpha}(x) = \varphi(x)^{\alpha}, \quad u_{-,\alpha}(x) = -\varphi(-x)^{\alpha},
		\end{equation*}
	satisfy the differential inequalities
		\begin{align*}
			- G_{*}^{\varphi}(Du_{+,\alpha},D^{2}u_{+,\alpha}) &\geq C_{+,\alpha}(R) \quad \text{in} \, \, B_{R}(0) \setminus \{0\}, \\
			- G^{*}_{\varphi}(Du_{-,\alpha},D^{2}u_{-,\alpha}) &\leq -C_{-,\alpha}(R) \quad \text{in} \, \, B_{R}(0) \setminus \{0\}.
		\end{align*}

In a manner similar to Lemma \ref{L: reduction to subsolutions} above, the arguments for $u_{+,\alpha}$ and $u_{-,\alpha}$ are symmetrical.  Therefore, only those for $u_{+,\alpha}$ will be presented here.

	In view of the fact that $-G_{*}^{\varphi}(D\varphi,D^{2}\varphi) \geq 0$ holds by Proposition \ref{P: strongly superharmonic}, the following inequalities also hold
		\begin{align*}
			- G_{*}^{\varphi}(Du_{+,\alpha},D^{2}u_{+,\alpha}) &\geq  - \alpha (\alpha - 1) \varphi(x)^{\alpha - 2} \varphi^{*}(D\varphi)^{2}.
		\end{align*}
	At the same time, since $\varphi^{*}(D\varphi) \geq 1$ in the viscosity sense, this implies
		\begin{align*}
			- G_{*}^{\varphi}(Du_{+,\alpha},D^{2}u_{+,\alpha}) &\geq \alpha (1 - \alpha) \varphi(x)^{\alpha - 2}.
		\end{align*}
	Finally, since $\alpha < 2$, 
		\begin{align*}
			C_{+,\alpha}(R) := \min \left\{ \alpha (1 - \alpha) \varphi(x)^{\alpha - 2} \, \mid \, x \in B_{R}(0) \setminus \{0\} \right\} > 0.
		\end{align*}

As advertised, the proof begins with the case when $g$ is more reuglar, then extends  to the general case by approximation and monotonicity.

	\textit{Step one: uniformly H\"{o}lder continuous boundary data.} 

	First, assume that there is an $\alpha \in (0,1)$ such that $g$ is uniformly H\"{o}lder continuous on $\partial U$ that is, there is a $K > 0$ such that 
		\begin{equation*}
			|g(x) - g(y)| \leq K \|x - y\|^{\alpha} \quad \text{for each} \quad x, y \in \partial U.
		\end{equation*}
	Notice that, by equivalence of norns, this implies there are constants $K_{+}$ and $K_{-}$ such that, for any $x,y \in \partial U$,
		\begin{equation*}
			|g(x) - g(y)| \leq \max\{K_{+} \varphi(x - y)^{\alpha}, K_{-} \varphi(y - x)^{\alpha}\}.
		\end{equation*}
	In particular, if $x_{0} \in \partial U$ is fixed, then, for any $x \in \partial U$, 
		\begin{equation*}
			g(x_{0}) - K_{-} \varphi(x_{0} - x)^{\alpha} \leq g(x) \leq g(x_{0}) + K_{+} \varphi(x - x_{0})^{\alpha} =: u^{-}_{x_{0}}(x).
		\end{equation*}


	Let $C > 0$ be a large constant to be determined.  Define functions $u^{+}_{x_{0}}$ and $u^{-}_{x_{0}}$ by
		\begin{align*}
			u^{\pm}_{x_{0}}(y) = g(x_{0}) \pm C K_{\pm} \varphi( \pm [x - x_{0}] )^{\alpha}.
		\end{align*}
	Due to Lemma \ref{L: barriers dirichlet}, a routine argument shows that, at least if $C > 1$ is large enough, 
		\begin{align*}
			\lambda u^{+}_{x_{0}} - G_{*}^{\varphi}(Du^{+}_{x_{0}},D^{2}u^{+}_{x_{0}}) &\geq f(x) \quad \text{in} \, \, U, \\
			\lambda u^{-}_{x_{0}} - G_{\varphi}^{*}(Du^{-}_{x_{0}},D^{2}u^{-}_{x_{0}}) &\leq f(x) \quad \text{in} \, \, U.
		\end{align*}		
	Note that $u^{+}_{x_{0}} \geq g \geq u^{-}_{x_{0}}$ also holds.  Fix such a $C$ henceforth.

	It only remains to apply Perron's Method.  Let $\mathcal{S}$ be the set of all subsolutions, that is,
		\begin{align*}
			\mathcal{S} = \left\{v \in USC(\overline{U}) \, \mid \, \lambda v - G_{\varphi}^{*}(Dv,D^{2}v) \leq f(x) \, \, \text{in} \, \, U, \, \, v \leq g \, \, \text{on} \, \, \partial U \right\}.
		\end{align*}
	We showed that $\mathcal{S}$ is nonempty.  Further, by the comparison principle (Theorem \ref{T: penalized problem comparison}), for any $v \in \mathcal{S}$ and any $x_{0} \in \partial U$,
		\begin{align*}
			v \leq u_{x_{0}}^{+} \quad \text{pointwise in} \, \, \overline{U}.
		\end{align*}
	This shows $\mathcal{S}$ is pointwise bounded.  In particular, let $u : \overline{U} \to \mathbb{R}$ be the function
		\begin{equation*}
			u(x) = \max \left\{ v(x) \, \mid \, v \in \mathcal{S} \right\}.
		\end{equation*}

A standard computation shows that the upper semicontinuous envelope of $u$ belongs to $\mathcal{S}$, from which it follows that $u \in USC(\overline{U})$ and $u \in \mathcal{S}$.  Similarly, a standard construction shows that $u$ is a supersolution in $U$, that is,
		\begin{equation*}
			\lambda u - c(x) G_{*}^{\varphi}(Du,D^{2}u) \geq f(x) \quad \text{in} \, \, U.
		\end{equation*}
	See \cite[Section 4]{user} for detailed proofs of both of these claims.

At the same time, for any $x_{0} \in \partial U$, $u_{x_{0}}^{-} \leq u \leq u_{x_{0}}^{+}$ holds pointwise in $\overline{U}$, and, therefore, $u = g$ on $\partial U$. 

	\textit{Step two: the general case.} 

	It remains to prove existence even when $g$ need not be uniformly H\"{o}lder continuous.  To that end, observe that there is a sequence of functions $(g_{n})_{n \in \mathbb{N}}$ with constants $(K_{n})_{n \in \mathbb{N}} \subseteq (0,+\infty)$ such that, for any $n$,
		\begin{equation*}
			g \leq g_{n + 1} \leq g_{n} \quad \text{pointwise in} \, \, \partial U,
		\end{equation*}
	and
		\begin{gather*}
			\lim_{n \to \infty} \|g_{n} - g\|_{C(\partial U)} = 0, \\
			|g_{n}(x) - g_{n}(y)| \leq K_{n} \|x - y\|^{\frac{1}{2}} \quad \text{for each} \quad x,y \in \partial U.
		\end{gather*}
	Further, it is possible to fix a $h \in C(\partial U)$ such that $h \leq g$ pointwise on $\partial U$ and $|h(x) - h(y)| \leq K_{h} \|x - y\|^{\frac{1}{2}}$ for any $x,y \in \partial U$.  

	For any $n$, let $u_{n}$ denote the solution of \eqref{E: Dirichlet problem redux ax} with $u_{n} = g_{n}$ on $\partial U$.  Similarly, let $u_{h}$ be the solution with $u_{h} = h$ on $\partial U$.  By the comparison principle (Theorem \ref{T: penalized problem comparison}), $u_{h} \leq u_{n + 1} \leq u_{n}$ for each $n \in \mathbb{N}$.  Thus, if $u : \overline{U} \to \mathbb{R}$ is the function given by $u(x) = \min\{u_{n}(x) \, \mid \, n \in \mathbb{N}\}$, then Dini's Theorem implies that $u \in C(\overline{U})$, and the choice of $(u_{n})_{n \in \mathbb{N}}$ implies that $u = g$ on $\partial U$.  Finally, by stability of viscosity solutions, $u$ is the viscosity solution of \eqref{E: Dirichlet problem redux ax}.

Let $\varphi$, $U$, and $c$ be as in Proposition \ref{P: perron}.  Given any $\alpha \in (0,1)$ and any $V \subset \subset U$, there is a $C(V,\alpha) > 0$ such that if $u$ is the solution of \eqref{E: Dirichlet problem redux ax}, then
		\begin{equation*}
			[u]_{\alpha,V}  \leq C(V,\alpha) \max \left\{ |g(x)| \, \mid \, x \in \partial U \right\},
		\end{equation*}
	where $[u]_{\alpha,V}$ is the H\"{o}lder seminorm
		\begin{equation*}
			[u]_{\alpha,V} = \inf \left\{ K > 0 \, \mid \, |u(x) - u(y)| \leq K \|x - y\|^{\alpha} \, \, \text{for each} \, \, x, y \in V \right\}.
		\end{equation*}

\label{L: comparison discrete} Let $\varphi$ be a Finsler norm in $\mathbb{R}^{d}$ and fix a bounded open set $U \subseteq \mathbb{R}^{d}$.  Given any $\epsilon, \mu > 0$, if $u, v : \overline{U} \to \mathbb{R}$ are bounded functions such that 
		\begin{equation*}
			\mu u + c(x) (u - \mathcal{M}^{\varphi}_{\epsilon}u) \leq \mu v + c(x) (v -  \mathcal{M}_{\epsilon}^{\varphi} v) \quad \text{in} \, \, U_{\epsilon},
		\end{equation*}
	then 
		\begin{equation*}
			\sup \left\{ u(x) - v(x) \, \mid \, x \in \overline{U} \right\} = \sup \left\{ u(x) - v(x) \, \mid \, x \in \overline{U} \setminus U_{\epsilon} \right\}.
		\end{equation*}

Let $B(\overline{U})$ denote the space of all bounded functions in $\overline{U}$ and let $T : B(\overline{U}) \to B(\overline{U})$ denote the map
			\begin{equation*}
				Tu(x) = \left\{ \begin{array}{r l}
					 \frac{c(x)}{\mu + c(x)} \mathcal{M}_{\epsilon}^{\varphi}u(x), & \text{if} \, \, x \in U_{\epsilon}, \\
					 0, & \text{otherwise.}
					\end{array} \right.
			\end{equation*}
		Notice that $T$ is monotone nondecreasing in the sense that if $u_{1} \leq u_{2}$ pointwise in $\overline{U}$, then $Tu_{1} \leq Tu_{2}$ pointwise in $\overline{U}$.  Furthermore, since $\mu > 0$ and $c$ is bounded above in $\overline{U}$, $T$ is a strict contraction with respect to the supremum norm.  It follows that $u - Tu \leq v - Tv$ holds pointwise in $\overline{U}$ if and only if $u \leq v$ pointwise in $\overline{U}$.

\label{L: cone comparison discrete} Let $\varphi$ be a Finsler norm in $\mathbb{R}^{d}$ and fix a bounded open set $U \subseteq \mathbb{R}^{d}$.  If $v \notin U$, then, for any $\epsilon > 0$, the function $u(x) = \varphi(x - v)$ satisfies
		\begin{equation*}
			u - \mathcal{M}_{\epsilon}^{\varphi} u = 0 \quad \text{in} \, \, U_{\epsilon}.
		\end{equation*}

This is one place where the need for asymmetry in the definitinon of $\mathcal{M}^{\varphi}_{\epsilon}$ becomes apparent.  Up to translation, one can assume $v = 0$.  Observe then that, for any $x \in U_{\epsilon}$,
			\begin{align*}
				\max \left\{ \varphi(y) \, \mid \, \varphi(y - x) \leq \epsilon \right\} &= \varphi(x) + \epsilon, \\
				\min \left\{ \varphi(y) \, \mid \, \varphi(x - y) \leq \epsilon \right\} &= \varphi(x) - \epsilon.
			\end{align*}
		This proves $\mathcal{M}_{\epsilon}^{\varphi} u(x) = u(x)$.

As in the proof of Lemma \ref{L: comparison discrete}, let $B(\overline{U})$ denote the space of all bounded functions in $\overline{U}$.  Let $\mathcal{S}$ denote the space of all subsolutions, meaning
	\begin{equation*}
		\mathcal{S} = \left\{u \in B(\overline{U}) \, \mid \, \mu u + \epsilon^{-2} c(x) (u - \mathcal{M}_{\epsilon}^{\varphi} u) \leq F(x) \, \, \text{in} \, \, U_{\epsilon}, \, \, u \leq G(x) \, \, \text{in} \, \, \overline{U} \setminus U_{\epsilon} \right\}.
	\end{equation*}
Note that the constant function $u(x) = \min\{\mu^{-1} \inf F, \inf G\}$ is in $\mathcal{S}$, hence $\mathcal{S}$ is nonempty.  Further, the function $v(x) = \max\{\mu^{-1} \sup F, \sup G\}$ is a supersolution, which, in view of Lemma \ref{L: comparison discrete}, implies that any element of $\mathcal{S}$ lies below it.

Defining $u^{\epsilon}(x) = \sup_{u \in \mathcal{S}} u(x)$, one readily deduces that $u^{\epsilon} \in \mathcal{S}_{\epsilon}$.  Furthermore, by maximality, $u^{\epsilon}$ is also a supersolution.  (If $u^{\epsilon}$ fails to be a supersolution at some point $x \in \overline{U}$, one directly shows that the function $u^{\epsilon} + \zeta 1_{\{x\}}$ is a subsolution provided $\zeta > 0$ is small enough, which would contradict the maximality of $u^{\epsilon}$.)

\label{L: consistency} Let $\varphi$ be a Finsler norm in $\mathbb{R}^{d}$.  Given any $C^{2}$ function $f$ defined in some open set $V \subseteq \mathbb{R}^{d}$, any $x_{0} \in V$, and any family $(x_{\epsilon})_{\epsilon > 0} \subseteq V$ such that $x_{\epsilon} \to x_{0}$ as $\epsilon \to 0^{+}$, 
		\begin{gather*}
			- G_{\varphi}^{*}(Df(x_{0}), D^{2} f(x_{0})) \leq \liminf_{\epsilon \to 0^{+}} \epsilon^{-2} \left[ f(x_{\epsilon}) - \mathcal{M}_{\epsilon}^{\varphi} f(x_{\epsilon}) \right], \\
			\limsup_{\epsilon \to 0^{+}} \epsilon^{-2} \left[ f(x_{\epsilon}) - \mathcal{M}_{\epsilon}^{\varphi} f(x_{\epsilon}) \right] \leq - G_{*}^{\varphi}(Df(x_{0}),D^{2}f(x_{0})).
		\end{gather*}

Let $u_{*}$ and $u^{*}$ be the upper and lower half-relaxed limits of $(u^{\epsilon})_{\epsilon > 0}$ as defined in \cite[Section 6]{barles} or \cite[Proof of Theorem 3.1]{chatterjee_souganidis}.  Since the barrier arguments above are $\epsilon$-independent and $G$ is an extension of $g$, it follows that $u_{*} = u^{*} = G = g$ on $\partial U$.  Further, using Lemma \ref{L: consistency}, one readily deduces that 
		\begin{equation*}
			\lambda u^{*} - G_{\varphi}^{*}(Du,D^{2}u) \leq f(x) \quad \text{in} \, \, U, \quad \lambda u_{*} - G_{*}^{\varphi}(Du,D^{2}u) \geq f(x) \quad \text{in} \, \, U.
		\end{equation*}
	Therefore, by Theorem \ref{T: penalized problem comparison}, $u^{*} \leq u_{*}$ in $\overline{U}$.  Yet the definitions imply $u^{*} \geq u_{*}$.  Thus, equality holds $u^{*} \equiv u_{*}$, and $u^{\epsilon} \to u$ uniformly in $\overline{U}$.

\label{R: no simple tug of war} It is also true that the solution $u^{\epsilon}$ of the simpler problem
	\begin{equation*}
		u^{\epsilon} - \mathcal{M}^{\varphi}_{\epsilon} u^{\epsilon} = 0 \quad \text{in} \, \, U_{\epsilon}, \quad u^{\epsilon} = G \quad \text{in} \, \, \overline{U} \setminus U_{\epsilon},
	\end{equation*}
converges to the $\varphi$-infinity harmonic function in $U$ with boundary value $G$.  However, this follows already from the cone comparison results of \cite{armstrong_smart_easy_proof} and \cite{armstrong_crandall_julin_smart}, the reason being that one can use Lemmas \ref{L: comparison discrete} and \ref{L: cone comparison discrete} to prove that the upper (resp.\ lower) half-relaxed limit of $(u^{\epsilon})_{\epsilon > 0}$ as $\epsilon \to 0^{+}$ is in $CCA_{\varphi}(U)$ (resp.\ $CCB_{\varphi}(U)$) and then invoke the comparison theorems in those papers to conclude that the upper and lower half-relaxed limits coincide.\footnote{The limiting behavior is less straightforward when there is a right-hand side, see \cite{armstrong_smart_transactions}.}

The focus here is on \eqref{E: tug of war} since it seems to be out of reach of previous work.  Specifically, unlike the Finsler infinity Laplace equation, the solutions of which are characterized by comparison with cones, the PDE \eqref{E: Dirichlet problem redux ax} considered here does not seem to possess a comparison-with-cones-type characterization.

The problem \eqref{E: finite difference} is just one of many tug-of-war games whose value functions can be shown to converge using the comparison results of this paper.  For another simple example, consider tug-of-war with noise,\footnote{The game is the same, except for a third ``drunk" player who chooses the next position $x_{n + 1}$ uniformly at random from the ball $B_{1}(x_{n})$; see \cite{lewicka,parviainen}.}  in which the value function is the solution of the following equation
	\begin{equation*}
		u^{\epsilon} + \epsilon^{-2} (u^{\epsilon} - p \mathcal{M}_{\epsilon}^{\varphi}u^{\epsilon} - (1 - p) \mathcal{S}_{\epsilon} u^{\epsilon}) = f(x).
	\end{equation*}
Above $p \in [0,1]$ and $\mathcal{S}_{\epsilon}$ is the following averaging operator:
	\begin{equation*}
		(\mathcal{S}_{\epsilon} u)(x) = \fint_{B_{\epsilon}(x)} u(y) \, dy.
	\end{equation*}
Since $\text{Id} - \mathcal{S}_{\epsilon}$ approximates $-\Delta$ as $\epsilon \to 0^{+}$, limits of the above equation are determined by the following differential inequalities:
	\begin{equation*}
		\lambda u - p \Delta u - (1 - p) G_{\varphi}^{*}(Du,D^{2}u) \leq f(x) \quad \text{and} \quad \lambda u - p \Delta u - (1 - p) G_{*}^{\varphi}(Du,D^{2}u) \geq f(x).  
	\end{equation*}

Let $\text{sppt}(\mu)$ denote the support of $\mu$, that is, $v \in \text{sppt}(\mu)$ if and only if
		\begin{equation*}
			\mu(B_{\epsilon}(v)) > 0 \quad \text{for each} \quad \epsilon > 0.
		\end{equation*}
	Recall that $\mu(\mathcal{N} \setminus \text{sppt}(\mu)) = 0$.  Let $\mathcal{N}_{0}$ denote the convex cone generated by $\text{sppt}(\mu)$, that is,
		\begin{equation*}
			\mathcal{N}_{0} = \left\{ \sum_{i = 1}^{N} \alpha_{i} v_{i} \, \mid \, N \in \mathbb{N}, \, \,  v_{1},\dots,v_{N} \in \text{sppt}(\mu), \, \, \alpha_{1},\dots,\alpha_{N} \geq 0\right\}.
		\end{equation*}
	The closure $\overline{\mathcal{N}_{0}}$ is also a convex cone, and $\overline{\mathcal{N}_{0}} \subseteq \mathcal{N}$ since $\mu$ is a measure on $\mathcal{N}$.  To prove that $\mu(\mathcal{N} \setminus \mathcal{N}') = 0$, it suffices to show that $\overline{\mathcal{N}_{0}} \subseteq \mathcal{N}'$.  Toward that end, since $\mathcal{N}'$ is a face of $\mathcal{N}$, it enough to show that the mean $m_{\mu} := \int_{\mathcal{N}} v \, \mu(dv)$ is an element of the relative interior of $\overline{\mathcal{N}_{0}}$.

	 It is clear that $m_{\mu} \in \overline{\mathcal{N}_{0}}$ since $\mu$ is a positive measure (e.g., by simple approximation).  Let us argue by contradiction: suppose that $m_{\mu} \in \text{bdry}(\overline{\mathcal{N}_{0}})$.  It follows that there is a vector $w \in \mathbb{R}^{m}$ such that 
	 	\begin{align*}
			\langle w, m_{\mu} \rangle &= \max \left\{ \langle w, v \rangle \, \mid \, v \in \overline{\mathcal{N}_{0}} \right\}.
		\end{align*}
Note that if $v \in \text{rint}(\overline{\mathcal{N}_{0}})$, then $\langle w, v \rangle < \langle w, m_{\mu} \rangle$ necessarily holds.  At the same time, since $\overline{\mathcal{N}_{0}}$ is a cone, the maximum can only be zero: $\langle w, m_{\mu} \rangle = 0$.

	Fix a $v_{0} \in \text{rint}(\overline{\mathcal{N}_{0}})$.  Since $\langle w, v_{0} \rangle < 0$, the definition of $\mathcal{N}_{0}$ implies there is a $\tilde{v} \in \text{sppt}(\mu)$ such that $\langle w, \tilde{v} \rangle < 0$.  In particular, there is an $\epsilon > 0$ such that
		\begin{equation*}
			\langle w, v \rangle < 0 \quad \text{for each} \quad v \in B_{\epsilon}(\tilde{v}).
		\end{equation*}
	Thus, $\mu(\{\langle w, \cdot \rangle < 0\}) \geq \mu(B_{\epsilon}(\tilde{v})) > 0$.
	On the other hand, since $\langle w, v \rangle \leq 0$ for all $v \in \overline{\mathcal{N}_{0}}$, this leads to the observation that
		\begin{align*}
			0 = \langle w, m_{\mu} \rangle = \int_{\text{sppt}(\mu)} \langle w, v \rangle \, \mu(dv) = \int_{\{\langle w, v \rangle < 0\}} \langle w, v \rangle \, \mu(dv) < 0,
		\end{align*} 
	a patent contradiction.

\label{L: key hessian control} Let $\varphi$ satisfying Assumption \ref{A: c11 assumption}.  Fix a $\nu \in (0,\zeta]$, $p \in \mathbb{R}^{d} \setminus \{0\}$, and let $e = \|p\|^{-1} p$.  Let $\psi_{\nu} = \psi_{e,\partial \varphi^{*}(p),\nu}$ be the associated conical test function, and let $(\psi_{\nu}^{\epsilon})_{0 < \nu < \epsilon}$ be an admissible perturbation.  

If there are sequences $(\epsilon_{j})_{j \in \mathbb{N}} \subseteq (0,\nu)$ and $(q_{j})_{j \in \mathbb{N}} \subseteq \mathbb{R}^{d}$ and a point $q_{*} \in \partial \varphi^{*}(p)$ such that $\psi_{\nu}^{\epsilon_{j}}(q_{j}) = 1$ for each $j \in \mathbb{N}$ and 
