In particular, since $q_{j} \to q_{*}$ as $j \to +\infty$ and $\psi_{\nu}^{\epsilon_{j}}(q_{j}) = 1$ for all $j$, this implies
	\begin{equation*}
		\limsup_{j \to \infty} \|Y_{j}\| = \limsup_{j \to \infty} \|D^{2}\psi_{\nu}^{\epsilon_{j}}(q_{j})\| \leq \Gamma(\delta_{*}) (1 - \rho)^{-2} \nu^{-1}.
	\end{equation*}
Finally, since $\Gamma$ is a continuous function, the desired estimate \eqref{E: hessian bounds ack ack} follows upon sending $\rho \to 0$ and $\delta_{*} \to \delta$.

Only the details for the bound involving $G_{\varphi}^{*}$ will be presented since the bound for $G_{*}^{\varphi}$ follows via a transformation as in Lemma \ref{L: reduction to subsolutions}.  

Recall that $f$ is a smooth function defined in some neighborhood of a point $x_{0} \in \mathbb{R}^{d}$ and $(x_{\epsilon})_{\epsilon > 0}$ are points such that $x_{\epsilon} \to x_{0}$ as $\epsilon \to 0^{+}$, the goal being to establish that 
	\begin{equation*}
		-G_{\varphi}^{*}(Df(x_{0}),D^{2}f(x_{0})) \leq \liminf_{\epsilon \to 0^{+}} \epsilon^{-2} \left[ f(x_{\epsilon}) - (\mathcal{M}^{\varphi}_{\epsilon}f)(x_{\epsilon}) \right].
	\end{equation*}

Given $\epsilon > 0$, define $y^{+}_{\epsilon}$ and $y_{\epsilon}^{-}$ such that $\varphi(y^{+}_{\epsilon} - x) \leq \epsilon$, $\varphi(x_{\epsilon} - y^{-}_{\epsilon}) \leq \epsilon$, and
	\begin{align*}
		f(y^{+}_{\epsilon}) = \max \left\{ f(y) \, \mid \, \varphi(y - x_{\epsilon}) \leq \epsilon \right\}, \quad f(y^{-}_{\epsilon}) = \min \left\{ f(y) \, \mid \, \varphi(x_{\epsilon} - y) \leq \epsilon \right\}.
