Fix $q' \in [G_{p}]^{(\mu)}$ and let $k = \text{dim}(G_{p})$.  After an affine change of coordinates, there is no loss of generality assuming that $q' = 0$ and $G_{p} \subseteq \mathbb{R}^{k} \times \{0\} \subseteq \mathbb{R}^{d-1}$. 

In what follows, for a point $x' \in \mathbb{R}^{d-1}$, write $x' = (\check{x}', \underline{x}')$ with $\check{x}' \in \mathbb{R}^{k} \times \{0\}$ and $\underline{x}' \in \{0\} \times \mathbb{R}^{d-1 - k}$.  

Since $G_{p}$ has dimension $k$, the inequality $\text{dist}(0, \text{bdry}(G)) \geq \mu$ is equivalent to the requirement that the closed $k$-dimensional ball $\overline{B}_{\mu}(0) \cap (\mathbb{R}^{k} \times \{0\})$ is contained in $G_{p}$. Thus, by comparing to $\text{dist}(\cdot,\mathbb{R}^{k} \times \{0\})$, one deduces that
	\begin{equation*}
		\text{dist}(x', G_{p}) = \text{dist}(x',\mathbb{R}^{k} \times \{0\}) = \|\underline{x}'\| \quad \text{for each} \quad x' \in B_{\mu}(0).
	\end{equation*}
After differentiating, this becomes, for $k < d - 1$,
	\begin{equation*}
		D\text{dist}(x',G_{p}) = D\text{dist}(x',\mathbb{R}^{k} \times \{0\}) = \frac{\underline{x}'}{\|\underline{x}'\|}\quad \text{for each} \quad x' \in B_{\mu}(0) \setminus (\mathbb{R}^{k} \times \{0\})
	\end{equation*}
and, for $k = d - 1$,
	\begin{equation*}
		D\text{dist}(x',G_{p}) = 0 \quad \text{for each} \quad x' \in B_{\mu}(0).
	\end{equation*}
Applying these identities in the formulas \eqref{E: graphical special case} and \eqref{E: mollification}, changing variables via the map $T(\check{x}',\underline{x}') = (\check{x}',-\underline{x}')$, and recalling that $\epsilon < \mu$ and \eqref{E: symmetry mollifier} holds, one finds
	\begin{align*}
		Dg_{\nu}^{\epsilon}(0) &= - \epsilon^{-(d-1)} \int_{B_{\epsilon}(0)} \frac{\text{dist}(x',G)}{\sqrt{\nu^{2} - \text{dist}(x',G)^{2}}} D\text{dist}(x',G) \rho(\epsilon^{-1}x') \, dx' \\
					&= - \epsilon^{-(d-1)} \int_{B_{\epsilon}(0)} \frac{\text{dist}(T(x'),\mathbb{R}^{k} \times \{0\})}{\sqrt{\nu^{2} - \text{dist}(T(x'),\mathbb{R}^{k} \times \{0\})^{2}}} D \text{dist}(T(x'),\mathbb{R}^{k} \times \{0\}) \rho(\epsilon^{-1}x') \, dx' \\
					&= \epsilon^{-(d-1)} \int_{B_{\epsilon}(0)} \frac{\text{dist}(x',\mathbb{R}^{k} \times \{0\})}{\sqrt{\nu^{2} - \text{dist}(x',\mathbb{R}^{k} \times \{0\})^{2}}} Dd(x', \mathbb{R}^{k} \times \{0\}) \rho(\epsilon^{-1}x') \, dx' \\
					&= - Dg_{\nu}^{\epsilon}(0).
	\end{align*}
This proves $Dg_{\nu}^{\epsilon}(0) = 0$.

