To begin the proof, fix a sequence $(\epsilon_{j})_{j \in \mathbb{N}} \subseteq (0,+\infty)$ such that
		\begin{equation*}
			\lim_{j \to \infty} \epsilon_{j}^{-1} \text{dist}(q_{\epsilon_{j}}',G_{p}) = \limsup_{\epsilon \to 0^{+}} \epsilon^{-1} \text{dist}(q_{\epsilon}',G_{p}), \quad \lim_{j \to \infty} \epsilon_{j} = 0.
		\end{equation*}

	Since $\overline{V}$ is compact, there is no loss of generality in assuming that the limit $x_{*} = \lim_{j \to \infty} x_{\epsilon_{j}}$ exists.  In particular, since $u$ is upper semicontinuous, a classical argument shows that
		\begin{equation*}
			u(x_{*}) - \psi_{\nu}(x_{*}) = \max \left\{ u(y) - \psi_{\nu}(y) \, \mid \, y \in \overline{V} \right\}.
		\end{equation*}
	Since $\psi_{\nu} \geq \psi_{\zeta}$ and $\psi_{\nu}(x_{0}) = \psi_{\zeta}(x_{0})$ by Proposition \ref{P: touching above test function part}, 
		\begin{equation*}
			u(x_{*}) = M + \psi_{\zeta}(x_{*}) = M + \psi_{\nu}(x_{*}).
		\end{equation*}  
	Thus, by \eqref{E: stay in the cone appendix}, $x_{*} \in V \cap \mathcal{C}(\partial \varphi^{*}(p))$ and $0 < \psi_{\nu}(x_{*}) < +\infty$.  Further, since $\psi_{\nu}^{\epsilon} \to \psi_{\nu}$ locally uniformly in a neighborhood of $\mathcal{C}(\partial \varphi^{*}(p))$, the limit $q_{*} = \lim_{j \to \infty} q_{\epsilon_{j}}$ exists. Since $x_{*} \in \mathcal{C}(\partial \varphi^{*}(p))$, there holds $q_{*} \in \partial \varphi^{*}(p)$. 

	The considerations of the previous paragraph show that $q_{\epsilon_{j}}' \to q_{*}'$ as $j \to +\infty$ and $q'_{*} \in G_{p}$.  In particular, $\text{dist}(q_{\epsilon_{j}}',G_{p}) \to 0$ as $j \to +\infty$, and, up to passing to another subsequence, there is no loss of generality in assuming that
		\begin{equation*}
			\sup \left\{ \text{dist}(q_{\epsilon_{j}}',G_{p}) \, \mid \, j \in \mathbb{N} \right\} \leq \delta,
		\end{equation*}
	where $\delta = \delta(\nu,\zeta) > 0$ is the constant in Proposition \ref{P: scarier bound}.

Similarly, if $\tilde{q}_{\epsilon_{j}} = \psi_{\zeta}(x_{\epsilon_{j}})^{-1} x_{\epsilon_{j}}$, then Proposition \ref{P: touching above test function part} implies that
	\begin{equation*}
		\lim_{j \to \infty} \tilde{q}_{\epsilon_{j}} = \lim_{j \to \infty} \frac{x_{\epsilon_{j}}}{\psi_{\zeta}(x_{\epsilon_{j}})} = \frac{x_{*}}{\psi_{\zeta}(x_{*})} = \frac{x_{*}}{\psi_{\nu}(x_{*})} = q_{*} \in \partial \varphi^{*}(p),
	\end{equation*}
In particular, $\text{dist}(\tilde{q}_{\epsilon_{j}}',G_{p}) \to 0$ as $j \to +\infty$, and, thus, there is no loss of generality in assuming once more that
	\begin{equation*}
		\sup \left\{ \text{dist}(\tilde{q}_{\epsilon_{j}}',G_{p}) \, \mid \, j \in \mathbb{N} \right\} \leq \delta.
	\end{equation*}
In particular, $x_{\epsilon_{j}}$ satisfies the assumptions of Proposition \ref{P: scarier bound} for every $j \in \mathbb{N}$. 

	On the one hand, $x_{\epsilon_{j}}$ is a point where $M + \psi_{\nu}^{\epsilon_{j}} - u$ is minimized in $\overline{V}$, that is,
		\begin{equation*}
			M + \psi_{\nu}^{\epsilon_{j}}(x_{\epsilon_{j}}) - u(x_{\epsilon_{j}}) = \min \left\{ M + \psi_{\nu}^{\epsilon_{j}}(x) - u(x) \, \mid \, x \in \overline{V} \right\}.
		\end{equation*}
	Using Lemma \ref{L: basic bound} and \eqref{E: hopefully the last time touching above}, this implies
		\begin{equation*}
			M + \psi_{\nu}^{\epsilon_{j}}(x_{\epsilon_{j}}) - u(x_{\epsilon_{j}}) \leq M + \psi_{\nu}^{\epsilon_{j}}(x_{0}) - u(x_{0}) \leq c(\nu,x_{0}) \epsilon^{2}_{j} \psi_{\nu}(x_{0}).
		\end{equation*}
	On the other hand, by Proposition \ref{P: scarier bound} and \eqref{E: hopefully the last time touching above},
		\begin{align*}
			\psi_{\nu}^{\epsilon_{j}}(x_{\epsilon_{j}}) &\geq \psi_{\zeta}(x_{\epsilon_{j}}) \left[1 + A(\nu,\zeta) \text{dist}(q_{\epsilon_{j}}',G)^{2}\right] \\
				&\geq u(x_{\epsilon_{j}}) - M + A(\nu,\zeta) \psi_{\zeta}(x_{\epsilon_{j}}) \text{dist}(q_{\epsilon_{j}}',G)^{2}.
		\end{align*}
	In particular, combining the two estimates leads to the bound
		\begin{equation*}
			 A(\nu,\zeta) \psi_{\zeta}(x_{\epsilon_{j}}) \text{dist}(q_{\epsilon_{j}}',G)^{2} \leq c(\nu,x_{0}) \epsilon_{j}^{2} \psi_{\nu}(x_{0})
		\end{equation*}
	Since $x_{\epsilon_{j}} \to x_{*}$ and $x_{0},x_{*} \in \mathcal{C}(\partial \varphi^{*}(p)) \setminus \{0\}$, Proposition \ref{P: touching above test function part} implies $\psi_{\nu}(x_{0}) = \varphi(x_{0})$ and $\psi_{\zeta}(x_{*}) = \varphi(x_{*}) > 0$, hence this last inequality leads to
		\begin{equation*}
			\limsup_{\epsilon \to 0^{+}} \epsilon^{-1} \text{dist}(q'_{\epsilon},G_{p}) = \lim_{j \to \infty} \epsilon_{j}^{-1} \text{dist}(q_{\epsilon_{j}}',G_{p}) \leq  \sqrt{ \frac{c(\nu,x_{0}) \varphi(x_{0})}{A(\nu,\zeta) \varphi(x_{*})} } < +\infty.
		\end{equation*}

Fix $x_{*} \in \mathcal{C}(\partial \varphi^{*}(p)) \setminus \{0\}$.  Define $q_{*} = \psi_{\nu}(x_{*})^{-1} x_{*}$.  Since $q_{*} \in \mathcal{C}(\partial \varphi^{*}(p)) \cap \{\psi_{\nu} = 1\}$, the inclusion $q_{*} \in \partial \varphi^{*}(p)$ holds and, thus,
	\begin{equation*}
		q_{*} = q_{*}' + g_{\nu}(q_{*}') e = q_{*}' + \varphi^{*}(e) e.
	\end{equation*}
In the proof, there are two cases to consider: (i) $q_{*}' \in \text{int}(G_{p})$ and (ii) $q_{*}' \in \partial G_{p}$.  (Here $\text{int}(G_{p})$ and $\partial G_{p}$ are the interior and boundary of $G_{p}$ relative to the topology of $\mathbb{R}^{d-1}$.)

In case (i), since $q_{*}' \in \text{int}(G_{p})$, there is a $\mu > 0$ such that $\overline{B}_{\mu}(q_{*}') \cap \mathbb{R}^{d-1} \subseteq G_{p}$.  Thus, if $\epsilon < \mu/2$, then $g^{\epsilon}_{\nu}(q') = \varphi^{*}(e)$ for each $q' \in \overline{B}_{\mu/2}(q_{*}') \cap \mathbb{R}^{d-1}$.  In particular, for any $\epsilon < \mu/2$,
	\begin{equation*}
		\psi_{\nu}^{\epsilon}(q_{*}) = 1 = \psi_{\nu}(q_{*}),
	\end{equation*}
which implies $\psi_{\nu}^{\epsilon}(x_{*}) = \psi_{\nu}(x_{*})$ for all $\epsilon \in (0,\mu/2)$, stronger than needed in \eqref{E: parabola estimate thing}.

To complete the proof, it remains to consider case (ii).  In this case, $q_{*}' \in \partial G_{p}$ so the convexity of $G_{p}$ implies the existence of a $p' \in \mathbb{R}^{d-1}$ such that 
	\begin{equation} \label{E: supporting hyperplane finally}
		\langle p', q' \rangle \leq \langle p', q'_{*} \rangle \quad \text{for each} \quad q' \in G_{p}.
	\end{equation}

Considering $g_{\nu}^{\epsilon}$ and Taylor expanding the function $r \mapsto \sqrt{\nu^{2} - r}$ near $r = 0$, one finds, for all sufficiently small $\epsilon$,
	\begin{align*}
		g_{\nu}^{\epsilon}(q_{*}') &= \varphi^{*}(e) - \nu + \int_{B_{1}} \sqrt{\nu^{2} - \text{dist}(q_{*}' + \epsilon y', G_{p})^{2}} \rho(y') \, dy' \\
			&\geq \varphi^{*}(e) - \frac{1}{4} \nu^{-1} \int_{B_{1}} \text{dist}(q_{*}' + \epsilon y',G_{p})^{2} \rho(y') \, dy' \\
			&= \varphi^{*}(e) - \frac{1}{4} \nu^{-1} \epsilon^{2} \int_{B_{1}} \left[ \epsilon^{-1} \text{dist}(q_{*}' + \epsilon y', G_{p}) \right]^{2} \rho(y') \, dy'.
	\end{align*}
At this stage, it is useful to note that 
	\begin{align} \label{E: another blowup argument}
		B(q_{*}') := \liminf_{\epsilon \to 0^{+}} \int_{B_{1}} \left[ \epsilon^{-1} \text{dist}(q_{*}' + \epsilon y', G_{p}) \right]^{2} \rho(y') \, dy' > 0.
	\end{align}
Assuming \eqref{E: another blowup argument} for the moment, one deduces that, for any $\epsilon > 0$ small enough,
	\begin{equation*}
		g_{\nu}^{\epsilon}(q_{*}') \geq \varphi^{*}(e) - \frac{1}{2} \nu^{-1} B(q_{*}') \epsilon^{2}.
	\end{equation*}
Since $q_{*} \in \partial \varphi^{*}(p)$,  the duality identity \eqref{E: subdifferential basic identity dual} implies $\langle q_{*}, e \rangle = \varphi^{*}(e)$, hence 
	\begin{equation*}
		g_{\nu}^{\epsilon}\left( q_{*}' \right) \geq \varphi^{*}(e) \left( 1 - \frac{B(q_{*}') \epsilon^{2}}{2 \nu \varphi^{*}(e)} \right) = \langle q_{*}, e \rangle \left(1 - \frac{B(q_{*}') \epsilon^{2}}{2 \nu \varphi^{*}(e)} \right)
	\end{equation*}
Since $\lim_{\epsilon \to 0^{+}} Dg_{\nu}^{\epsilon}(q_{*}') = Dg_{\nu}(q_{*}') = 0$ by Proposition \ref{P: gradient vanishing ack ack}, it follows that one can fix an $\eta > 0$ such that, for all $\epsilon > 0$ small enough,
	\begin{align*}
		g_{\nu}^{\epsilon} \left( \frac{q_{*}'}{1 + \eta \epsilon^{2}} \right) \geq \frac{\langle q_{*}, e \rangle}{1 + \eta \epsilon^{2}}.
	\end{align*}
In particular, as soon as $\epsilon$ is small enough, one can invoke Proposition \ref{P: crazy monotonicity argument} to deduce that $\psi_{\nu}^{\epsilon}(q_{*}) \leq 1 + \eta \epsilon^{2}$, yielding the desired estimate \eqref{E: parabola estimate thing} by homogeneity.

To check \eqref{E: another blowup argument}, let $H_{p'} = \{x' \in \mathbb{R}^{d-1} \, \mid \, \langle p', x' \rangle \geq 0\}$ and use \eqref{E: supporting hyperplane finally} to obtain
	\begin{equation*}
		\text{dist}(x',G_{p}) \geq \text{dist}(x',q_{*}' - H_{p'}).
	\end{equation*}
By homogeneity and \eqref{E: symmetry mollifier}, this leads to
	\begin{align*}
		B(q_{*}') \geq \lim_{\epsilon \to 0^{+}} \int_{B_{1}} \left[\epsilon^{-1} \text{dist}(\epsilon y', -H_{p'}) \right]^{2} \rho(y') \, dy' = \int_{B_{1}} \text{dist}(y',-H_{p'})^{2} \rho(y') \, dy' > 0.
	\end{align*}

Suppose that $x \in \{\psi^{\epsilon}_{\nu} < + \infty\} \cap \{\psi_{\zeta}< + \infty\}$ and assume that \eqref{E: smallness condition necessary assumption} holds for some $\delta > 0$ to be determined below.  As in Section \ref{S: c11 setting}, write $x = \langle x, e \rangle e + x'$, where $x' \in \{e\}^{\perp} \simeq \mathbb{R}^{d-1}$.  

To lighten the notation, define $C, \gamma, \ell > 0$ by
	\begin{equation*}
		C = \psi^{\epsilon}_{\nu}(x), \quad \gamma = \psi^{\epsilon}_{\nu}(x)^{-1} \psi_{\zeta}(x), \quad \ell = \text{dist}\left(\frac{x'}{\psi^{\epsilon}_{\nu}(x)},G_{p}\right).
	\end{equation*}
Note, in particular, that $\psi_{\zeta}(x) = \gamma C$. By Definition \ref{D: admissible}, $\psi^{\epsilon}_{\nu} \geq \psi_{\zeta}$ and, thus, $\gamma \leq 1$.

By Taylor expanding the function $r \mapsto \sqrt{\nu^{2} - r}$ at $r = 0$, we have, for $\delta > 0$ small enough,
	\begin{align} \label{E: definition of delta in the appendix}
		g_{\nu}^{\epsilon}(y') \leq g_{\nu}(y') \leq g_{\zeta}(y') -  \frac{1}{4} (\nu^{-1} - \zeta^{-1}) \text{dist}(y',G_{p})^{2} \quad \text{if} \quad \text{dist}(y',G_{p}) \leq \delta.
	\end{align}
This condition fixes $\delta$ from now on.

In view of \eqref{E: smallness condition necessary assumption}, the key property \eqref{E : graph property ack ack ack} of $\psi_{\nu}^{\epsilon}$, and the definition of $C$ and $\ell$, one can write
	\begin{align} \label{E: thankful}
		\frac{x_{d}}{C} = g_{\nu}^{\epsilon} \left( \frac{x'}{C} \right) \leq g_{\zeta} \left(\frac{x'}{C}\right) - \frac{1}{4} (\nu^{-1} - \zeta^{-1}) \ell^{2}.	\end{align}
At the same time, by definition of $\gamma$ and $M_{\zeta}(\delta)$,
	\begin{align*}
			\frac{x_{d}}{\gamma C} = g_{\zeta}\left(\frac{x'}{\gamma C}\right) \geq g_{\zeta} \left(\frac{x'}{C} \right) - M_{\zeta}(\delta) \left\|\frac{x'}{\gamma C} - \frac{x'}{C} \right\| = g_{\zeta}\left(\frac{x'}{C}\right) - M_{\zeta}(\delta) \left(\frac{1}{\gamma} - 1\right) \left\|\frac{x'}{C}\right\|.
	\end{align*}

Combining this with the bound \eqref{E: thankful}, one deduces that
	\begin{align*}
		\frac{x_{d}}{\gamma C} &\geq \frac{x_{d}}{C} + \frac{1}{4} (\nu^{-1} - \zeta^{-1}) \ell^{2} - M_{\zeta}(\delta) \left\| \frac{x'}{C} \right\| \left( \frac{1}{\gamma} - 1 \right).
	\end{align*}
After rearrangement, this becomes
	\begin{align*}
		\frac{1}{4} (\nu^{-1} - \zeta^{-1}) \ell^{2} &\leq \left(\frac{1}{\gamma} - 1 \right) \left(\frac{x_{d}}{C} + M_{\zeta}(\delta) \left\| \frac{x'}{C} \right\| \right) \\
			&= \left(\frac{1}{\gamma} - 1 \right) \left(g_{\nu}^{\epsilon} \left( \frac{x'}{C} \right) + M_{\zeta}(\delta) \left\| \frac{x'}{C} \right\| \right).
	\end{align*}

Reinterpreting this last inequality as a lower bound on $\gamma^{-1} - 1$, one arrives at the following lower bound on $\psi^{\epsilon}_{\nu}(x)$:
	\begin{align*}
		\psi^{\epsilon}_{\nu}(x) = C &= \psi_{\zeta}(x) + (1 - \gamma)C \\
			&\geq \psi_{\zeta}(x) + \frac{1}{4} (\nu^{-1} - \zeta^{-1}) \gamma \psi^{\epsilon}_{\nu}(x) \ell^{2} \left( g^{\epsilon}_{\nu}\left( \frac{x'}{C}\right) + M_{\zeta}(\delta) \left\| \frac{x'}{C}\right\|\right)^{-1} \\
			&= \psi_{\zeta}(x) \left[ 1 + \frac{1}{4} (\nu^{-1} - \zeta^{-1}) \ell^{2} \left( g^{\epsilon}_{\nu} \left( \frac{x'}{C} \right) + M_{\zeta}(\delta) \left\| \frac{x'}{C}\right\|\right)^{-1} \right]
	\end{align*}
Finally, observe that $C^{-1} \|x'\| \leq R(\delta)$ and 
	\begin{align*}
		\max \left\{ g_{\nu}^{\epsilon}(q') \, \mid \, \text{dist}(q',G) \leq \delta \right\} \leq \max \left\{ g_{\nu}(q') \, \mid \, \text{dist}(q',G) \leq \delta \right\} &= \varphi^{*}(e),
	\end{align*}
hence \eqref{E: main thing appendix smallness} holds with the constant $A$ given by 
	\begin{align*}
		A= \frac{1}{4} (\nu^{-1} - \zeta^{-1}) \left( \varphi^{*}(e) + M_{\zeta}(\delta) R(\delta) \right)^{-1}.
	\end{align*}
